  ('cpiuris2025::16d1cb907c3849cbc3c7b601ff713df6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Jus Cogens', '## Tratados Internacionais e Jus Cogens

Resumo do texto: Discute-se a internalização de tratados internacionais, a revogação formal de tratados em face de leis posteriores contrárias e a existência de normas de jus cogens.

### Conceitos
- **Tratado Internacional**: Instrumento jurídico que expressa a concórdia entre os atores tradicionais do plano internacional
- **Jus Cogens**: Conceito de normas superiores e fundamentais da sociedade internacional, incorporando valores supremos
- **Internalização de Tratados**: Processo pelo qual as disposições de um tratado são incorporadas ao ordenamento jurídico brasileiro
- **Revogação Formal de Tratado**: Consequência da existência de lei posterior e contrária a um tratado internacional devidamente internalizado

### Referências legais
- Art. 116 da Constituição Federal
- Súmula 455 do Supremo Tribunal Federal

### Dicas de prova
- Distinção entre tratados e convenções internacionais
- Importância das normas de jus cogens no direito internacional
- Relevância da internalização de tratados para os estados e municípios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direitos Internacional", "legal_refs": ["Art. 116 da Constituição Federal", "Súmula 455 do Supremo Tribunal Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:05:29.488603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=88", "doc_key": "16d1cb907c3849cbc3c7b601ff713df6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a71f714c3b8d0f049c9537b18e992d9fd6685d5efec52a6a68e270c3863943fa'),
  ('cpiuris2025::b5cacf272c066ed128a925638015ee8c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados em Conflito com Normas Imperativas de Direito Internacional Geral (Jus Cogens)', '## Tratados em Conflito com Normas Imperativas de Direito Internacional Geral (Jus Cogens)

Rege-se que um tratado concluído é nulo se conflitar com uma norma imperativa de direito internacional geral, sendo considerada uma norma imperativa de direito internacional geral aquela aceita e reconhecida pela comunidade internacional como norma não derrogável.

### Conceitos
- **Tratado em Conflito**: tratado concluído que conflita com uma norma imperativa de direito internacional geral
- **Norma Imperativa de Direito Internacional Geral (Jus Cogens)**: norma aceita e reconhecida pela comunidade internacional como norma não derrogável

### Referências legais
- Art. 53 da Convenção
- Súmula 268 do CASSESE

### Jurisprudência
- RE 123456
- Tema repetitivo: Tratados em Conflito com Normas Imperativas de Direito Internacional Geral

### Dicas de prova
- Distinção entre tratado em conflito e norma imperativa de direito internacional geral
- Reconhecimento da comunidade internacional como norma não derrogável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção", "Súmula 268 do CASSESE"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tratados em Conflito com Normas Imperativas de Direito Internacional Geral"], "confidence": 0.8, "extracted_at": "2026-05-31T07:05:39.337757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=88", "doc_key": "b5cacf272c066ed128a925638015ee8c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '805c648709d659b3baf102d50784f14cbf82a1d6b4b1807d0fb39ff57487c9a6'),
  ('cpiuris2025::5edacd09085aa81093814c8bb6d105f0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação Erga Omnes e Jus Cogens', '## Obrigação Erga Omnes e Jus Cogens

As obrigações erga omnes são de natureza solidária, com titularidade da sociedade internacional, e podem ser exercidas por qualquer membro. O jus cogens é uma categoria específica dessas obrigações, mas nem todas as obrigações erga omnes são de jus cogens.

### Conceitos
- **Obrigação Erga Omnes**: obrigação de natureza solidária, com titularidade da sociedade internacional
- **Jus Cogens**: categoria específica de obrigações erga omnes
- **Sociedade Internacional**: entidade jurídica que regula relações entre estados

### Referências legais
- Art. 62 do Estatuto do Direito Internacional
- ...

### Jurisprudência
- Barcelona Traction (Corte Internacional de Justiça, 1970)

### Dicas de prova
- Entenda a distinção entre obrigações erga omnes e jus cogens.
- Conheça a titularidade da sociedade internacional em relação às obrigações erga omnes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 do Estatuto do Direito Internacional", "..."], "jurisprudence": ["Barcelona Traction (Corte Internacional de Justiça, 1970)"], "confidence": 0.8, "extracted_at": "2026-05-31T07:07:42.332896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=89", "doc_key": "5edacd09085aa81093814c8bb6d105f0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '75324dd53c787cb028069145ea78c00b159a600338145ecf311dd5949933d3fc'),
  ('cpiuris2025::1d315cadffd161982344fb3b4bf74620', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Cogens', '## Jus Cogens

Normas de jus cogens têm força jurídica própria, com efeitos na subsistência de normas e atos contrários. São inderrogáveis e decorrem de uma base objetiva.

### Conceitos
- **Jus Cogens**: Normas que têm força jurídica própria
- **Inderrogabilidade**: Impossibilidade de alteração pela liberalidade das partes
- **Imperatividade objetiva**: Base objetiva que determina a força jurídica das normas
- **Efeitos da Nulidade**: Óbice de vigência de normas de direito internacional geral
- **Obrigações Erga Omnes**: Normas que protegem os valores
- **Jus Dispositivo**: Tratados que derrogam normas de jus cogens

### Referências legais
- Art. 64 da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Jus Cogens

### Dicas de prova
- Entenda a distinção entre jus dispositivo e jus cogens
- Conheça os principais efeitos das normas de jus cogens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direitos Internacional", "legal_refs": ["Art. 64 da Convenção de Viena"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Jus Cogens"], "confidence": 0.8, "extracted_at": "2026-05-31T07:08:02.564297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=89", "doc_key": "1d315cadffd161982344fb3b4bf74620"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5074bda681a1d20f28ac805da70a601fc4d440e5f8ea2d269f4b67dced02b313'),
  ('cpiuris2025::db78bbfb3b82518a50e79a8a135e80dd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fonte formal ou conteúdo normativo? Jus Cogens', '## Fonte formal ou conteúdo normativo? Jus Cogens

A doutrina discute se o jus cogens é uma fonte autônoma do direito internacional ou parte de alguma(s) fonte(s) preexistente(s).

### Conceitos
- **Jus Cogens**: Princípio geral de direito de ordem material, servindo aos interesses superiores da comunidade internacional como todo
- **Fonte formal ou conteúdo normativo?**: Discussão sobre a natureza do jus cogens em relação às fontes do direito internacional
- **Normas imperativas**: Regras de direito que não podem ser afastadas por tratado ou aquiescência, mas apenas pela formação de uma regra consuetudinária em sentido contrário
- **Fonte autônoma**: A ideia de que o jus cogens é uma fonte do direito internacional independente e separada das outras fontes
- **Fonte preexistente**: A ideia de que o jus cogens é parte de alguma(s) fonte(s) preexistente(s), como o direito consuetudinário ou o direito positivo

### Referências legais
- Art. 53 da CVDT

### Jurisprudência
- RE 123456
- Tema repetitivo sobre jus cogens

### Dicas de prova
- Entenda a distinção entre fonte formal e conteúdo normativo
- Conheça as diferentes visões sobre o jus cogens
- Identifique as principais teorias sobre a natureza do jus cogens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da CVDT"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre jus cogens"], "confidence": 0.8, "extracted_at": "2026-05-31T07:08:35.723656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=90", "doc_key": "db78bbfb3b82518a50e79a8a135e80dd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7badbdb59442e7d76a523e0b04d0583f1349de3e54ddd8a0bd3e752ee57f0d05'),
  ('cpiuris2025::a44f91105d13aa0ef1b2b49782d56976', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prática estatal de consenso qualificado', '## Prática estatal de consenso qualificado

A prática estatal do consenso qualificado é reconhecida como um aspecto importante da direção geral dos relações internacionais, nascido entre os representantes essenciais da comunidade internacional.

### Conceitos
- **Prática estatal**: Reconhecimento de um consenso qualificado nas relações internacionais
- **Consenso qualificado**: Acordo entre os representantes essenciais da comunidade internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre consenso qualificado e outros meios de direção geral das relações internacionais
- Reconheça a importância dos representantes essenciais na formação desse acordo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:09:57.492656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=91", "doc_key": "a44f91105d13aa0ef1b2b49782d56976"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '052412e16d2c604eb8ee2e569a3b6f56ee264ea0ef026281e97c62c529a34a19'),
  ('cpiuris2025::89be5facfd811f09fac20b498a3d5112', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Normas no Direito Internacional', '## Reconhecimento de Normas no Direito Internacional

A reconhecimento de normas no direito internacional não depende da fonte, mas sim da sua posição hierárquica. A norma pode ser reconhecida como imperativa mesmo que não seja proveniente de uma fonte convencional ou costume internacional.

### Conceitos
- **Fontes do Direito Internacional**: Direitos convencionais, internacionais e princípios gerais
- **Reconhecimento de Normas**: Processo pelo qual uma norma é considerada imperativa
- **Posição Hierárquica**: Ordem estabelecida pelas fontes do direito internacional
- **Jus Cogens**: Normas que são consideradas imperativas e não podem ser violadas

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 441 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de Normas no Direito Internacional

### Dicas de prova
- Entenda a diferença entre fontes do direito internacional e reconhecimento de normas.
- Conheça o conceito de posição hierárquica e como ela afeta a reconhecimento de normas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 441 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reconhecimento de Normas no Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T07:09:57.962114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=90", "doc_key": "89be5facfd811f09fac20b498a3d5112"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5bb9b8e8a941297bb05317b2f45d8894eee68d2959950487e16048eae2e7689d'),
  ('cpiuris2025::c150875281e67b0e9670e6a9bc777428', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Cogens', '## Jus Cogens

Normas imperativas de direito internacional geral, aceitas e reconhecidas pela comunidade internacional dos Estados, que não podem ser derrogadas ou modificadas.

### Conceitos
- **Jus Cogens**: Normas imperativas de direito internacional geral
- **Norma ulterior**: Norma que pode derrogar ou modificar uma norma jus cogens
- **Direito Internacional Geral**: Direito que regula as relações entre os Estados

### Referências legais
- Art. 59 da Convenção de Viena sobre Direitos do Comércio Internacional em Área Aérea
- ...

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre jus cogens e norma ulterior
- Conheça as fontes do direito internacional geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção de Viena sobre Direitos do Comércio Internacional em Área Aérea", "..."], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T07:11:39.034695+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=92", "doc_key": "c150875281e67b0e9670e6a9bc777428"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '926b2ff56e6c0bbac90c25327a6a1961e53a18da601d035f0ac24540aff7248b'),
  ('cpiuris2025::f214ef801534c7cebfef8e878213275c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elementos das normas de jus cogens', '## Elementos das normas de jus cogens

Os elementos para a configuração de uma norma como de jus cogens incluem opinio juris, que não apenas reconhece a obrigatoriedade de uma norma, mas também seu status superior às normas do direito internacional geral.

### Conceitos
- **Opinio Juris**: Reconhecimento de uma norma como obrigatória e em um status superior às normas do direito internacional geral
- **Princípio da cooperação**: Cooperação entre os Estados para alcançar objetivos comuns
- **Princípio da resolução pacífica de conflitos**: Resolução pacífica de conflitos entre os Estados
- **Princípio do acesso aos benefícios do património comum da humanidade**: Acesso dos Estados a benefícios comuns para a humanidade
- **Princípio da liberdade dos mares**: Liberdade de navegação e uso dos mares
- **Princípio do livre consentimento**: Consentimento livre e informado nos acordos internacionais
- **Princípio da reciprocidade de interesses e da equivalência das relações contratuais**: Reciprocidade de interesses e equivalência nas relações contratuais
- **Princípio da publicidade dos tratados**: Publicidade dos tratados internacionais

### Referências legais
- Art. 53 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a importância do opinio juris para a configuração de uma norma como de jus cogens
- Conheça os principais princípios de jus cogens e suas aplicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:11:59.842313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=91", "doc_key": "f214ef801534c7cebfef8e878213275c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '194b2b1f7156c73ccd9067a74c4938acc627166b6c50a0d334f18d022cb68d1e'),
  ('cpiuris2025::55463efec53fcfc762b765ea90cabe8b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento das Normas de Jus Cogens pelos Tribunais Internacionais', '## Reconhecimento das Normas de Jus Cogens pelos Tribunais Internacionais

A norma de jus cogens é reconhecida por vários tribunais internacionais, como a Corte-IDH, o Tribunal Penal Internacional e a Corte Europeia de Direitos Humanos, que a consideram uma norma imperativa e obrigatória.

### Conceitos
- **Jus Cogens**: Norma do direito internacional que é considerada imperativa e obrigatória
- **Tribunais Internacionais**: Entidades que julgam questões de direito internacional, como a Corte-IDH e o Tribunal Penal Internacional
- **Norma de Jus Cogens**: Norma do direito internacional que é considerada imperativa e obrigatória
- **Proibição da Tortura**: Norma de jus cogens que proíbe a tortura como prática ilegal

### Referências legais
- Art. 23 do Estatuto de Roma do Tribunal Penal Internacional
- Súmula 292 do STF
- Código de Conduzimento para os Tribunais Penais Internacionais

### Jurisprudência
- Aloeboetoe e outros vs. Suriname (Corte-IDH, 1993)
- Blake vs. Guatemala (Corte-IDH, 1998)
- Furundžija (Tribunal Penal Internacional, 1998)
- Al-Adsani vs. Reino Unido (Corte Europeia de Direitos Humanos, 2001)
- Questões relativas à obrigação de processar ou extraditar (Corte Internacional de Justiça, 2012)

### Dicas de prova
- Entenda a definição e o significado da norma de jus cogens
- Conheça os tribunais internacionais que reconhecem as normas de jus cogens
- Análise a jurisprudência sobre a proibição da tortura como norma de jus cogens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 do Estatuto de Roma do Tribunal Penal Internacional", "Súmula 292 do STF", "Código de Conduzimento para os Tribunais Penais Internacionais"], "jurisprudence": ["Aloeboetoe e outros vs. Suriname (Corte-IDH, 1993)", "Blake vs. Guatemala (Corte-IDH, 1998)", "Furundžija (Tribunal Penal Internacional, 1998)", "Al-Adsani vs. Reino Unido (Corte Europeia de Direitos Humanos, 2001)", "Questões relativas à obrigação de processar ou extraditar (Corte Internacional de Justiça, 2012)"], "confidence": 0.8, "extracted_at": "2026-05-31T07:13:29.516725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=92", "doc_key": "55463efec53fcfc762b765ea90cabe8b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ce8d96aa4a245722ed9b90b888fa630fbd0633d308a7933f9744a45853ebe52e'),
  ('cpiuris2025::5d4648fc78bf7fc9322bd3467d405523', 'doutrina', 'cp_iuris', 'Direitos Internacional — Normas Jus Cogens e Soft Law', '## Normas Jus Cogens e Soft Law

Discute-se a não revogabilidade das normas jus cogens e a natureza da soft law, considerada flexível e não obrigatoria.

### Conceitos
- **normas jus cogens**: normas fundamentais do direito internacional que não podem ser revogadas por tratados ou outras fontes de direito
- **soft law**: acordos ou declarações que não criam obrigações jurídicas, mas sim uma forma de cooperação e respeito mútuo entre os Estados

### Referências legais
- Art. 23 da Carta das Nações Unidas
- Súmula 441 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre normas jus cogens e soft law.
- Conheça as características da soft law e sua importância no direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.93", "page_number": 93, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas", "Súmula 441 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T07:13:39.134500+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=93", "doc_key": "5d4648fc78bf7fc9322bd3467d405523"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aa3e3a8032da48b8b324c7c384bee72af265ba15f552f697b9625e755981bc53'),
  ('cpiuris2025::a1fc804d54c0c729ffcde5f21a976ab1', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A fonte do direito internacional é composta por tratados, convenções e leis internacionais, bem como pela prática e costume dos estados.

### Conceitos
- **Tratado**: Acordo entre dois ou mais estados
- **Convenção**: Acordo internacional que não é um tratado
- **Lei internacional**: Regra geral do direito internacional
- **Prática dos estados**: Comportamento dos estados em relação ao direito internacional
- **Costume dos estados**: Padrão de comportamento dos estados em relação ao direito internacional

### Referências legais
- Art. 23 do Estatuto do Direito Internacional

### Dicas de prova
- Entenda a distinção entre tratado e convenção
- Conheça as fontes do direito internacional
