  ('cpiuris2025::22283fd6089ed34ea416fba549b47d2e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Internacional e Conceito de Direito Internacional', '## Personalidade Internacional e Conceito de Direito Internacional

O texto discute a posição que rejeita o conceito de personalidade internacional, estipulando que todos os atores efetivos das relações internacionais são relevantes para o sistema.

### Conceitos
- **Personalidade Internacional**: Conceito jurídico que atribui personalidade ao Estado ou à entidade internacional
- **Ator em particular**: Entidade individual que atua no âmbito internacional

### Referências legais
- Art. 13 da Convenção de Viena sobre Direitos do Comércio Internacional

### Dicas de prova
- Distinção entre personalidade internacional e ator em particular
- Entendimento do conceito de direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 da Convenção de Viena sobre Direitos do Comércio Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:15:05.736708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=96", "doc_key": "22283fd6089ed34ea416fba549b47d2e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '56640d5673ae2b1794543aa4f82b0422f7ee99e776a0722f9bebbf48cd69b5e8'),
  ('cpiuris2025::1869d8f2b95a17d539899c38c356d9b4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceitos do Direito Internacional', '## Conceitos do Direito Internacional

Descreve as principais concepções sobre o Direito Internacional, incluindo teoria dualista, positivismo moderno e realista.

### Conceitos
- **Teoria Dualista**: Considera que existem ordenamentos distintos com sujeitos distintos
- **Positivismo Moderno**: Só reconhece pessoas jurídicas de Direito Internacional como atores
- **Realismo**: Abarca toda a realidade das relações jurídicas internacionais, incluindo responsabilização individual e acesso a órgãos internacionais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Opinião Consultiva sobre a Reparação de danos sofridos a serviço das Nações Unidas, de 11 de abril de 1949

### Dicas de prova
- Entenda a distinção entre teoria dualista e positivismo moderno
- Conheça as limitações da realidade sociológica
- Aprenda com a Opinião Consultiva sobre a Reparação de danos sofridos a serviço das Nações Unidas, de 11 de abril de 1949', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Opinião Consultiva sobre a Reparação de danos sofridos a serviço das Nações Unidas, de 11 de abril de 1949"], "confidence": 0.8, "extracted_at": "2026-05-31T07:15:59.005801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=97", "doc_key": "1869d8f2b95a17d539899c38c356d9b4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5d608ace4eae8774dee31265d4c6826c09761bf928139a98b47ce278db2b7080'),
  ('cpiuris2025::4547f5491d3945f03632424dadfefa67', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

As posições sobre a personalidade jurídica internacional são polêmicas e variadas, abrangendo positivistas, reconhecimento, individualista, formal e atores.

### Conceitos
- **Positivismo**: Teoria que considera a sociedade internacional como uma sociedade interestatal
- **Reconhecimento**: Conferir personalidade internacional a Estados e outros entes, com status de pessoa do Direito Internacional originária
- **Individualismo**: Posição que considera apenas os indivíduos como sujeitos do Direito Internacional
- **Formalismo**: Teoria que não confere presunção de personalidade jurídica a ninguém, deixando-a para ser estabelecida por princípios gerais de interpretação
- **Atores**: Nomenclatura utilizada para descrever os entes que atuam nas Relações Internacionais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre positivismo e reconhecimento
- Identifique a posição individualista e sua importância
- Conheça o formalismo e como ele afeta a personalidade jurídica internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:16:18.794578+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=96", "doc_key": "4547f5491d3945f03632424dadfefa67"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fc2a505dadcb82333d98afd717b366f57e3922b0fa75739fa917c9ec1316f64e'),
  ('cpiuris2025::c271e4d6359b23fe34e8e7185fed1f0b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

A personalidade jurídica internacional é um conceito controverso, com diferentes abordagens e critérios. A teoria formalista é majoritária, mas não há um único critério para definir a personalidade jurídica internacional.

### Conceitos
- **Personalidade Jurídica Internacional**: Conceito que define os direitos e deveres de um Estado ou entidade no plano internacional.
- **Formalismo**: Abordagem que considera a personalidade jurídica internacional como uma entidade com direitos e deveres definidos por pressupostos jurídicos.
- **Funcionalismo**: Abordagem que considera a personalidade jurídica internacional como um sistema aberto de pessoas, com uma perspectiva dinâmica da subjetividade internacional.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre formalismo e funcionalismo para responder às questões.
- Conheça as principais abordagens para definir a personalidade jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:17:16.551829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=97", "doc_key": "c271e4d6359b23fe34e8e7185fed1f0b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b6d546aca6598d7d622570e71f4e90fdb9a6300b227f320e007dcd9f90b2076b'),
  ('cpiuris2025::c94c1d5a10f8622fb214115248e414f1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Internacional e Funcionalidade', '## Personalidade Internacional e Funcionalidade

A personalidade internacional de um ente não estável é definida pela sua funcionalidade, ou seja, quando atua no plano jurídico internacional. Isso significa que a personalidade internacional pode não coincidir com a personalidade jurídica interna.

### Conceitos
- **Personalidade Internacional**: definição curta
- **Funcionalidade**: funcionalidade como critério para definição de sujeitos do Direito Internacional não estatais
- **Capacidade Jurídica Internacional**: poder variar conforme a pessoa em análise
- **Vinculação com as Normas do Direito Internacional**: ligação direta à normas do Direito Internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a relação entre personalidade internacional e funcionalidade.
- Distinção entre personalidade jurídica interna e capacidade jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:17:50.025581+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=98", "doc_key": "c94c1d5a10f8622fb214115248e414f1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8257fa939804bf56f5d55895049ffc8872d337798e930e9e111ad169d87a1465'),
  ('cpiuris2025::4cdbb7ab016f306c8f5d16a793e7facb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

A definição da personalidade jurídica internacional é objeto de debate entre os autores, com Malcolm N. Shaw e Ian Brownlie apresentando conceituações diferentes. A Corte Internacional de Justiça considerou que a ONU não tem personalidade jurídica expressa na sua Carta constitutiva.

### Conceitos
- **Personalidade Jurídica Internacional**: Característica do direito internacional que confere aos Estados ou organizações internacionais capacidade de exercer direitos e obrigações no plano internacional.
- **Capacidade de Celebrar Tratados**: Requisito para a definição da personalidade jurídica internacional, pois é necessário que os Estados ou organizações internacionais tenham capacidade de celebrar tratados válidos no plano internacional.
- **Detenção de Privilégios e Imunidades**: Requisito para a definição da personalidade jurídica internacional, pois é necessário que os Estados ou organizações internacionais tenham privilégios e imunidades nas jurisdições nacionais.
- **Posição de Destinatários das Normas**: Característica da definição da personalidade jurídica internacional, pois é necessário que os Estados ou organizações internacionais sejam destinatários das normas do Direito Internacional.
- **Capacidade de Operar no Plano Internacional**: Requisito para a definição da personalidade jurídica internacional, pois é necessário que os Estados ou organizações internacionais tenham capacidade de operar no plano internacional.
- **Aquisição de Personalidade Internacional**: Proceso pelo qual um Estado ou organização internacional adquire capacidade de exercer direitos e obrigações no plano internacional.
- **Funções e Direitos Internacionais**: Direitos e responsabilidades que os Estados ou organizações internacionais têm em relação às outras entidades internacionais.

### Referências legais
- Art. 6 da Carta das Nações Unidas

### Jurisprudência
- Opinião Consultiva da Corte Internacional de Justiça, Reparação de danos sofridos a serviço das Nações Unidas

### Dicas de prova
- Entenda a definição de personalidade jurídica internacional e os requisitos para sua formação.
- Conheça as diferentes conceituações apresentadas pelos autores sobre a personalidade jurídica internacional.
- Análise da opinião consultiva da Corte Internacional de Justiça sobre a ONU.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 da Carta das Nações Unidas"], "jurisprudence": ["Opinião Consultiva da Corte Internacional de Justiça, Reparação de danos sofridos a serviço das Nações Unidas"], "confidence": 0.8, "extracted_at": "2026-05-31T07:18:25.695066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=98", "doc_key": "4cdbb7ab016f306c8f5d16a793e7facb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '259fe56a22c1736566cfa456d6838adf00cdc14b9a6776214271016468bac075'),
  ('cpiuris2025::32e8e084804f62c2a46ff1b1c83f82f6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificações dos sujeitos do Direito Internacional', '## Classificações dos sujeitos do Direito Internacional

São classificados os sujeitos do Direito Internacional considerando sua origem, capacidade jurídica, base territorial, natureza jurídica, finalidades, reconhecimento e posição nas relações jurídicas internacionais.

### Conceitos
- **Sujeitos não estatais**: Organizações internacionais e indivíduos
- **Natureza jurídica**: Estados, organizações governamentais internacionais, pessoas jurídicas, indivíduos e blocos regionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre sujeitos estatais e não estatais no Direito Internacional.
- Reconheça as diferentes classificações dos sujeitos do Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:20:12.076837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=99", "doc_key": "32e8e084804f62c2a46ff1b1c83f82f6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3978016a9b9bcdf311d426de649e03fe905fa4779839a56ee3b25ceeeac025c0'),
  ('cpiuris2025::32dafa3c80d72a903dcc0fd51df2e403', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sujeito do Direito Internacional', '## Sujeito do Direito Internacional

A maioria da doutrina considera que os Estados, Organizações Internacionais e indivíduos são detentores de personalidade internacional. Há controvérsas sobre a inclusão de pessoas jurídicas e ONGs.

### Conceitos
- **Personalidade Internacional**: status jurídico que confere direitos e obrigações internacionais
- **Sujeito do Direito Internacional**: entidade capaz de ser responsável por atos internacionais
- **Organizações Internacionais**: entidades governamentais ou não governamentais que operam em escala internacional
- **Pessoas Jurídicas**: entidades jurídicas privadas que podem ter personalidade internacional
- **ONGs (Organizações Não-Governamentais)**: entidades não governamentais que podem ter influência em questões internacionais

### Referências legais
- Art. 5 da Convenção de Viena sobre o Direito do Espaço Aéreo
- ...

### Jurisprudência
- Caso Bernadotte (Corte Internacional de Justiça)

### Dicas de prova
- Entenda a distinção entre personalidade internacional e sujeito do direito internacional
- Conheça as organizações internacionais e suas características
- Avalie a inclusão de pessoas jurídicas e ONGs como sujeitos do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Convenção de Viena sobre o Direito do Espaço Aéreo", "..."], "jurisprudence": ["Caso Bernadotte (Corte Internacional de Justiça)"], "confidence": 0.8, "extracted_at": "2026-05-31T07:21:09.510154+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=99", "doc_key": "32dafa3c80d72a903dcc0fd51df2e403"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7944176ccf5eb514acb67d2c6b536a85a759a0db21bf4f5c37813c2db497e97c'),
  ('cpiuris2025::a2cdc609a097ab89e925277dba607a98', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sujeitos do Direito Internacional', '## Sujeitos do Direito Internacional

O texto destaca a importância dos sujeitos no Direito Internacional, destacando sua origem, capacidade jurídica, base territorial e posição na relação jurídica internacional.

### Conceitos
- **Sujeito originário**: Estado
- **Sujeito derivado**: outros sujeitos reconhecidos pelos Estados como pessoas jurídicas do Direito Internacional
- **Capacidade jurídica plena**: Estados que podem atuar de forma irrestrita em âmbito internacional
- **Capacidade jurídica restrita**: outros sujeitos com limitações na atuação internacional
- **Base territorial**: Estados, beligerantes, estados semissoberanos e Associações de Estados
- **Sujeito ativo**: detentor de direitos no plano internacional
- **Sujeito passivo**: detentor de obrigações internacionais
- **Reconhecimento geral**: reconhecido pela generalidade dos Estados

### Referências legais
- Art. 2 da Convenção de Viena sobre o Direito do Tratado
- Súmula 441/2013 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Sujeitos do Direito Internacional

### Dicas de prova
- Entenda a distinção entre sujeitos originários e derivados.
- Conheça as diferentes formas de capacidade jurídica e base territorial.
- Identifique os sujeitos ativos e passivos no Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.100", "page_number": 100, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Convenção de Viena sobre o Direito do Tratado", "Súmula 441/2013 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Sujeitos do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T07:21:37.715916+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=100", "doc_key": "a2cdc609a097ab89e925277dba607a98"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '442a9bf3ed344fe0de247d7236437b1a3b9746160f1e422b92b2ccff6fe728b2'),
  ('cpiuris2025::eca48852e191ee0874459d2bc1295d45', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elementos constitutivos do Estado', '## Elementos constitutivos do Estado

O Estado é composto por território, povo e soberania. O território é a delimitação geográfica exclusiva do Estado, enquanto o povo é a coletividade humana que habita o território.

### Conceitos
- **Território**: delimitação geográfica exclusiva do Estado
- **Povo**: coletividade humana que habita o território de um Estado em um determinado período histórico
- **Soberania**: poder exclusivo do Estado sobre seu território

### Referências legais
- Art. 2 da Convenção Interamericana sobre os Direitos e Deveres dos Estados de 1933 (Convenção de Montevidéu)

### Jurisprudência
- Caso do Saara Ocidental, em 1975

### Dicas de prova
- Entenda a distinção entre povo, Estado e nação
- Identifique o território como elemento objetivo do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Convenção Interamericana sobre os Direitos e Deveres dos Estados de 1933 (Convenção de Montevidéu)"], "jurisprudence": ["Caso do Saara Ocidental, em 1975"], "confidence": 0.8, "extracted_at": "2026-05-31T07:22:16.859044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=101", "doc_key": "eca48852e191ee0874459d2bc1295d45"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4a21cc746ff6deeb148b2d187e9301b13f82ff71ea8a6927dde33226681e2699'),
  ('cpiuris2025::c27e79727233904b944b61094c8be664', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de nacionalidade e seus limites no direito internacional', '## Definição de nacionalidade e seus limites no direito internacional

A nacionalidade é definida como o conjunto de pessoas ligadas ao Estado por meio da nacionalidade, sendo fundamental considerar o contexto da questão em provas de concurso.

### Conceitos
- **Nacionalidade**: conjunto de pessoas ligadas ao Estado
- **Contexto da questão**: consideração fundamental em provas de concurso

### Referências legais
- Art. 13 do Convenção de Viena sobre Relações Diplomáticas

### Dicas de prova
- Perguntas que envolvem nacionalidade podem ser complexas, portanto, é importante ler o contexto da questão cuidadosamente.
- A definição de nacionalidade pode variar entre os países e é fundamental entender as diferenças.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 do Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:22:49.186546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=101", "doc_key": "c27e79727233904b944b61094c8be664"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2174d273165dd055592b91069633b33dc7236669bcb8d863e1ac2899d48d6ef3'),
  ('cpiuris2025::cda3c4c8f8487e03b06bebb8740631e1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Soberania e Elementos do Estado', '## Soberania e Elementos do Estado

A soberania é o elemento político do Estado que se divide em dimensões interna e internacional. A soberania externa/internacional refere-se à ausência de hierarquia entre os Estados na sociedade internacional, permitindo que os Estados sejam juridicamente independentes.

### Conceitos
- **Soberania**: Elemento político do Estado que se divide em dimensões interna e internacional
- **Governo**: Requisito para o Estado ser considerado pessoa de Direito Internacional
- **Finalidade**: Elemento social do Estado que se refere ao papel do Estado no desenvolvimento da sua própria história e da humanidade
- **Capacidade de entrar em relações com outros Estados**: Um dos requisitos para o Estado ser considerado pessoa de Direito Internacional, segundo a Convenção de Montevidéu

### Referências legais
- Art. 2º da Carta da ONU
- Artigo 1º da Convenção de Montevidéu

