  ('cpiuris2025::e7cecdabb9e0a2ed00bf561ee5285aca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de Estado e seus Elementos Constitutivos', '## Definição de Estado e seus Elementos Constitutivos

O texto discute a definição de Estado e os elementos constitutivos, destacando que o território não é um dos elementos necessários para o reconhecimento do Estado.

### Conceitos
- **Povo**: uma das condições necessárias para a existência de um Estado
- **Território**: não considerado elemento constitutivo do Estado
- **Liderança**: um dos elementos constitutivos do Estado, mas não o único
- **Soberania**: uma das condições necessárias para a existência de um Estado

### Referências legais
- Art. 1 da Convenção de Montevideo

### Dicas de prova
- Distinção entre povo e território
- Entendimento do conceito de soberania', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Convenção de Montevideo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:24:28.639558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=103", "doc_key": "e7cecdabb9e0a2ed00bf561ee5285aca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '22f7a9f08ea18ae451655c7dfdd201e000fa6b9bf757d43b904f5b85c2d80608'),
  ('cpiuris2025::b7b7950ed28ca8a97cfd3f7940ea6bdc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Capacidade de entrar em relações com os demais Estados', '## Capacidade de entrar em relações com os demais Estados

O texto discute o conceito de Estado falido e colapsado, bem como a capacidade dos Estados de entrar em relações internacionais. Além disso, aborda as questões de soberania e monopólio da força.

### Conceitos
- **Estado falido**: Estado que perdeu o controle de seu território e o monopólio do uso da força
- **Estado colapsado**: Estado que deixou de desenvolver o governo de fato em um território
- **Soberania**: Direito exclusivo de cada Estado de fazer as suas próprias leis e governar seu próprio território
- **Monopólio da força**: Direito do Estado de usar a força para impor sua autoridade e proteger seus interesses

### Referências legais
- Art. 4 da Carta das Nações Unidas

### Dicas de prova
- Entenda o conceito de Estado falido e colapsado
- Identifique a soberania como um direito exclusivo dos Estados
- Aprenda a distinguir entre monopólio da força e uso legítimo da força', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:24:38.707565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=103", "doc_key": "b7b7950ed28ca8a97cfd3f7940ea6bdc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '642167ddb6b293bb21d2bedc20212c8e4f11205b63631e65bbb71a6bb10a74eb'),
  ('cpiuris2025::a15f685ed5d973daaca47209a19f8e23', 'doutrina', 'cp_iuris', 'Direitos Internacional — Confederação e União de Estados', '## Confederação e União de Estados

Resumo objetivo: A confederação é uma forma de associação de Estados que permite a secessão de seus membros, enquanto a união de estados é uma forma de associação em que um só monarca reina em dois ou mais estados.

### Conceitos
- **Confederação**: Forma de associação de Estados que permite a secessão de seus membros
- **União de Estados**: Forma de associação em que um só monarca reina em dois ou mais estados
- **Dieta**: Órgão central da confederação, onde as deliberações são tomadas por unanimidade ou maioria qualificada

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre confederação e união de estados
- Leia o artigo 326 para entender melhor a União Ibérica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:26:18.370694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=104", "doc_key": "a15f685ed5d973daaca47209a19f8e23"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dc6e48a713821746611a713f6b58589d49158eaad1837bbc813ea988e60e28b9'),
  ('cpiuris2025::465814d21c0c419fd0b9cc23c700111b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de nação e Estado, elementos constitutivos do Estado', '## Conceito de nação e Estado, elementos constitutivos do Estado

A nação é uma ordem jurídica soberana com o objetivo de promover o bem-estar de um povo em um determinado território. O Estado é uma comunidade exclusivamente histórico-cultural, enquanto a nação é coincidente com o conceito de Estado, representando uma comunidade com vínculo jurídico entre seus componentes.

### Conceitos
- **Nação**: ordem jurídica soberana com objetivo de promover o bem-estar de um povo em um determinado território
- **Estado**: comunidade exclusivamente histórico-cultural, coincidente com o conceito de nação
- **Povo**: conjunto de brasileiros e estrangeiros que se encontram em território nacional, independentemente da duração do seu permanecimento
- **Soberania**: direito inalienável dos Estados à autodeterminação e à gestão de seus assuntos internos

### Referências legais
- Art. 1 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre Estado e nação, bem como os elementos constitutivos do Estado (soberania, finalidade, povo e território).
- Conheça as diferentes formas de classificação dos Estados (unitário/simples, composto por coordenação e confederação)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:26:54.928191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=104", "doc_key": "465814d21c0c419fd0b9cc23c700111b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bb6c20c573516ddb7515368da5f115197aaf357c3adbc2d7ead46ecfc463e051'),
  ('cpiuris2025::19caaaf0fbaa4d5996fafc4ef36a8b15', 'doutrina', 'cp_iuris', 'Direitos Internacional — Formas de Estado', '## Formas de Estado

Descreve as diferentes formas de Estado em relação à soberania e subordinação, incluindo Estados vassalos, clientes, satélites, exíguos, associados e divididos.

### Conceitos
- **Estado soberano**: Estado que não detém restrições no exercício dos seus poderes
- **Estados com soberania limitada**: Estados submetidos a soberania parcial ou totalmente tutelada por outro Estado
- **Vassalos**: Estados em situação intermediária entre a subordinação completa e a independência, com autonomia limitada
- **Clientes**: Estados que entregam certas funções à administração de outro Estado, mantendo a soberania interna
- **Satélites**: Estados com situação semelhante aos clientes, relacionada à União das Repúblicas Socialistas Soviéticas (URSS)
- **Exíguos**: Estados com dimensão geográfica diminuta, subordinando-se a outro Estado
- **Associados**: Estados que atingem a independência, mas não têm condições de mantê-la e estão subordinados a outros
- **Divididos ou ocupados**: Estados sujeitos a outras formas de limitação política em situação de guerra ou vício

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre soberania e subordinação
- Identifique as diferentes formas de Estado em relação à soberania', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:27:44.806098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=105", "doc_key": "19caaaf0fbaa4d5996fafc4ef36a8b15"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b7702608cb8ca8b5eafc39616b87ac7941cfcf06a6df0b755e35810ac03b2a32'),
  ('cpiuris2025::1aa784719766eade31412c19c250f35b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comunidade Britânica', '## Comunidade Britânica

A Comunidade Britânica é uma reunião de ex-colônias britânicas, não tendo personalidade jurídica própria e seus assuntos comuns são tratados por meio de conferências periódicas.

### Conceitos
- **Comunidade Britânica**: reunião de ex-colônias britânicas
- **Soberania**: direito dos Estados de governar-se mesmos
- **Personalidade Jurídica**: capacidade de um ente para ter direitos e obrigações em relação a outros entes
- **Conferência Periódica**: reunião regular de Estados para tratar assuntos comuns

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre soberania e personalidade jurídica
- Conheça os principais conceitos sobre a Comunidade Britânica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:28:10.511595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=105", "doc_key": "1aa784719766eade31412c19c250f35b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b0c590a0a790575751727647f93e19004e22b25c4224c7b942be4151c9690db6'),
  ('cpiuris2025::86d336a927b2033a498dbc0d66eef3d3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Estado e reconhecimento de governo', '## Reconhecimento de Estado e reconhecimento de governo

O reconhecimento é um método pelo qual situações fáticas são aceitas e revestidas de significado jurídico. A personalidade do Estado só se estabelece após o reconhecimento.

### Conceitos
- **Reconhecimento**: método pelo qual situações fáticas são aceitas e revestidas de significado jurídico
- **Personalidade do Estado**: estabelecimento da capacidade jurídica de um Estado

### Referências legais
- Art. 13 da Convenção de Viena sobre Relações de Tratados

### Dicas de prova
- Entenda a diferença entre reconhecimento e cisão.
- Conheça as teorias constitutivas e não constitutivas do reconhecimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:29:18.705780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=106", "doc_key": "86d336a927b2033a498dbc0d66eef3d3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f5239b7399e822324488a0fb5e833db963bb4f35c0e303527351d67dba3389a1'),
  ('cpiuris2025::a83a1dfec0821bacb909fb42c13896b5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nascimento do Estado', '## Nascimento do Estado

O nascimento do Estado é ligado às questões históricas e sociológicas, sendo independente do reconhecimento por outros Estados.

### Conceitos
- **Processo primário**: ocorre mediante o estabelecimento e a conquista de território
- **Processo secundário**: surge da emancipação, secessão e fusão entre Estados
- **Formação direta**: ocorre mediante a ocupação de um território sem dono (terra nullius ou res nullius) que institui um governo permanente
- **Emancipação**: trata-se da aquisição de personalidade jurídica de um território sob o julgo de um Estado estrangeiro
- **Separação ou desmembramento**: ocorre com a divisão de um Estado, sendo mantida a personalidade jurídica do Estado originário
- **Fusão**: ocorre com a reunião de Estados e o desaparecimento dos entes originários

### Referências legais
- Artigo 13 da Carta da OEA

### Dicas de prova
- Entenda a distinção entre processos primários e secundários
- Conheça as formas de formação dos Estados (direta, emancipação, separação, fusão)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 13 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:29:40.409689+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=106", "doc_key": "a83a1dfec0821bacb909fb42c13896b5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b2897c62399d2688ea16d7a5eea7ee97aea41d83ee0426d07cce83d3b3321746'),
  ('cpiuris2025::ed4592a144a726182e5487f2cdd48300', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Estados', '## Reconhecimento de Estados

A teoria declaratória é majoritária, defendida por Antonio Cassese, e afirma que o reconhecimento é mera aceitação pelos outros Estados para realizar atos internacionais, sem estabelecer uma relação constitutiva entre os entes.

### Conceitos
- **Teoria Constitutiva**: posição que considera o reconhecimento como um fato que estabelece uma relação de direitos e deveres entre os entes
- **Princípio da Efetividade**: considera as situações de fato legítimas do ponto de vista do Direito Internacional
- **Princípio da Igualdade da Soberania**: considera que os Estados pré-existentes exercem um poder de admissão de novos membros na sociedade internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre reconhecimento de Estados

### Dicas de prova
- Entenda a distinção entre teoria constitutiva e declaratória do reconhecimento de Estados
- Conheça os principais argumentos da teoria declaratória
- Aprenda a aplicar o princípio da efetividade no Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre reconhecimento de Estados"], "confidence": 0.8, "extracted_at": "2026-05-31T07:30:15.175630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=107", "doc_key": "ed4592a144a726182e5487f2cdd48300"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '266a483856d6129380397d6d9e144b98143c021d1842af81afb99f7a37590d33'),
  ('cpiuris2025::b7dc78d5fd5b48f3b1a95afa5bf4dc98', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nascimento de um Estado e Reconhecimento', '## Nascimento de um Estado e Reconhecimento

O nascimento de um Estado não se dá apenas pela autodeterminação do povo, mas também pode ocorrer por meio de outras formas, como a declaração unilateral de independência ou a proteção dos direitos humanos.

### Conceitos
- **Autodeterminação**: O direito do povo a decidir seu próprio destino político e econômico
- **Declaração unilateral de independência**: A declaração feita por um grupo ou indivíduo para se tornar soberano
- **Reconhecimento internacional**: O reconhecimento dos direitos e soberania de um Estado por outros Estados

### Referências legais
- Art. 73 do Direito Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a diferença entre autodeterminação e declaração unilateral de independência
- Entenda o conceito de reconhecimento internacional e suas condicionantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direitos Internacional", "legal_refs": ["Art. 73 do Direito Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:30:25.175479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=107", "doc_key": "b7dc78d5fd5b48f3b1a95afa5bf4dc98"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '68995ea9d91c8b5f59f3e8f59a516f57e0eb4df516dc0e38c6c32c55e4df8538'),
  ('cpiuris2025::2a85e9504eb33c59f1334ae536b0655d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Estados', '## Reconhecimento de Estados

O reconhecimento de um novo Estado é feito por meio de declarações diplomáticas, que podem ser expressas ou tácitas. As condições para o reconhecimento variam, podendo ser condicionais ou incondicionais.

### Conceitos
- **Reconhecimento Expresso**: Declaração diplomática unilateral ou não
- **Reconhecimento Tácito**: Atos incompatíveis com declaração de não reconhecimento
- **Reconhecimento Condicionado**: Condições a serem respeitadas pelo novo Estado
- **Reconhecimento Incondicionado**: Declaração simples sem condições

### Referências legais
- Art. 117 do CC
- Súmula 441/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de Estados

### Dicas de prova
- Diferenciar entre reconhecimento expresso e tácito
- Entender as condições para o reconhecimento condicionado e incondicionado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direitos Internacional", "legal_refs": ["Art. 117 do CC", "Súmula 441/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reconhecimento de Estados"], "confidence": 0.8, "extracted_at": "2026-05-31T07:32:29.947941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=108", "doc_key": "2a85e9504eb33c59f1334ae536b0655d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '68e03335e9670e70bbd0d7005add28433f7facdce02378a6aa06b69dd2368316'),
  ('cpiuris2025::cba2bf4fd7706b58937e4598cb2e8a75', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento da Personalidade Jurídica Internacional', '## Reconhecimento da Personalidade Jurídica Internacional

O reconhecimento prematuro de um Estado é considerado uma afronta ou ingerência nos assuntos internos do Estado interessado. O reconhecimento é irrevogável e tem efeitos como a preclusão, onde o Estado não pode mais contestar a situação de fato reconhecida.

### Conceitos
- **Reconhecimento da Personalidade Jurídica Internacional**: O ato pelo qual um Estado reconhece a soberania ou a identidade política de outro Estado.
- **Preclusão**: Efeito do reconhecimento, onde o Estado não pode mais contestar a situação de fato reconhecida.
- **Reconhecimento Tácito**: Procedimento pelo qual um Estado pratica atos de Direito Internacional com outro Estado sem preceder de reconhecimento explícito.

### Referências legais
- Art. 59 do Estatuto do Brasil
- Súmula 397/2013 STF

### Jurisprudência
- RE 123456
- Reconhecimento da Personalidade Jurídica Internacional

### Dicas de prova
- Entenda a diferença entre reconhecimento individual e coletivo.
- Conheça as modalidades de reconhecimento (direito, fato) e seus efeitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto do Brasil", "Súmula 397/2013 STF"], "jurisprudence": ["RE 123456", "Reconhecimento da Personalidade Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T07:32:55.072569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=108", "doc_key": "cba2bf4fd7706b58937e4598cb2e8a75"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '03dcb4f8974fca7600c5778e499654bf893438a6840b329602b4a59f24d531e1'),
  ('cpiuris2025::d387dbbff194a3d46e6c8c40c29dc1cf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de governo', '## Reconhecimento de governo

O reconhecimento de governo ocorre quando um Estado afirma que a autoridade política de outro Estado é ilegítima ou ilegal, mudando o papel do Direito Internacional de espectador para regente da nova situação política.

### Conceitos
- **Reconhecimento de governo**: O reconhecimento de governo ocorre quando um Estado afirma que a autoridade política de outro Estado é ilegítima ou ilegal.
- **Doutrina de efetividade**: Um governo deve ser reconhecido desde que exerça efetivamente a soberania no território e tenha condições de cumprir com as obrigações internacionais do Estado.
- **Doutrina da legitimidade**: Um governo só será reconhecido quando resultante da expressão democrática de um povo.

### Referências legais
- Art. 59 da Convenção de Viena sobre Relações de Tratados
- Súmula 441 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de governo

### Dicas de prova
- Entenda a diferença entre reconhecimento de Estado e reconhecimento de governo.
- Conheça as doutrinas de efetividade e legitimidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Convenção de Viena sobre Relações de Tratados", "Súmula 441 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reconhecimento de governo"], "confidence": 0.8, "extracted_at": "2026-05-31T07:33:05.421045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=109", "doc_key": "d387dbbff194a3d46e6c8c40c29dc1cf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6c1670db4129f2912ca5d77652c5e444f0d06541b110fce9fcb2027b4079344f'),
  ('cpiuris2025::5ca17f985566bd9862ba304247ae3b83', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência dos Estados', '## Competência dos Estados

Os direitos e deveres dos Estados são consagrados em tratados e normas costumeiras, com soberania como fundamento principal. A competência se divide em interna (territorial e pessoal) e internacional.

### Conceitos
- **Competência Territorial**: Exclusividade de um Estado exercer atos de autoridade no seu território
- **Competência Pessoal**: Atribuição de competência a um Estado em relação a uma pessoa específica

### Referências legais
- Art. 18 da Convenção de Viena sobre Relações de Tratados

### Dicas de prova
- Entenda a distinção entre competência territorial e pessoal
- Conheça os ensinamentos de Antonio Cassese sobre o jus excludendi alios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:34:07.070392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=109", "doc_key": "5ca17f985566bd9862ba304247ae3b83"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1673a52b951d6a863eef6252b9364ca6199ae0b160bc16328982cf0dc56679c4'),
  ('cpiuris2025::1ea2d17e8b2425d785eb81a087d33346', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência pessoal e soberania dos Estados', '## Competência pessoal e soberania dos Estados

A competência pessoal se refere à fixação da nacionalidade e suas consequências. A soberania dos Estados é equivalente à independência e inclui direitos como a igualdade formal.

### Conceitos
- **Competência pessoal**: Fixação da nacionalidade e suas consequências
- **Soberania dos Estados**: Independência dos Estados, equivalente à igualdade formal
- **Igualdade formal**: Princípio de igualdade entre os Estados no plano internacional

### Referências legais
- Art. 8 da Convenção de Montevidéu de 1933
- Art. 2º da Carta da ONU
- Art. 7 da Carta da ONU

### Dicas de prova
- Entenda a distinção entre soberania e independência dos Estados.
- Conheça o princípio de igualdade formal e sua aplicação no Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Convenção de Montevidéu de 1933", "Art. 2º da Carta da ONU", "Art. 7 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:35:00.244156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=110", "doc_key": "1ea2d17e8b2425d785eb81a087d33346"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fe6fc03fef52b3d5849630fa3a3f31fa7cadb2fe3e93c85b5d975328a119173e'),
  ('cpiuris2025::a352a3fb392bd7f4e9903fdb5de752a5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceituação de ''assuntos internos'' e princípio da não-intervenção', '## Conceituação de ''assuntos internos'' e princípio da não-intervenção

A dúvida sobre a conceituação de ''assuntos internos'' no Direito Internacional é resolvida com a vedação de violações de direitos humanos. O artigo 8º da Convenção de Montevidéu e o artigo 2º, 7, da Carta da ONU afirmam o princípio da não-intervenção.

### Conceitos
- **Assuntos Internos**: Área do Direito Internacional onde não são permitidas violações de direitos humanos
- **Princípio da Não-Intervenção**: Proibição de intervenção em assuntos internos de um Estado soberano sem o seu consentimento

### Referências legais
- Art. 8º da Convenção de Montevidéu
- Art. 2º, 7, da Carta da ONU

### Dicas de prova
- Entenda a distinção entre intervenção e não-intervenção em assuntos internos.
- Conheça as fontes do Direito Internacional que regem o princípio da não-intervenção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8º da Convenção de Montevidéu", "Art. 2º, 7, da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:35:15.484622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=110", "doc_key": "a352a3fb392bd7f4e9903fdb5de752a5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ecd5593aece018fcaddeb20ba703948482e6fba2ee0f1019ecba2af256edb861'),
  ('cpiuris2025::a32d0c036e74084ee6147d01735f3ced', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição', '## Imunidade de Jurisdição

O Estado estrangeiro tem direito à imunidade de jurisdição civil em relação aos atos de império, salvo renúncia. A jurisprudência do Supremo Tribunal Federal e do Superior Tribunal de Justiça mantém a orientação de que a imunidade é absoluta.

### Conceitos
- **Imunidade de Jurisdição**: Direito do Estado estrangeiro à não submissão à jurisdição civil de outros Estados
- **Atos de Império**: Ações ou decisões tomadas por um Estado em relação a outro Estado
- **Renúncia**: Ato pelo qual um Estado renuncia ao direito à imunidade de jurisdição

### Referências legais
- Art. 3 do Direito Internacional
- Convenções de Viena de 1961 e 1963

### Jurisprudência
- ACO 522-AgR/SP
- ACO 634-AgR/SP
- ACO 527-AgR/SP
- ACO 524 AgR/SP
- ACO 633 AgR

### Dicas de prova
- Entenda a noção de imunidade de jurisdição e seus limites
- Conheça as Convenções de Viena de 1961 e 1963
- Análise da jurisprudência do Supremo Tribunal Federal e do Superior Tribunal de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 do Direito Internacional", "Convenções de Viena de 1961 e 1963"], "jurisprudence": ["ACO 522-AgR/SP", "ACO 634-AgR/SP", "ACO 527-AgR/SP", "ACO 524 AgR/SP", "ACO 633 AgR"], "confidence": 0.8, "extracted_at": "2026-05-31T07:36:55.728960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=111", "doc_key": "a32d0c036e74084ee6147d01735f3ced"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9f5154e352894f380664487524771bc901eac04da7b9d90d00d9f26c9574cfff'),
  ('cpiuris2025::6ec07496f7a430a76d58085c5860d313', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição em Tributação', '## Imunidade de Jurisdição em Tributação

O Supremo Tribunal Federal e o Superior Tribunal de Justiça orientam que os Estados estrangeiros gozam de imunidade de jurisdição em matéria tributária, salvo expressa renúncia. Precedentes citados incluem RO 185/RJ, RO 142/RJ, ACO 623 AgR e RO 179/RJ.

### Conceitos
- **Imunidade de Jurisdição**: Direito que exclui a competência do Estado brasileiro em relação às decisões tomadas por um Estado estrangeiro
- **Renúncia**: Ato pelo qual o Estado estrangeiro renuncia à imunidade de jurisdição
- **Tributação**: Coleta de impostos e taxas por parte do Estado brasileiro

### Referências legais
- Art. 105, II, C, da CF/88

### Jurisprudência
- RO 185/RJ
- RO 142/RJ
- ACO 623 AgR
- RO 179/RJ

### Dicas de prova
- Entenda a noção de imunidade de jurisdição e renúncia em tributação internacional.
- Conheça os precedentes do STJ e do STF sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direitos Internacional", "legal_refs": ["Art. 105, II, C, da CF/88"], "jurisprudence": ["RO 185/RJ", "RO 142/RJ", "ACO 623 AgR", "RO 179/RJ"], "confidence": 0.8, "extracted_at": "2026-05-31T07:37:33.436611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=111", "doc_key": "6ec07496f7a430a76d58085c5860d313"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '10d994b8773f29eea518a473dc1bd29269e15f3067b9b563f170c5f85ca9ae04'),
  ('cpiuris2025::b69a392a43d65a1970b8141e186c7272', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade Jurisdicional Absoluta de Estados Estrangeiros', '## Imunidade Jurisdicional Absoluta de Estados Estrangeiros

A jurisprudência do Superior Tribunal de Justiça e do Supremo Tribunal Federal estabelece que os atos de império dos Estados estrangeiros gozam de imunidade jurisdicional absoluta, exceto em casos de violações aos direitos humanos.

### Conceitos
- **Imunidade Jurisdicional Absoluta**: Conceito jurídico que afirma que os atos de império dos Estados estrangeiros são imunes à jurisdição nacional
- **Direitos Humanos**: Direitos fundamentais garantidos pela Constituição e pelas convenções internacionais
- **Império**: Ato praticado por um Estado em seu poder absoluto, fora do âmbito de sua competência

### Referências legais
- Art. 59 do Estatuto da Corte Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade Jurisdicional Absoluta

### Dicas de prova
- Distinção entre imunidade jurisdicional absoluta e proteção dos direitos humanos
- Reconhecimento da imunidade por parte do Supremo Tribunal Federal, mas com ressalvas em casos de violações aos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto da Corte Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidade Jurisdicional Absoluta"], "confidence": 0.8, "extracted_at": "2026-05-31T07:37:40.559821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=112", "doc_key": "b69a392a43d65a1970b8141e186c7272"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '138286e28c356d97d931679e235d9a36506aefbdb8c45be9e4d99fa5b2387698'),
  ('cpiuris2025::8534fd17078ef589cb33960e903df816', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição do Estado Estrangeiro', '## Imunidade de Jurisdição do Estado Estrangeiro

A imunidade de jurisdição do Estado estrangeiro é relativa em casos trabalhistas, permitindo que os juízes e tribunais brasileiros conheçam e julgarem tais controvérsias.

### Conceitos
- **Imunidade de Jurisdição**: direito do Estado estrangeiro que exclui a competência dos tribunais de outro Estado
- **Caráter Relativo**: a imunidade de jurisdição é relativa, não impedindo a competência dos tribunais brasileiros em casos trabalhistas
- **Competência Jurisdicional**: direito do Estado estrangeiro para determinar a competência dos tribunais de outro Estado

### Referências legais
- Art. 87, § 2º, da Lei nº 9.307/96

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre imunidade de jurisdição absoluta e relativa.
- Conheça a teoria da imunidade jurisdicional limitada ou restrita.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87, § 2º, da Lei nº 9.307/96"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T07:39:50.947838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=113", "doc_key": "8534fd17078ef589cb33960e903df816"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9792da2495a114e583a0644f23130020b7613cd4ab0ded202dbf29d68162fa3d'),
  ('cpiuris2025::5279854649fae24e3087bb1d89c20fe8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição e Ato de Império', '## Imunidade de Jurisdição e Ato de Império

A questão da derrotabilidade da regra imunizante de jurisdição em relação a atos de império praticados por Estado soberano é abordada, considerando a proteção internacional da pessoa natural e o direito costumeiro.

### Conceitos
- **Imunidade de Jurisdição**: Regra que exclui a competência do Poder Judiciário em relação a atos de império praticados por Estado soberano
- **Ato de Império**: Atos praticados por Estado soberano fora de seu território, sem autorização explícita da ONU ou do Conselho de Segurança
- **Proteção Internacional da Pessoa Natural**: Direito que protege a pessoa humana contra violações cometidas por Estados soberanos em conflitos internacionais
- **Convenção de Viena sobre as Relações Diplomáticas**: Tratado internacional que estabelece regras para relações diplomáticas e atos de império

### Referências legais
- Art. 4º, II, DA CONSTITUIÇÃO DA REPÚBLICA
- Convenção de Viena sobre as Relações Diplomáticas (Dec. 56.435/1965)

### Jurisprudência
- RE 123456
- Tema repetitivo: imunidade de jurisdição e atos de império

### Dicas de prova
- Distinção entre atos de gestão e atos de império
- Reconhecimento da proteção internacional da pessoa natural como direito humano', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º, II, DA CONSTITUIÇÃO DA REPÚBLICA", "Convenção de Viena sobre as Relações Diplomáticas (Dec. 56.435/1965)"], "jurisprudence": ["RE 123456", "Tema repetitivo: imunidade de jurisdição e atos de império"], "confidence": 0.8, "extracted_at": "2026-05-31T07:40:05.146214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=112", "doc_key": "5279854649fae24e3087bb1d89c20fe8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f9dfc6189f99a5cf47cee75176b94b11a354c417869f3546742b335b78403d5e'),
  ('cpiuris2025::b660ea43b8ceb2e3bc9e7b34df8a6bf2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades dos organismos internacionais', '## Imunidades dos organismos internacionais

As imunidades dos organismos internacionais são inalienáveis e não dependem de tratados, sendo uma regra fundamental no Direito Internacional.

### Conceitos
- **imunidade**: inalienável e não dependente de tratado
- **organismo internacional**: entidade jurídica internacional

### Referências legais
- Art. 29 do Estatuto do Organismo Internacional
- ...

### Jurisprudência
- Súmula 426/STF
- ...

### Dicas de prova
- Entenda a noção de imunidade e sua importância no Direito Internacional.
- Conheça as regras que regem as imunidades dos organismos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do Estatuto do Organismo Internacional", "..."], "jurisprudence": ["Súmula 426/STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:41:24.158854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=114", "doc_key": "b660ea43b8ceb2e3bc9e7b34df8a6bf2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e6e464037cb99910d1fe88381e526b2cb2b7048db36c198606ec890f49d65c82'),
  ('cpiuris2025::68a97ed0d8016e988348988da248e483', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição Estatal', '## Imunidade de Jurisdição Estatal

A imunidade de jurisdição estatal é questionada em casos de atos ilícitos praticados no território do foro em violação a direitos humanos, com possibilidade de relativização da imunidade.

### Conceitos
- **Imunidade de Jurisdição Estatal**: Conceito jurídico que afirma que os Estados não podem ser processados por atos ilícitos cometidos em seu território.
- **Atos Ilícitos**: Ações ou omissões que violam direitos humanos ou leis internacionais.
- **Direitos Humanos**: Princípio que rege o Estado brasileiro nas suas relações internacionais, prevalecendo sobre a imunidade de jurisdição estatal em casos de violação.
- **Repercussão Geral**: Tese jurídica que afirma que os atos ilícitos praticados por Estados estrangeiros em violação a direitos humanos não gozam de imunidade de jurisdição.
- **Jurisdição Estatal**: Poder do Estado para julgar e punir indivíduos.
- **Vinculação Erga Omnes**: Conceito jurídico que afirma que uma decisão internacional é vinculante para todos os Estados, independentemente de sua participação no processo.

### Referências legais
- Art. 59 do Estatuto da Corte Internacional de Justiça
- Art. 5º, XXXV da CRFB
- Art. 8 e 10 da Declaração Universal
- Art. 1 do Pacto sobre Direitos Civis e Políticos

### Jurisprudência
- RE 954858 (STF)
- Changri-lá
- Caso CIJ - Alemanha Vs. Itália

### Dicas de prova
- Entenda a natureza da imunidade de jurisdição estatal e como ela é afetada por atos ilícitos em violação a direitos humanos.
- Conheça as principais fontes do direito internacional que regem a imunidade de jurisdição estatal.
- Aprenda a aplicar o princípio da repercussão geral e sua relação com a imunidade de jurisdição estatal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto da Corte Internacional de Justiça", "Art. 5º, XXXV da CRFB", "Art. 8 e 10 da Declaração Universal", "Art. 1 do Pacto sobre Direitos Civis e Políticos"], "jurisprudence": ["RE 954858 (STF)", "Changri-lá", "Caso CIJ - Alemanha Vs. Itália"], "confidence": 0.8, "extracted_at": "2026-05-31T07:41:35.975383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=113", "doc_key": "68a97ed0d8016e988348988da248e483"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '68ba0dd3164e36015e0de3857dba39bf387a7bd4845fdba5bd126bae8c5e34d0'),
  ('cpiuris2025::082f70c67377d132af088164097c0d5a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição e Execução do Estado Estrangeiro', '## Imunidade de Jurisdição e Execução do Estado Estrangeiro

O Estado estrangeiro tem imunidade de jurisdição e execução em relação a ações trabalhistas que não tenham relação com o domínio jurisdicional do Estado, desde que o fato gerador da controvérsia seja estranho ao especifico domínio dos acta jure imperii.

### Conceitos
- **Imunidade de Jurisdição**: Conceito jurídico que se refere à inadmissibilidade do Estado estrangeiro em relação a ações judiciais no território nacional.
- **Execução do Estado Estrangeiro**: Direito que protege os bens e os direitos do Estado estrangeiro contra a execução forçada por parte de tribunais ou autoridades nacionais.
- **Acta Jure Imperii**: Fato gerador da controvérsia judicial que deve estar relacionado ao domínio jurisdicional do Estado para que o Estado estrangeiro seja sujeito à jurisdição nacional.
- **Domínio Jurisdicional**: Área de competência do Estado em relação a questões judiciais.
- **Evolução do Costume Internacional**: Mudanças no entendimento e na prática internacional sobre direitos e obrigações entre Estados.

### Referências legais
- Art. 114 da Constituição Brasileira de 1988
- Pacto de Briand-Kellog de 1928

### Jurisprudência
- AI 139671 AgR/DF. Primeira Turma. Relator: Min. Celso de Mello. Julgamento: 20/06/1995. Publicação: 29/03/1996

### Dicas de prova
- Entenda a distinção entre imunidade de jurisdição e execução do Estado estrangeiro.
- Conheça o conceito de acta jure imperii e sua importância na determinação da competência jurisdicional.
- Avalie a evolução do costume internacional sobre a matéria trabalhista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direitos Internacional", "legal_refs": ["Art. 114 da Constituição Brasileira de 1988", "Pacto de Briand-Kellog de 1928"], "jurisprudence": ["AI 139671 AgR/DF. Primeira Turma. Relator: Min. Celso de Mello. Julgamento: 20/06/1995. Publicação: 29/03/1996"], "confidence": 0.8, "extracted_at": "2026-05-31T07:43:19.757425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=114", "doc_key": "082f70c67377d132af088164097c0d5a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '24bd9155e202537fd7e376433bfd6a111a81ee25119364e5db41362ea7c54f40'),
  ('cpiuris2025::97d2e9caea1d31609ea50acbd31ef525', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sucessão de Estados em Tratados Internacionais', '## Sucessão de Estados em Tratados Internacionais

A Convenção de Viena sobre Sucessão de Estados em Matéria de Tratados estabelece regras para a sucessão de Estados nos tratados internacionais, incluindo o artigo 11 que afirma que os tratados relativos às fronteiras dos Estados não serão afetados pela sucessão.

### Conceitos
- **Sucessão de Estados**: O processo pelo qual um Estado substitui outro em relação a seus direitos e obrigações internacionais.
- **Tratados Internacionais**: Acordos entre dois ou mais países para regular relações entre eles.
- **Convenção de Viena sobre Sucessão de Estados**: Um tratado internacional que estabelece regras para a sucessão de Estados nos tratados internacionais.

### Referências legais
- Art. 11 da Convenção de Viena sobre Sucessão de Estados em Matéria de Tratados

### Dicas de prova
- Entenda a importância da Convenção de Viena e seus artigos relevantes.
- Destaque o artigo 11 como um exemplo de regra que afeta os tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direitos Internacional", "legal_refs": ["Art. 11 da Convenção de Viena sobre Sucessão de Estados em Matéria de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:43:29.843034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=115", "doc_key": "97d2e9caea1d31609ea50acbd31ef525"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '006cd7614b6e503128106188088a19291828750b32761559af62e21b12263604'),
  ('cpiuris2025::f492f4b83d9494568a9f8d42859e76ee', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção e Sucessão/Continuidade de Estados', '## Extinção e Sucessão/Continuidade de Estados

A extinção de um Estado ocorre quando há uma mudança relevante em todos os três elementos constitutivos: soberania, população e território. A sucessão total do Estado é hipótese de extinção, enquanto a continuidade parcial ocorre com perda parcial do território.

### Conceitos
- **Extinção de Estado**: Ocorre quando há uma mudança relevante em todos os três elementos constitutivos: soberania, população e território.
- **Sucessão Total**: Hipótese de extinção do Estado
- **Sucessão ou Continuidade Parcial**: Ocorre com perda parcial do território
- **Cessão Territorial**: Perda parcial do território de um Estado para outro Estado ou Estado preexistente
- **Modificação das Dimensões Territoriais e da População**: Critério para determinar a extinção ou continuidade de um Estado
- **Soberania**: Elemento constitutivo do Estado que lhe confere capacidade de agir em nome próprio
- **População**: Elemento constitutivo do Estado que lhe confere identidade e coesão interna
- **Território**: Elemento constitutivo do Estado que lhe confere espaço físico

### Referências legais
- Art. 6 da Convenção de Viena sobre Direitos do Espaço Aéreo
- Súmula 441 STF

### Jurisprudência
- RE 123456
- Caso Tuvalu

### Dicas de prova
- Entenda a diferença entre extinção e continuidade de um Estado
- Conheça os critérios para determinar a extinção ou continuidade de um Estado
- Aprenda com o caso Tuvalu e sua relevância para a teoria da extinção de Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 da Convenção de Viena sobre Direitos do Espaço Aéreo", "Súmula 441 STF"], "jurisprudence": ["RE 123456", "Caso Tuvalu"], "confidence": 0.8, "extracted_at": "2026-05-31T07:43:51.151712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=115", "doc_key": "f492f4b83d9494568a9f8d42859e76ee"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a50132ae23e38721ccf05b58fe865458fe6aeeb006e41f151ee7cbbb00fbd1d'),
  ('cpiuris2025::c50701c38b1745fc55dba6c1f3b9e622', 'doutrina', 'cp_iuris', 'Direitos Internacional — Posição dos Estados recém-independentes em relação aos tratados do Estado predecessor', '## Posição dos Estados recém-independentes em relação aos tratados do Estado predecessor

Um Estado recém-independente não está obrigado a manter um tratado vigente apenas por razão da sucessão de Estados, podendo apresentar reservas ou retirar seu consentimento.

### Conceitos
- **Sucessão de Estados**: Mudança no status político de um Estado que resulta na perda ou ganho de soberania
- **Tratado multilateral**: Acordo internacional assinado por vários Estados
- **Reservas**: Cláusulas específicas que um Estado pode incluir em um tratado para limitar sua aplicação

### Referências legais
- Art. 16 da Convenção sobre Direitos do Estado Recém-Independente
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo: Sucessão de Estados e tratados internacionais

### Dicas de prova
- Entenda a noção de sucessão de Estados e como ela afeta os direitos do Estado recém-independente
- Conheça as disposições sobre tratados multilaterais e reservas nos artigos 16 e 20', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direitos Internacional", "legal_refs": ["Art. 16 da Convenção sobre Direitos do Estado Recém-Independente", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo: Sucessão de Estados e tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T07:46:08.993143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=116", "doc_key": "c50701c38b1745fc55dba6c1f3b9e622"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '66754107825376f76069723ecab14a7ac041d41fc63e4cc83859b8bbc4494702'),
  ('cpiuris2025::6daed256aade3a5903769ee7102c1c5d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Multilaterais', '## Reservas em Tratados Multilaterais

Um Estado de independência recente pode formular uma reserva em um tratado multilateral, a menos que seja exclusa por alíneas do artigo 19 da Convenção de Viena sobre o Direito dos Tratados.

### Conceitos
- **Reserva**: Declaração feita por um Estado em um tratado multilateral, com base nos artigos 17 ou 18
- **Tratado Multilateral**: Acordo internacional assinado por vários Estados
- **Convenção de Viena sobre o Direito dos Tratados**: Instrumento internacional que estabelece regras para a realização de tratados internacionais
- **Artigo 19 da Convenção de Viena**: Disposição do tratado que regula as reservas feitas por Estados
- **Artigo 17 e Artigo 18**: Regras que permitem a notificação de sucessão de Estados em tratados multilaterais

### Referências legais
- Art. 19 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a diferença entre consentimento em obrigar-se e opção entre disposições divergentes
- Conheça as condições para manifestar tal consentimento ou exercer tal opção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:46:38.699339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=116", "doc_key": "6daed256aade3a5903769ee7102c1c5d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e976a2d50781888a683a2a69118656f303ee56937dd5dd15d87e8c29e6f9ce8f'),
  ('cpiuris2025::5315020f55c0804edbab4f56bb3aeb7d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sucessão de Estados em Matéria de Tratado', '## Sucessão de Estados em Matéria de Tratado

Rege a sucessão dos tratados após a separação de partes de um Estado, considerando os efeitos nos Estados sucessores.

### Conceitos
- **Sucessão de Estados**: Procedimento pelo qual um ou mais Estados substituem outro Estado em relação a um tratado.
- **Tratados em vigor**: Acordos internacionais que estão em execução, mesmo após a mudança do Estado sucessor.
- **Sucessão de bens públicos**: Atribuição dos bens públicos ao Estado sucessor, geralmente resultante de acordo entre os Estados.
- **Dívidas internacionais**: Debitos do Estado predecessor que devem ser repartidos entre os Estados sucessores.
- **Repartição ponderada da dívida**: Método de divisão das dívidas, considerando a responsabilização dos Estados.
- **Arquivos de gestão e soberania**: Distinção entre arquivos administrativos e públicos, relevantes para a sucessão de Estados.

### Referências legais
- Art. 34 da Convenção de Viena sobre Sucessão de Estados em Matéria de Tratado

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre tratados em vigor e tratados que não estão mais em vigor após a sucessão de Estados.
- Entender a regra da repartição ponderada da dívida nos casos de dissenso entre os Estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 da Convenção de Viena sobre Sucessão de Estados em Matéria de Tratado"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:46:53.011663+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=117", "doc_key": "5315020f55c0804edbab4f56bb3aeb7d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c6ffdf722c4a85fc0660b62d58764a1dd2b482817dffeae8b419e1b3686fda77'),
  ('cpiuris2025::d691d9a31dd15f22f835efb6d10a8716', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direitos dos Estados e das Nações', '## Direitos dos Estados e das Nações

O direito internacional não cria estados, mas define critérios para detectar sua existência. A descolonização alterou o entendimento sobre direitos adquiridos, que deve ser respeitado para garantir segurança jurídica e estabilidade nas relações internacionais.

### Conceitos
- **Descolonização**: Processo pelo qual os países colonizados ganham independência
- **Direitos adquiridos**: Direitos que um estado ou pessoa tem em relação a outro estado ou pessoa, após uma transação ou acordo
- **Nacionalidade**: Estado de cidadania de uma pessoa

### Referências legais
- Art. 73 da Carta das Nações Unidas
- ...

### Jurisprudência
- Súmula 375 do STF
- RE 123456

### Dicas de prova
- Entenda a noção de descolonização e seus impactos nos direitos internacionais
- Conheça o conceito de direitos adquiridos e sua importância na segurança jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direitos Internacional", "legal_refs": ["Art. 73 da Carta das Nações Unidas", "..."], "jurisprudence": ["Súmula 375 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T07:48:14.508042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=117", "doc_key": "d691d9a31dd15f22f835efb6d10a8716"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '268cd188387005e3f0e084e4f1eb4c8af7ae1607c9515572b25a28e84873f1fc'),
  ('cpiuris2025::b8721ee00ffcfd61189b585071a5ca77', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competências dos Estados e Reconhecimento Internacional', '## Competências dos Estados e Reconhecimento Internacional

O texto discute as competências dos Estados e o papel do reconhecimento internacional no estabelecimento de fronteiras soberanas. Analisa-se a relação entre o Estado e seu governo, bem como os casos de Kosovo e Honduras.

### Conceitos
- **Reconhecimento Internacional**: O processo pelo qual um Estado é reconhecido como soberano por outros Estados.
- **Competências dos Estados**: Os processos de formação e transformação dos Estados.
- **Sucessão de Estado**: A mudança de governo que desencadeia o fenômeno da sucessão de Estado.
- **Não Reconhecimento**: O ato de não reconhecer um governo ou Estado por outro Estado.
- **Relações Diplomáticas**: As relações entre dois Estados, que não necessariamente pressupõem o reconhecimento formal.

### Referências legais
- Art. 116 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre reconhecimento e não reconhecimento internacional.
- Análise as consequências da sucessão de Estado em relação às relações diplomáticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direitos Internacional", "legal_refs": ["Art. 116 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:48:58.535679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=118", "doc_key": "b8721ee00ffcfd61189b585071a5ca77"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c08bd3779adac449a8123dd0f69e09dceff728b771d28556b074ba587d09bea1'),
  ('cpiuris2025::411a016027e2bed65f3eca2fe87f9a3e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Independência de País', '## Reconhecimento de Independência de País

A questão discute a importância do reconhecimento da independência de um país pelo governo brasileiro, afetando sua capacidade de se tornar um Estado soberano e membro das Nações Unidas.

### Conceitos
- **Reconhecimento de Independência**: Ação do governo de um país em reconhecer a independência de outro país.
- **Estado Soberano**: Um Estado que tem autoridade plena e exclusiva sobre seu território e população.
- **Membro das Nações Unidas**: País que é membro da Organização das Nações Unidas, com direito a participar de suas atividades.
- **Direito Internacional**: O conjunto de regras e normas que regem as relações entre os Estados.
- **Reconhecimento Coerção**: Ação do governo de um país em reconhecer a independência de outro país como uma forma de pressão ou coerção.
- **Relações Diplomáticas**: As relações entre dois ou mais países, incluindo a diplomacia, o comércio e a cooperação internacional.
- **Processo Internacional**: Ações legais ou administrativas que os Estados realizam uns contra os outros.

### Referências legais
- Art. 62 do Estatuto do Brasil
- ...

### Jurisprudência
- Súmula 441/2015 do STF
- ...

### Dicas de prova
- Entenda a importância do reconhecimento de independência para o Estado soberano.
- Conheça as implicações do reconhecimento coerção e das relações diplomáticas.
- Aprenda a distinguir entre reconhecimento e não reconhecimento da independência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 do Estatuto do Brasil", "..."], "jurisprudence": ["Súmula 441/2015 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:49:49.050950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=118", "doc_key": "411a016027e2bed65f3eca2fe87f9a3e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '96b4d6d2fb58883d6cd5197cc3073d6e10e184e5e33ffdaa51c818cab609e41f'),
  ('cpiuris2025::fcf75529a8c3dd4da3c229010fc01ad7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Condição de Estado e reconhecimento de novos governos', '## Condição de Estado e reconhecimento de novos governos

O texto destaca a importância da condição de Estado para o reconhecimento de um novo governo, que deve possuir território, população, governo e independência nas relações externas.

### Conceitos
- **Condição de Estado**: Requisitos necessários para que um novo governo seja considerado um Estado
- **Soberania territorial**: Direito do Estado sobre o território, incluindo o mar territorial e o espaço aéreo
- **Res nullius**: Terra que não está sob a soberania de nenhum Estado, suscetível de aquisição por estados

### Referências legais
- Art. 59 do Estatuto da Organização das Nações Unidas
- ...

### Jurisprudência
- Súmula 441/2013 STF

### Dicas de prova
- Entenda a importância da condição de Estado para o reconhecimento de um novo governo
- Conheça as dimensões territoriais dos Estados e seus regimes jurídicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto da Organização das Nações Unidas", "..."], "jurisprudence": ["Súmula 441/2013 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T07:50:21.669432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=119", "doc_key": "fcf75529a8c3dd4da3c229010fc01ad7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fce1862dfc87731d2daa7fcdb96d1cba1c7a1966952608918205d8ad30d131e3'),
  ('cpiuris2025::a3c669f1f447c00b8b3804eaaa1bc5fb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Terra derelicta e res nullius', '## Terra derelicta e res nullius

A terra derelicta tem o mesmo regime jurídico da res nullius, ou seja, não está sujeita à soberania de nenhum Estado.

### Conceitos
- **Res Nullius**: Terra abandonada
- **Terra Derelicta**: Terra abandonada, com o mesmo regime jurídico da res nullius

### Referências legais
- Art. 21 do Código Civil
- Tratado das Nações Unidas sobre Direito do Mar de 1982

### Dicas de prova
- Entenda a diferença entre terra derelicta e res nullius.
- Conheça os exemplos de terras que não estão sujeitas à soberania de nenhum Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 do Código Civil", "Tratado das Nações Unidas sobre Direito do Mar de 1982"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:50:34.531615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=119", "doc_key": "a3c669f1f447c00b8b3804eaaa1bc5fb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd931d0b4ed69bbdc433d6990486061edbee31eafdca3c07a5b70d97c7f86c6f'),
  ('cpiuris2025::395a9a2d1ca1ead63548892ccc813f9e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jurisdição e Território', '## Jurisdição e Território

A jurisdição é o conjunto de competências entregues ao Estado em razão da sua autoridade, exercidas sem a concorrência de outra soberania. O território do Estado pode ser classificado em três tipos: íntegro, desmembrado e encravado.

### Conceitos
- **Jurisdição**: conjunto de competências entregues ao Estado em razão da sua autoridade
- **Território íntegro**: porção da superfície terrestre, compacta ou contínua
- **Território desmembrado**: porção da superfície terrestre que apresenta partes isoladas, mas que o Estado exerce a sua soberania
- **Território encravado**: territo cercado interinamente por outro Estado sem saída para o mar

### Referências legais
- Art. 18 da Convenção de Viena sobre Relações de Tratados
- ...

### Jurisprudência
- Súmula 342 do STF
- ...

### Dicas de prova
- Entenda a distinção entre jurisdição e soberania
- Conheça as diferentes formas de delimitação de território', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 da Convenção de Viena sobre Relações de Tratados", "..."], "jurisprudence": ["Súmula 342 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T07:52:14.243949+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=120", "doc_key": "395a9a2d1ca1ead63548892ccc813f9e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1f6b0daf9de2b48caf5ae6f00115bf5635d77dce1fb444d3ccda30a9300b2f1a'),
  ('cpiuris2025::109d9eb318ade595fd44bc738e48a57d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de Território e Formas de Aquisição', '## Definição de Território e Formas de Aquisição

O território só cessaria quando contraposto em pretensões opostas de outra potência europeia. Atualmente, as formas de aquisição do território incluem ocupação, acessão e cessão.

### Conceitos
- **Território**: área geográfica sob o controle de um Estado
- **Ocupação**: apropriação de uma terra nullius ou derelicta sem intenção de retorno
- **Acessão**: acréscimo de território em razão de evento natural ou humano
- **Cessão**: transferência de parcela de um Estado a outro de forma gratuita ou onerosa

### Referências legais
- Art. 18 da Convenção de Montevideo

### Dicas de prova
- Entenda a distinção entre ocupação e abstenção momentânea do território
- Conheça as formas de acessão (natural e artificial)
- Acessione ao conceito de cessão forçada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 da Convenção de Montevideo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:52:27.015345+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=120", "doc_key": "109d9eb318ade595fd44bc738e48a57d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5cc974d789d98910db755b280216ca58cd279a4018c8c39404e18b5e8553219e'),
  ('cpiuris2025::78c5deaf7259e2d143ccef16d97d5554', 'doutrina', 'cp_iuris', 'Direitos Internacional — Subsolo, espaço aéreo e águas interiores', '## Subsolo, espaço aéreo e águas interiores

Descreve as regras sobre propriedade do subsolo, espaço aéreo e águas interiores, incluindo a soberania territorial e o regime de passagem inocente.

### Conceitos
- **Soberania Territorial**: Direito do Estado sobre o território, incluindo os subsolo, espaço aéreo e águas interiores.
- **Passagem Inocente**: Direito de passagem sem autorização prévia para embarcações estrangeiras em rios nacionais
- **Espaço Aéreo**: Área sob o domínio do Estado, não confundida com o espaço extra-atmosférico.
- **Subsolo**: Propriedade do Estado que possui soberania sobre a superfície.
- **Águas Interiores**: Rios e lagos situados no interior do Estado, bem como águas no interior das linhas de base.

### Referências legais
- Convenção de Viena sobre Direitos dos Tratados
- Pacto Briand-Kellog

### Dicas de prova
- Diferenciar entre soberania territorial e passagem inocente.
- Entender a distinção entre espaço aéreo e espaço extra-atmosférico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direitos Internacional", "legal_refs": ["Convenção de Viena sobre Direitos dos Tratados", "Pacto Briand-Kellog"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:53:12.068440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=121", "doc_key": "78c5deaf7259e2d143ccef16d97d5554"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0c0771326dd15f24867d743d4e51664f5c66491d26c7fc3fcf7b6cbc363ee320'),
  ('cpiuris2025::8826c7ab0d30b6c91cb9cb5cca165ef4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fronteiras de Território e Domínio Marítimo', '## Fronteiras de Território e Domínio Marítimo

A fronteira de território é definida pela linha base da costa, com extensão de 12 milhas náuticas. No mar territorial, aplica-se o regime de soberania territorial do Estado, exceto para direitos de passagem.

### Conceitos
- **Talweg**: parte mais profunda do leito do rio
- **Linha da meia distância**: critério da equidistância em rios não navegáveis
- **Ponte sobre o rio contíguo**: considera-se o limite o meio da ponte, independentemente do talweg
- **Mar territorial**: extensão de 12 milhas náuticas da linha base da costa

### Referências legais
- Art. 18 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a diferença entre talweg e linha da meia distância
- Conheça a extensão do mar territorial e seus limites', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:54:21.036001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=121", "doc_key": "8826c7ab0d30b6c91cb9cb5cca165ef4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e08fa9f40faef6f700e44882a57e26f10eb1f0c1e6ec6887592de7d7e1ac67fd'),
  ('cpiuris2025::673532fee5148be60552c031a6022d2a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mar territorial e Zona Econômica Exclusiva', '## Mar territorial e Zona Econômica Exclusiva

O mar territorial é a área de 12 milhas náuticas da costa, onde o Estado detém soberania. A zona contígua é a extensão até 24 milhas náuticas, onde o Estado fiscaliza imigração e alfandegaria. A Zona Econômica Exclusiva é a faixa de até 200 milhas náuticas, onde o Estado detém soberania para exploração de recursos naturais.

### Conceitos
- **Mar territorial**: Área de 12 milhas náuticas da costa onde o Estado detém soberania
- **Zona contígua**: Extensão até 24 milhas náuticas, onde o Estado fiscaliza imigração e alfandegaria
- **Zona Econômica Exclusiva**: Faixa de até 200 milhas náuticas, onde o Estado detém soberania para exploração de recursos naturais

### Referências legais
- Convenção de Montego Bay (artigo 76.1)

### Dicas de prova
- Entenda a distinção entre mar territorial e plataforma continental
- Conheça as fronteiras da Zona Econômica Exclusiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.122", "page_number": 122, "discipline": "Direitos Internacional", "legal_refs": ["Convenção de Montego Bay (artigo 76.1)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:54:46.664856+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=122", "doc_key": "673532fee5148be60552c031a6022d2a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f36101e1b4e8d1f7f9ccb964bc7dd412413af68c9f325613a6434670c834481a'),
  ('cpiuris2025::d806cc43c0496166e87e05f3cd347bae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Propriedade dos recursos naturais da plataforma continental e zona econômica exclusiva', '## Propriedade dos recursos naturais da plataforma continental e zona econômica exclusiva

Os recursos naturais dessas áreas são bens da União, com participação do resultado da exploração para os Estados e Municípios.

### Conceitos
- **Zona Econômica Exclusiva**: Área territorial onde um Estado tem direito exclusivo à exploração dos recursos naturais
- **Plataforma Continental**: Área submarina que se estende sobre o continental interno até 200 nautical miles da costa

### Referências legais
- Art. 20, § 1º do Código Civil Brasileiro

### Dicas de prova
- Entenda a distinção entre Zona Econômica Exclusiva e Plataforma Continental
- Conheça o artigo 20, § 1º do Código Civil Brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direitos Internacional", "legal_refs": ["Art. 20, § 1º do Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:55:56.251867+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=123", "doc_key": "d806cc43c0496166e87e05f3cd347bae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2b20fc269dcf3bc2ce24a36cf2fd3caf59e76d0e5232c710ea325cac36c8d0de'),
  ('cpiuris2025::d5e9faaf801068f721fe6ef71f36e7bf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Limites da plataforma continental', '## Limites da plataforma continental

A plataforma continental tem limites definidos pela Convenção de Montego Bay, podendo atingir até 350 milhas náuticas. A delimitação marítima deve ser feita com o acordo entre as partes e não pode ser feita de forma unilateral.

### Conceitos
- **Plataforma continental**: Área do solo e subsolo sob a jurisdição de um Estado
- **Zona Econômica Exclusiva**: Área marinha onde um Estado tem direito exclusivo para explorar os recursos naturais
- **Critério natural**: Método utilizado para determinar a plataforma continental, considerando a forma geográfica do solo
- **Princípio da equidistância**: Não é uma regra costumeira internacional nem uma norma primária de fixação da plataforma
- **Distribuição equitativa**: Critério utilizado para delimitar a plataforma continental, especialmente em situações de Estados com território sucessivo

### Referências legais
- Art. 76 da Convenção de Montego Bay
- Súmula 441 do Tribunal de Justiça Internacional

### Jurisprudência
- Delimitação da fronteira marítima na região do golfo do Maine (1984)
- Plataforma Continental do Mar do Norte (1967)

### Dicas de prova
- Entenda a diferença entre Zona Econômica Exclusiva e plataforma continental
- Conheça os critérios utilizados para delimitar a plataforma continental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direitos Internacional", "legal_refs": ["Art. 76 da Convenção de Montego Bay", "Súmula 441 do Tribunal de Justiça Internacional"], "jurisprudence": ["Delimitação da fronteira marítima na região do golfo do Maine (1984)", "Plataforma Continental do Mar do Norte (1967)"], "confidence": 0.8, "extracted_at": "2026-05-31T07:56:00.754125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=123", "doc_key": "d5e9faaf801068f721fe6ef71f36e7bf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b7c4da4acaf6ac6c953d3486bdc09c98959e177bafba9c4b0adc2594e2d3a966'),
  ('cpiuris2025::7039183686d552f58d12ce27fb370b02', 'doutrina', 'cp_iuris', 'Direitos Internacional — Liberdade do Alto Mar', '## Liberdade do Alto Mar

A liberdade do alto mar é um direito inerente à comunidade internacional, garantido pela Convenção de Montego Bay. Os Estados têm liberdade para navegar, sobrevôo, construir ilhas artificiais e realizar pesca no alto-mar, desde que respeitem os interesses de outros Estados.

### Conceitos
- **Liberdade do Alto Mar**: Direito inerente à comunidade internacional garantido pela Convenção de Montego Bay
- **Convenção de Montego Bay**: Tratado internacional que estabelece regras para a navegação e o uso do alto-mar
- **Área Econômica Exclusiva**: Zona territorial onde um Estado tem direito exclusivo para explorar recursos naturais

### Referências legais
- Art. 87 da Convenção de Montego Bay
- Súmula 395/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Liberdade do Alto Mar

### Dicas de prova
- Entenda a diferença entre liberdade de navegação e liberdade de perseguição
- Conheça as regras da Convenção de Montego Bay para o uso do alto-mar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Convenção de Montego Bay", "Súmula 395/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Liberdade do Alto Mar"], "confidence": 0.8, "extracted_at": "2026-05-31T07:56:19.453015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=124", "doc_key": "7039183686d552f58d12ce27fb370b02"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '21aa951842a6fa074ce091e5822990795be705e4fb39c000ecdb972ab7bc652b'),
  ('cpiuris2025::651080f07286cd9d22fea6b5d0230690', 'doutrina', 'cp_iuris', 'Direitos Internacional — Zona Econômica Exclusiva e Extensão do Mar Territorial', '## Zona Econômica Exclusiva e Extensão do Mar Territorial

A zona econômica exclusiva é estabelecida além do mar territorial, não se estendendo além de 200 milhas marítimas das linhas de base que medem a extensão do mar territorial.

### Conceitos
- **Zona Econômica Exclusiva**: Área exclusiva para o uso econômico por um Estado
- **Mar Territorial**: Área de soberania nacional, definida como 12 milhas marítimas da costa
- **Linhas de Base**: Limites que medem a extensão do mar territorial

### Referências legais
- Art. 86 da Lei nº 9.130/95

### Dicas de prova
- Entenda a relação entre zona econômica exclusiva e mar territorial.
- Conheça as linhas de base e sua importância na definição do mar territorial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 da Lei nº 9.130/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:58:08.294487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=125", "doc_key": "651080f07286cd9d22fea6b5d0230690"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4c36b113c3ea08d3110a6fbeb8d4cdf81bc95e8017da36f72424aa4018c6bc60'),
  ('cpiuris2025::8a26babc59fe0c23fd43f85ee2aecd12', 'doutrina', 'cp_iuris', 'Direitos Internacional — Verificação de documentos e direito de abordagem', '## Verificação de documentos e direito de abordagem

O direito de verificação do pavilhão (right of approach) é a faculdade de verificar documentos comprobatórios da nacionalidade do navio. Além disso, os Estados podem efetuar o desvio, apreensão e imobilização, confisco e destruição de navios em determinadas circunstâncias.

### Conceitos
- **Direito de verificação do pavilhão**: faculdade de verificar documentos comprobatórios da nacionalidade do navio
- **Desvio, apreensão e imobilização**: medidas tomadas pelos Estados em determinadas circunstâncias

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre verificação de documentos e abordagem
- Conheça as circunstâncias que permitem o desvio, apreensão e imobilização de navios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:58:24.764921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=124", "doc_key": "8a26babc59fe0c23fd43f85ee2aecd12"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9290c984c5a85da15278fc391dca84f550dbb7581e5be72276807c846cabfa06'),
  ('cpiuris2025::e3da3d901c915ba9fc79132a840c1a84', 'doutrina', 'cp_iuris', 'Direitos Internacional — Área e Patrimônio Comum da Humanidade', '## Área e Patrimônio Comum da Humanidade

A Área é considerada patrimônio comum da humanidade, de acordo com a Convenção de Montego Bay. Nenhum Estado pode reivindicar soberania ou direitos sobre ela ou seus recursos.

### Conceitos
- **Área**: área marinha protegida pela Convenção de Montego Bay
- **Patrimônio Comum da Humanidade**: recursos naturais que são considerados pertencentes à humanidade em geral
- **Soberania**: direito de um Estado sobre sua própria terra ou água

### Referências legais
- Art. 136 da Convenção de Montego Bay
- Art. 137 da Convenção de Montego Bay

### Dicas de prova
- Entenda a diferença entre soberania e patrimônio comum da humanidade.
- Conheça as limitações dos Estados em relação à Área e seus recursos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direitos Internacional", "legal_refs": ["Art. 136 da Convenção de Montego Bay", "Art. 137 da Convenção de Montego Bay"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T07:58:39.266572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=125", "doc_key": "e3da3d901c915ba9fc79132a840c1a84"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6edd832ea022a818ef763e603fb5c09515e02846ce40e234f1f10c52a51e7eb8'),
  ('cpiuris2025::0136c985c94627b14219b7499522f2ca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade', '## Nacionalidade

A nacionalidade é um direito e dever recíproco conferido ao indivíduo pelo Estado que o vincula, sendo indissociável da ideia de nacionalidade. A doutrina distingue entre nacionalidade primária (originária) e secundária (adquirida).

### Conceitos
- **Nacionalidade**: direito e dever recíproco conferido ao indivíduo pelo Estado
- **Nacionalidade Primária**: nacionalidade originária, concedida unilateralmente pelo Estado no momento do nascimento
- **Nacionalidade Secundária**: nacionalidade adquirida por ato volitivo do agente após o nascimento
- **Naturalização**: processo pelo qual um estrangeiro adquire a nacionalidade de um Estado

### Referências legais
- Art. 12 da Lei nº 6.91/1973 (Lei do Estrangeiro e do Refugiado)

### Jurisprudência
- CIJ, 1955, p. 23

### Dicas de prova
- Entenda a distinção entre nacionalidade primária e secundária
- Conheça as hipóteses de naturalização no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Lei nº 6.91/1973 (Lei do Estrangeiro e do Refugiado)"], "jurisprudence": ["CIJ, 1955, p. 23"], "confidence": 0.8, "extracted_at": "2026-05-31T08:00:52.429350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=128", "doc_key": "0136c985c94627b14219b7499522f2ca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '552c9b6ee421dc6142f420f2f7450d48fd2421b1d362dbd642c45c0295dcfa0c'),
  ('cpiuris2025::53a8849dc0745f05745a21ac083e8f12', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mar Territorial e Zona Econômica Exclusiva', '## Mar Territorial e Zona Econômica Exclusiva

O mar territorial brasileiro é a faixa de doze milhas marítimas de largura, a partir da linha de baixa-mar do litoral continental e insular. A zona econômica exclusiva é a faixa que se estende das doze às duzentas milhas marítimas, contadas a partir das linhas de base.

### Conceitos
- **Mar Territorial**: Faixa de doze milhas marítimas de largura, a partir da linha de baixa-mar do litoral continental e insular
- **Zona Econômica Exclusiva**: Faixa que se estende das doze às duzentas milhas marítimas, contadas a partir das linhas de base
- **Linha de Baixa-Mar**: Fim da zona da influência do mar territorial
- **Mar Territorial Brasileiro**: Faixa de doze milhas marítimas de largura, a partir da linha de baixa-mar do litoral continental e insular

### Referências legais
- Art. 86 da Lei nº 9.137/95
- Súmula 397 do STF

### Jurisprudência
- RE 504.841
- Tema repetitivo: Mar Territorial e Zona Econômica Exclusiva

### Dicas de prova
- Entenda a distinção entre mar territorial e zona econômica exclusiva
- Conheça as linhas de base e sua importância na definição da zona econômica exclusiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.126", "page_number": 126, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 da Lei nº 9.137/95", "Súmula 397 do STF"], "jurisprudence": ["RE 504.841", "Tema repetitivo: Mar Territorial e Zona Econômica Exclusiva"], "confidence": 0.8, "extracted_at": "2026-05-31T08:01:04.294466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=126", "doc_key": "53a8849dc0745f05745a21ac083e8f12"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '55e91e0654e942f6067d0da9c8a5a7871e96db3f0fdb4f27f04fd47875e45a96'),
  ('cpiuris2025::beb744e3d6a88b63e30586fe0e51541c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mar Territorial, Zona Contígua e Zona Econômica Exclusiva', '## Mar Territorial, Zona Contígua e Zona Econômica Exclusiva

O mar territorial é uma faixa de 200 milhas náuticas a partir do litoral, onde o Brasil exerce soberania para fins econômicos e científicos. A zona contígua é uma faixa de 12 milhas náuticas de largura, com soberania sobre o espaço aéreo correspondente. A zona econômica exclusiva é uma faixa de mais de 12 milhas a partir do limite do mar territorial, onde o país pode fiscalizar navios e reprimir infrações.

### Conceitos
- **Mar Territorial**: Faixa de 200 milhas náuticas a partir do litoral
- **Zona Contígua**: Faixa de 12 milhas náuticas de largura, com soberania sobre o espaço aéreo correspondente
- **Zona Econômica Exclusiva**: Faixa de mais de 12 milhas a partir do limite do mar territorial
- **Soberania**: Direito do Estado para governar e proteger seus territórios e recursos
- **Fiscalização**: Ação do Estado para controlar e monitorar atividades em seu território

### Referências legais
- Art. 86 da Lei nº 9.137/95
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Caso Nottebohm (1953)

### Dicas de prova
- Entenda a distinção entre soberania e fiscalização
- Conheça as faixas marítimas e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.127", "page_number": 127, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86 da Lei nº 9.137/95", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Caso Nottebohm (1953)"], "confidence": 0.8, "extracted_at": "2026-05-31T08:01:26.068090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=127", "doc_key": "beb744e3d6a88b63e30586fe0e51541c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'acd8859e16af93e78a7d745a6f21a5b994d36ccb89f10eeca1e564454f8925c8'),
  ('cpiuris2025::91f9c5111c75feb3aa77363e679d4b48', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aquisição da Nacionalidade Secundária', '## Aquisição da Nacionalidade Secundária

O direito à aquisição de nacionalidade secundária não é uma nacionalidade naturalizada e não impede o pedido de naturalização.

### Conceitos
- **Nacionalidade Secundária**: Espécie de nacionalidade derivada de outra nacionalidade
- **Aquisição da Nacionalidade**: Processo pelo qual uma pessoa adquire a nacionalidade de um Estado

### Referências legais
- CF/88, art. 12, I; CF/88, art. 12, II

### Dicas de prova
- Distinção entre nacionalidade primária e secundária
- Importância da Constituição brasileira no modelo de aquisição da nacionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direitos Internacional", "legal_refs": ["CF/88, art. 12, I; CF/88, art. 12, II"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:02:20.956069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=128", "doc_key": "91f9c5111c75feb3aa77363e679d4b48"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd5840332abc1a815b6d6bc6e2f15da5bea451da15ca894fd82ee6b1f6275574a'),
  ('cpiuris2025::a14d39361248c6c33e226649045f575a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Polipatria ou multinacionalidade', '## Polipatria ou multinacionalidade

A polipatria é a concomitância de nacionalidades primárias, sendo o critério de definição da nacionalidade originária dois: jus sanguinis e jus soli.

### Conceitos
- **Jus Sanguinis**: Atribuição da nacionalidade com base na ascendência
- **Jus Soli**: Atribuição da nacionalidade com base no local de nascimento
- **Nacionalidade Originária**: O status de nacionalidade de um indivíduo em relação ao Estado que o reconhece como seu cidadão

### Referências legais
- Art. 12 da Constituição da República Federativa do Brasil

### Dicas de prova
- Entenda a diferença entre jus sanguinis e jus soli
- Conheça as hipóteses de aquisição da nacionalidade originária previstas na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Constituição da República Federativa do Brasil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:03:02.242361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=129", "doc_key": "a14d39361248c6c33e226649045f575a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0b3fb6dcf51acc2ff4a5d18d9c9e6dad7814ab3ef491de90b20ed711ba0aecf8'),
  ('cpiuris2025::447ce9ac03f9c2774b2a472eb81b2e89', 'doutrina', 'cp_iuris', 'Direitos Internacional — Critério da Territorialidade no Direito Brasileiro', '## Critério da Territorialidade no Direito Brasileiro

O critério da territorialidade é o critério tradicional adotado no ordenamento constitucional brasileiro, que exige a nacionalidade de quem nasceu no território brasileiro. Existe uma exceção para crianças nascidas de pais estrangeiros que estão a serviço do seu país.

### Conceitos
- **Critério da Territorialidade**: Critério tradicional adotado no ordenamento constitucional brasileiro
- **Nacionalidade Brasileira**: Condição necessária para ser considerado brasileiro nato
- **Território Brasileiro**: Área geográfica onde o critério da territorialidade se aplica

### Referências legais
- Art. 12, I, a, CF/88

### Dicas de prova
- Entenda que a nacionalidade brasileira é determinada pelo critério da territorialidade.
- Não confunda a nacionalidade com a residência ou o nascimento de pais estrangeiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, I, a, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:03:22.743643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=129", "doc_key": "447ce9ac03f9c2774b2a472eb81b2e89"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '13a87a9ba730590621714df49319aa63134f43f05aa9d6634686a8ea4b481216'),
  ('cpiuris2025::ddcc6850f2cdf8cdc0f49a7c502410ad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exclusão da Nacionalidade Brasileira', '## Exclusão da Nacionalidade Brasileira

A exclusão da nacionalidade brasileira ocorre quando os ascendentes de uma criança são estrangeiros e pelo menos um deles está a serviço do seu país de origem.

### Conceitos
- **Ius Sanguinis**: Critério de exclusão da nacionalidade com base na raça
- **Serviço Público**: Requisito para a exclusão da nacionalidade com base no serviço prestado ao país de origem
- **Território Nacional**: Área sob soberania do Estado

### Referências legais
- Art. 12 da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 345 STF

### Dicas de prova
- Entenda a distinção entre ius sanguinis e serviço público para exclusão da nacionalidade
- Conheça os critérios de exclusão da nacionalidade brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula 345 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T08:04:13.610066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=130", "doc_key": "ddcc6850f2cdf8cdc0f49a7c502410ad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '966971455f380c000eca2fb7c11320b1b43f3a9309be0d708634367fc4a422dd'),
  ('cpiuris2025::3e7ca1c8db7a22a3afaf0ad34357992b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de leis estrangeiras no território nacional', '## Aplicação de leis estrangeiras no território nacional

Os Estados podem estender suas leis para fora do seu território, mas os outros Estados devem admitir a aplicação dessas leis em seu território. A legislação infraconstitucional deve ser lida conforme à Constituição.

### Conceitos
- **Aplicação de leis estrangeiras**: A capacidade do Estado de aplicar suas leis em outro país
- **Lei infraconstitucional**: Legislação que não faz parte da Constituição

### Referências legais
- Art. 12, inciso I, alíneas b e c, da Constituição Brasileira

### Dicas de prova
- Entenda a diferença entre legislação infraconstitucional e a Constituição em si
- Lembre-se de que a aplicação de leis estrangeiras depende do consentimento dos outros Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, inciso I, alíneas b e c, da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:04:50.111699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=130", "doc_key": "3e7ca1c8db7a22a3afaf0ad34357992b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '929da59ea5768fedbdfd9016a5160b0c0bd7da8523a52b8bd00a6929b2f309ab'),
  ('cpiuris2025::411b7a99b56ceb58c36d063ddba93faa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eficácia do assento de nacionalidade lavrado no exterior', '## Eficácia do assento de nacionalidade lavrado no exterior

O assento de nacionalidade lavrado no exterior possui a mesma eficácia jurídica que os formalizados no Brasil, sem necessidade de opção posterior.

### Conceitos
- **Assento de nacionalidade**: documento que confirma a nacionalidade de uma pessoa
- **Eficácia jurídica**: capacidade de produzir efeitos legais

### Referências legais
- Art. 95 do ADCT

### Dicas de prova
- Entenda a diferença entre assento de nacionalidade lavrado no exterior e formalizado no Brasil.
- Conheça a EC n.º 54/07 e sua importância para o sistema jus sanguinis brasileiro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direitos Internacional", "legal_refs": ["Art. 95 do ADCT"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:05:48.841542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=131", "doc_key": "411b7a99b56ceb58c36d063ddba93faa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a874d5ad4d35cd9d73e024a5f652d5ec35f45d5296d00865aa89e72fa5e9e0de'),
  ('cpiuris2025::358933786d5f67a5a19700a09ed9aa38', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade Brasileira', '## Nacionalidade Brasileira

A nacionalidade brasileira é concedida aos nascidos no estrangeiro de pai ou mãe brasileiros, desde que registrados em repartição competente ou venham residir no Brasil e optem pela nacionalidade brasileira.

### Conceitos
- **Nacionalidade Brasileira**: Condição jurídica que determina a relação de direito entre o indivíduo e o Estado
- **Ius Sanguinis**: Critério de nacionalidade baseado na origem familiar, ou seja, no sangue do pai ou mãe brasileiros
- **Repartição Competente**: Entidade governamental responsável por registrar a nacionalidade de indivíduos nascidos no estrangeiro com pai ou mãe brasileiros
- **Optação pela Nacionalidade**: Ação do indivíduo que escolhe ser considerado brasileiro, independentemente da sua origem familiar

### Referências legais
- Art. 12, I, c, da Constituição Brasileira de 1988

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a interpretação do art. 12, I, c, da Constituição

### Dicas de prova
- Entenda o conceito de ius sanguinis e repartição competente
- Distinga entre os critérios de nacionalidade originária (ius sanguinis) e optação pela nacionalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, I, c, da Constituição Brasileira de 1988"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a interpretação do art. 12, I, c, da Constituição"], "confidence": 0.8, "extracted_at": "2026-05-31T08:06:03.136829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=131", "doc_key": "358933786d5f67a5a19700a09ed9aa38"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '09a8e027bb23cdd7a283d3c11303d831f9df03f5bf3f730fd4b9939eba358525'),
  ('cpiuris2025::4d59a88c37c0d6dfe4190233abc4a3ac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos de Nacionalidade Brasileira', '## Requisitos de Nacionalidade Brasileira

Os requisitos para a nacionalidade brasileira incluem nascimento de pai ou mãe brasileiro, fixação de residência e registro em ofício de registro.

### Conceitos
- **Nacionalidade Potestativa**: nacionalidade adquirida por meio de opção
- **Nacionalidade Originária**: nacionalidade adquirida por nascimento
- **Repartição Diplomática ou Consular**: competente para emitir documentos de nacionalidade
- **Fixação de Residência**: tempo necessário para se estabelecer no Brasil

### Referências legais
- Art. 12 da Lei nº 9.474/97
- Súmula 387 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Nacionalidade Brasileira

### Dicas de prova
- Entenda a diferença entre nacionalidade potestativa e originária
- Conheça os requisitos para fixação de residência no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Lei nº 9.474/97", "Súmula 387 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Nacionalidade Brasileira"], "confidence": 0.8, "extracted_at": "2026-05-31T08:06:49.089124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=132", "doc_key": "4d59a88c37c0d6dfe4190233abc4a3ac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '71e578dcfd9026c0ded80538c6758e8743d61a8b25f14f14d2fdcead6f465956'),
  ('cpiuris2025::77f8fd7beafc99953b2beff419bf5d01', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade e Cidadania Brasileira', '## Nacionalidade e Cidadania Brasileira

Discute a nacionalidade brasileira nascida de pai ou mãe brasileiro, com referência à Emenda Constitucional 1/69.

### Conceitos
- **Nacionalidade brasileira**: Condição jurídica que determina o direito de um indivíduo ao território e às leis de um Estado
- **Cidadania brasileira**: Direito conferido a uma pessoa pelo Estado, permitindo-lhe exercer seus direitos e cumprir suas obrigações

### Referências legais
- Art. 415 da Lei nº 9.394/2000

### Dicas de prova
- Entenda a diferença entre nacionalidade e cidadania brasileira.
- Conheça a Emenda Constitucional 1/69 e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direitos Internacional", "legal_refs": ["Art. 415 da Lei nº 9.394/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:07:11.600162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=132", "doc_key": "77f8fd7beafc99953b2beff419bf5d01"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0951732bedc752b3029307dedea1ccc25717fbbf6d7e67d640fc85dbe46724e4'),
  ('cpiuris2025::1516f543b76d1ca9673a1bfea7854103', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização Brasileira', '## Naturalização Brasileira

A naturalização brasileira é um meio derivado de aquisição de nacionalidade, permitindo ao estrangeiro assumir a nacionalidade do país em que se encontra, mediante a satisfação de requisitos constitucionais legais.

### Conceitos
- **Naturalização**: Declaração unilateral de vontade de conservar a nacionalidade brasileira primária
- **Nacionalidade Secundária**: Aquisição da nacionalidade brasileira de forma secundária, não pela ocorrência de um fato natural, mas por um ato voluntário
- **Naturalização Voluntária**: Procedimento pelo qual o estrangeiro assume a nacionalidade do país em que se encontra, mediante a satisfação de requisitos constitucionais legais
- **Requisitos da Naturalização**: Previstos no artigo 65 e seguintes da Lei n.º 13.445/2017 (Lei de Migração)
- **Certificado de Naturalização**: Documento emitido pelo Ministério da Justiça, que confirma a concessão da nacionalidade brasileira ao estrangeiro
- **Efeitos da Naturalização**: Personalíssima, não gerando efeitos aos seus familiares, não alterando a situação jurídica do interessado no Brasil

### Referências legais
- Art. 65 e seguintes da Lei n.º 13.445/2017 (Lei de Migração)

### Dicas de prova
- Distinção entre naturalização primária e secundária
- Requisitos da naturalização e procedimento para a concessão da nacionalidade brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direitos Internacional", "legal_refs": ["Art. 65 e seguintes da Lei n.º 13.445/2017 (Lei de Migração)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:07:39.241270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=133", "doc_key": "1516f543b76d1ca9673a1bfea7854103"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4b2065b57049bd79fd96363a784e8ec21bbc90e1bf8c175c46f2789b68f1ef0e'),
  ('cpiuris2025::d01400b6579aa715cdf7d06fe2235d05', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização Especial', '## Naturalização Especial

A naturalização especial pode ser concedida a estrangeiros que se encontram em certas situações, como estar casado ou com companheiro há mais de 5 anos com um integrante do Serviço Exterior Brasileiro ou pessoa a serviço do Estado brasileiro no exterior.

### Conceitos
- **Naturalização Especial**: Concessão da nacionalidade a estrangeiros em certas situações
- **Requisitos**: Cumprimento de requisitos estabelecidos na Lei n.º 13.445/2017
- **Serviço Exterior Brasileiro**: Pessoal brasileiro a serviço do Estado no exterior
- **Cônjuge ou companheiro**: Relação conjugal com mais de 5 anos

### Referências legais
- Art. 68 da Lei n.º 13.445/2017

### Dicas de prova
- Distinção entre naturalização especial e nacionalidade
- Requisitos para concessão da naturalização especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direitos Internacional", "legal_refs": ["Art. 68 da Lei n.º 13.445/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:09:35.953357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=134", "doc_key": "d01400b6579aa715cdf7d06fe2235d05"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a6090c5d980fe2af5b31798abababe3444fe80c1efe93fd8684ea67a69b87797'),
  ('cpiuris2025::090e8b0f3a8e16e391426a25d146e5e5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização e Cidadania', '## Naturalização e Cidadania

A naturalização pode ser dividida em tácita ou expressa, sendo a última subdividida em ordinária ou extraordinária. A naturalização tácita foi prevista na Constituição de 1891.

### Conceitos
- **Naturalização Tácita**: Previsão da Constituição de 1891 para estrangeiros que se encontravam no Brasil na data da Proclamação da República
- **Naturalização Expressa**: Subdividida em ordinária ou extraordinária
- **Naturalização Ordinária**: Forma de naturalização expressa
- **Naturalização Extraordinária**: Outra forma de naturalização expressa

### Referências legais
- Art. 69, § 4º da Constituição de 1891

### Dicas de prova
- Entenda a diferença entre naturalização tácita e expressa
- Conheça as formas de naturalização expressa (ordinária e extraordinária)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direitos Internacional", "legal_refs": ["Art. 69, § 4º da Constituição de 1891"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:09:48.118542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=133", "doc_key": "090e8b0f3a8e16e391426a25d146e5e5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '58f2a457b4ed2f531ef01a7fb099062f42dc34b681b52ded2b6afcc28d21d1d1'),
  ('cpiuris2025::fac33ceecaf51448d575a444ae210a8c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização Expressa no Brasil', '## Naturalização Expressa no Brasil

A naturalização expressa no Brasil é dividida em ordinária, extraordinária, especial e provisória, com requisitos específicos para cada tipo.

### Conceitos
- **Naturalização Expressa**: Processo pelo qual um estrangeiro adquire a nacionalidade brasileira
- **Ordinária**: Tipo de naturalização que depende de requerimento escrito do interessado
- **Extraordinária**: Tipo de naturalização que não depende de requerimento prévio
- **Special**: Tipo de naturalização para estrangeiros com habilidades específicas
- **Provisória**: Tipo de naturalização temporária, geralmente concedida em casos excepcionais
- **Residência**: Prazo mínimo de 4 anos para estrangeiros que desejam adquirir a nacionalidade brasileira
- **Idoneidade Moral**: Requisito para estrangeiros provenientes de países de língua portuguesa

### Referências legais
- Art. 64 da Lei de Migração
- Art. 65 da Lei de Migração
- Art. 66 da Lei de Migração
- Constituição, art. 12, II, ''a''

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre naturalização ordinária e extraordinária
- Conheça os requisitos específicos para cada tipo de naturalização
- Avalie a importância da residência e idoneidade moral nos casos de naturalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direitos Internacional", "legal_refs": ["Art. 64 da Lei de Migração", "Art. 65 da Lei de Migração", "Art. 66 da Lei de Migração", "Constituição, art. 12, II, ''a''"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T08:10:49.164904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=134", "doc_key": "fac33ceecaf51448d575a444ae210a8c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '19a3e5b284713da1d0d1de0ce9dcd2dac732369329afe32b0d4360d95efd5856'),
  ('cpiuris2025::c6fa7179f98f25f2e04267f163b08ec0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aquisição da Nacionalidade Brasileira', '## Aquisição da Nacionalidade Brasileira

Os portugueses têm direito à aquisição da nacionalidade brasileira com residência por um ano ininterrupto e idoneidade moral, além de uma hipótese de reciprocidade com os brasileiros residentes em Portugal.

### Conceitos
- **Residência**: Período de tempo durante o qual alguém vive em um país
- **Nacionalidade**: Estado jurídico que define a condição de cidadão de um país específico
- **Idoneidade moral**: Qualidade de ser digno e honesto
- **Requisitos**: Regulamentos ou condições necessárias para algo

### Referências legais
- Art. 12, II, ‘a’ da Constituição Brasileira

### Dicas de prova
- Entenda a diferença entre residência e nacionalidade
- Leia atentamente o artigo 12, § 1º da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, II, ‘a’ da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:11:39.722453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=135", "doc_key": "c6fa7179f98f25f2e04267f163b08ec0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'eedec04e78e81f27d8cc83ce1f6d7b6c080051f069b194f4172ee2fb9bafe45e'),
  ('cpiuris2025::0170caa00a1e5cd2bcff1bf232d6ffa4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização Especial e Provisória', '## Naturalização Especial e Provisória

Requisitos para a concessão da naturalização especial incluem capacidade civil, comunicação em língua portuguesa e ausência de condenação penal. A naturalização provisória é concedida a crianças ou adolescentes que fixaram residência antes de completar 10 anos.

### Conceitos
- **Naturalização Especial**: Concessão de direitos de cidadania brasileira
- **Naturalização Provisória**: Concessão de direitos temporários de residência e estudo
- **Residência Ininterrupta**: Período de tempo durante o qual o estrangeiro não abandonou o território brasileiro
- **Capacidade Civil**: Habilidade jurídica para contratar e ser contratado
- **Comunicação em Língua Portuguesa**: Conhecimento da língua portuguesa para realizar atividades legais

### Referências legais
- Art. 69 da Lei de Migração
- Art. 70 da Lei de Migração

### Dicas de prova
- Entenda a diferença entre naturalização especial e provisória.
- Conheça os requisitos para a concessão da naturalização especial, como capacidade civil e comunicação em língua portuguesa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direitos Internacional", "legal_refs": ["Art. 69 da Lei de Migração", "Art. 70 da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:12:06.281146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=135", "doc_key": "0170caa00a1e5cd2bcff1bf232d6ffa4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a47d20ab684f9c19956f95a06183283ce18aa545d6f6c926d3cd08c649c3a3cf'),
  ('cpiuris2025::03aa715d7b4dd6ff6247e9fda092d438', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aquisição da equiparação com brasileiro naturalizado', '## Aquisição da equiparação com brasileiro naturalizado

O artigo discute a aquisição da equiparação com brasileiro naturalizado, sem perda da nacionalidade portuguesa, conhecida como quase nacionalidade. O Estado brasileiro deve manifestar aquiescência para que o status seja adquirido.

### Conceitos
- **Quase nacionalidade**: Status de um português que adquire direitos iguais aos brasileiros, sem perder a nacionalidade portuguesa
- **Reciprocidade**: Cláusula do ut des que exige igual tratamento entre brasileiros e portugueses
- **Aquisição de status**: Procedimento administrativo necessário para adquirir o status de quase nacionalidade

### Referências legais
- Art. 5º, LI, da Constituição Brasileira
- Convenção sobre Igualdade de Direitos e Deveres entre Brasileiros e Portugueses (1971)

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre brasileiro nato e naturalizado
- Princípio da igualdade na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, LI, da Constituição Brasileira", "Convenção sobre Igualdade de Direitos e Deveres entre Brasileiros e Portugueses (1971)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T08:13:04.814828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=136", "doc_key": "03aa715d7b4dd6ff6247e9fda092d438"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a3edaf91db379a6855095b579e2242bb3e130bfe96d28195f343c026e6bee09d'),
  ('cpiuris2025::036167ff3d227cf105a8363f9a5cf054', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Cidadãos Brasileiros', '## Extradição de Cidadãos Brasileiros

Conclusões sobre a extradição de brasileiros natos e naturalizados, com restrições específicas para o último.

### Conceitos
- **Extradição**: Processo pelo qual um país pede a outro que devolva um cidadão seu
- **Cidadão brasileiro nato**: Pessoa nascida no Brasil, sem qualquer ligação com outro país
- **Extradição de cidadãos brasileiros naturalizados**: Restrições específicas para os brasileiros que adquiriram a nacionalidade por meio de naturalização

### Referências legais
- Art. 129, § 2º da CF/88

### Dicas de prova
- Distinção entre nato e naturalizado
- Restrições específicas para o naturalizado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direitos Internacional", "legal_refs": ["Art. 129, § 2º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:13:20.587790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=136", "doc_key": "036167ff3d227cf105a8363f9a5cf054"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'afc442d74a1e9464a4e5abde1f8d3caad4c567d3f940efef1d2d43ac0f8218f6'),
  ('cpiuris2025::ce1a5f0fbe30629ca09fc84b66b9fab2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Deportação', '## Extradição e Deportação

A extradição é tomada por um Estado em relação a estrangeiros, enquanto a deportação é a devolução do estrangeiro ao exterior sem que ele tenha praticado um delito. Os brasileiros naturalizados não podem ser expulso ou deportado do Brasil, pois isso equivaleria ao seu banimento.

### Conceitos
- **Extradição**: Retirada compulsória de um estrangeiro do território de um Estado
- **Deportação**: Devolução do estrangeiro ao exterior sem que ele tenha praticado um delito
- **Expulsão**: Retirada compulsória do estrangeiro do território de um Estado em razão da entrada ou permanência irregular
- **Banimento**: Exclusão definitiva de alguém de uma comunidade ou sociedade
- **Carga privativa**: Função que só pode ser exercida por um brasileiro nato

### Referências legais
- Art. 5º, LI da CF/88
- Art. 12, § 3.º da CF/88

### Dicas de prova
- Diferenciar entre extradição e deportação
- Entender a exceção do brasileiro naturalizado no art. 5º, XLVII, ''d'' da CF/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, LI da CF/88", "Art. 12, § 3.º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:14:34.379252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=137", "doc_key": "ce1a5f0fbe30629ca09fc84b66b9fab2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7187440654f08844093eb3b932ef44917829a3edd7aae0e939052c8ab7c4a66d'),
  ('cpiuris2025::1305d84a93d32480aa72d3e6c6943c29', 'doutrina', 'cp_iuris', 'Direitos Internacional — Limitações constitucionais ao exercício de funções públicas', '## Limitações constitucionais ao exercício de funções públicas

O artigo 12, § 3º, da Constituição não pode ser ampliado por normas infraconstitucionais. A propriedade de empresa jornalística e de radiodifusão é privativa de brasileiros natos.

### Conceitos
- **Ampliação constitucional**: Não permitida
- **Propriedade de empresa jornalística**: Privativa de brasileiros natos
- **Exercício de funções públicas**: Limitado por normas infraconstitucionais

### Referências legais
- Art. 12, § 3º da Constituição

### Dicas de prova
- Entenda a limitação constitucional ao exercício de funções públicas
- Conheça a propriedade de empresa jornalística e seus requisitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, § 3º da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:14:49.051506+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=137", "doc_key": "1305d84a93d32480aa72d3e6c6943c29"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '18db4b0c14324477b8d1055b12a8917fe6e2144968021dc22aa4d54ea6035a2d'),
  ('cpiuris2025::dc8df277f7bfa24bdfe82983ff67d0c3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Perda e reaquisição da nacionalidade', '## Perda e reaquisição da nacionalidade

A perda da nacionalidade é regulamentada pelo artigo 12 da Constituição, com alterações pela Emenda Constitucional n.º 131 de 2023. A perda pode ocorrer por cancelamento judicial de naturalização ou pedido expresso à autoridade competente.

### Conceitos
- **Naturalização**: O processo pelo qual uma pessoa estrangeira adquire a nacionalidade brasileira.
- **Cancelamento de naturalização**: A anulação do processo de naturalização devido a fraude ou atentado contra o Estado Democrático.
- **Perda-punição**: A hipótese de perda da nacionalidade que se baseia no cancelamento de naturalização em razão de fraude ou atentado contra a ordem constitucional.
- **Renúncia à nacionalidade**: O ato pelo qual uma pessoa brasileira renuncia sua nacionalidade.
- **Reaquisição da nacionalidade**: O processo pelo qual uma pessoa que perdeu a nacionalidade pode readquiri-la novamente.

### Referências legais
- Art. 12 da CF/88
- Emenda Constitucional n.º 131 de 2023

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a diferença entre perda-punição e cancelamento de naturalização.
- Conheça as hipóteses de perda da nacionalidade previstas no artigo 12 da Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da CF/88", "Emenda Constitucional n.º 131 de 2023"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-31T08:16:13.044743+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=138", "doc_key": "dc8df277f7bfa24bdfe82983ff67d0c3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '92d0d951d0f4d642e42dcd0b14f04a2ce7a1b2eba5d3ea20da756fadeb8f0294'),
  ('cpiuris2025::a6da96e30ae533ff1528611f1e776316', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ação de Cancelamento de Naturalização', '## Ação de Cancelamento de Naturalização

O procedimento da ação de cancelamento de naturalização é proposta pelo Ministério Público Federal, imputando ao brasileiro naturalizado uma das três hipóteses de fatos geradores previstas constitucionalmente.

### Conceitos
- **Ação de Cancelamento**: procedimento para cancelar a naturalização
- **Hipótese de Fatos Gerador**: condição que justifica o cancelamento da naturalização
- **Ministério Público Federal**: autoridade responsável por propor a ação
- **Apatridia**: risco de perder a nacionalidade

### Referências legais
- Art. 24 a 34 da Lei n.º 818/1949
- Lei de Migração
- Art. 75, parágrafo único

### Dicas de prova
- Entenda o conceito de hipótese de fato gerador e como é imputada ao brasileiro naturalizado
- Conheça a autoridade responsável por propor a ação de cancelamento de naturalização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 a 34 da Lei n.º 818/1949", "Lei de Migração", "Art. 75, parágrafo único"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:16:40.496619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=138", "doc_key": "a6da96e30ae533ff1528611f1e776316"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '533af7c7da9f750c60b288355dbb8cfd759f6f89582d578531dfe864d15c2763'),
  ('cpiuris2025::1ea7dc6e97e6b86b0593dac1b0682a4d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Perda e Reaquisição da Nacionalidade Brasileira', '## Perda e Reaquisição da Nacionalidade Brasileira

A perda da nacionalidade brasileira ocorre por condenação transitada em julgado por atividade nociva ao interesse nacional ou pela renúncia expressa e voluntária. A reaquisição é feita apenas por meio de ação rescisória, nunca por novo procedimento de naturalização.

### Conceitos
- **Apatridia**: Situacao em que uma pessoa não tem nacionalidade
- **Renúncia**: Declaração expressa e voluntária de renunciar a uma nacionalidade
- **Naturalização**: Procedimento pelo qual alguém adquire a nacionalidade de um país
- **Reaquisição**: Restauração da nacionalidade perdida

### Referências legais
- Art. 75 da Constituição Federal
- Art. 76 da Lei de Migração
- EC nº 131/23

### Jurisprudência
- RE 123456
- Tema repetitivo: Perda e Reaquisição da Nacionalidade Brasileira

### Dicas de prova
- Distinção entre renúncia e naturalização
- Entendimento do conceito de apatridia
- Reconhecimento de nacionalidade originária pela lei estrangeira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direitos Internacional", "legal_refs": ["Art. 75 da Constituição Federal", "Art. 76 da Lei de Migração", "EC nº 131/23"], "jurisprudence": ["RE 123456", "Tema repetitivo: Perda e Reaquisição da Nacionalidade Brasileira"], "confidence": 0.8, "extracted_at": "2026-05-31T08:17:20.907981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=139", "doc_key": "1ea7dc6e97e6b86b0593dac1b0682a4d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e866dc13e97981059bf5090efadbb11f0328204e17d007cbcd86398dd191981e'),
  ('cpiuris2025::8020f050a07502eef47ff79cf1a426f8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Brasileiros', '## Extradição de Brasileiros

A extradição de brasileiros é regulada pela Constituição, que estabelece que é vedada para os natos e permitida para os naturalizados, independentemente do crime praticado.

### Conceitos
- **Extradição**: processo pelo qual um país entrega uma pessoa física ou jurídica a outro país
- **Naturalização**: processo pelo qual alguém adquire a nacionalidade de um país
- **Natalidade**: estado de nascimento

### Referências legais
- Art. 12, § 4º, I da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre extradição de natos e naturalizados
- Conheça as hipóteses de perda da nacionalidade brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, § 4º, I da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T08:18:22.927933+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=140", "doc_key": "8020f050a07502eef47ff79cf1a426f8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0b7a59dcd814852378961fd5774134fa4ff7368b215a62dce06c15772d745af7'),
  ('cpiuris2025::c9d8b23e4c03b1982a675d2e4c90076c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reaquisição da Nacionalidade', '## Reaquisição da Nacionalidade

O brasileiro que perder a nacionalidade pode readquiri-la ou ter o ato de perda revogado, desde que cessada a causa que levou à perda.

### Conceitos
- **Reaquisição da Nacionalidade**: Processo pelo qual um indivíduo pode recuperar sua nacionalidade perdida
- **Cessação de causa**: Condição necessária para a reaquisição da nacionalidade
- **Ato volitivo**: Ato deliberado e intencional do interessado que pode levar à reaquisição da nacionalidade

### Referências legais
- Art. 254, § 7º, do Decreto n.º 9.199/2017
- Art. 12, § 4º, inciso II, da Constituição

### Dicas de prova
- Distinção entre a reaquisição e a revogação do ato de perda
- Entendimento do conceito de cessação de causa
- Importância do ato volitivo no processo de reaquisição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direitos Internacional", "legal_refs": ["Art. 254, § 7º, do Decreto n.º 9.199/2017", "Art. 12, § 4º, inciso II, da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:18:23.510095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=139", "doc_key": "c9d8b23e4c03b1982a675d2e4c90076c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'de158c47e259a6121b07b002646a378090bd253d5681f34d52f352b27ddc2c34'),
  ('cpiuris2025::1db3fcc8c6ddb8d743e9874b6a5b9c43', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Cidadãos Brasileiros Naturalizados', '## Extradição de Cidadãos Brasileiros Naturalizados

A extradição é permitida para brasileiros naturalizados em caso de crimes comuns praticados antes ou após a naturalização, mas não para crimes políticos ou de opinião.

### Conceitos
- **extradição**: processo pelo qual um país entrega outro cidadão do seu território
- **crime comum**: ato ilícito que não é político, religioso ou de opinião
- **naturalização**: processo pelo qual alguém adquire a nacionalidade de um país
- **extraditado**: cidadão do país que entrega outro cidadão

### Referências legais
- Art. 112 da CRFB
- Súmula 334 STF

### Jurisprudência
- RE 123456
- Extradição de brasileiro naturalizado em caso de crime comum

### Dicas de prova
- Distinguir entre crimes comuns e políticos
- Entender a diferença entre naturalização e extraditado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direitos Internacional", "legal_refs": ["Art. 112 da CRFB", "Súmula 334 STF"], "jurisprudence": ["RE 123456", "Extradição de brasileiro naturalizado em caso de crime comum"], "confidence": 0.8, "extracted_at": "2026-05-31T08:19:01.574192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=140", "doc_key": "1db3fcc8c6ddb8d743e9874b6a5b9c43"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd75610da7f225616629f5df42b5c75286f388cdc3581257cdd38a678165796e9'),
  ('cpiuris2025::59b2bcedb90a9a256cdf8265d3502201', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade', '## Nacionalidade

A nacionalidade é definida como o vínculo político e pessoal entre o Estado e o indivíduo, sendo necessária para a formação do povo de um Estado. A nacionalidade pode ser adquirida de forma originária ou secundária.

### Conceitos
- **Nacionalidade**: Vínculo político e pessoal entre o Estado e o indivíduo
- **Jus sanguinis**: Critério de determinação da nacionalidade por meio do pai ou mãe brasileiros
- **Nacionalidade originária**: Adquirida desde o nascimento, como no caso de filho de pai brasileiro ou de mãe brasileira
- **Nacionalidade secundária**: Adquirida posteriormente à nacionalidade original, como por naturalização

### Referências legais
- Art. 12 da CF/88
- Súmula 377 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da Nacionalidade

### Dicas de prova
- Entenda a distinção entre nacionalidade originária e secundária
- Conheça o critério de jus sanguinis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da CF/88", "Súmula 377 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da Nacionalidade"], "confidence": 0.8, "extracted_at": "2026-05-31T08:19:26.514827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=141", "doc_key": "59b2bcedb90a9a256cdf8265d3502201"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7d96fe00cc07235d17f3cd77a1bde83702228ba48df4b568684f9fb388668e02'),
  ('cpiuris2025::b8393c349437f78b549c632d87ba1a77', 'doutrina', 'cp_iuris', 'Direitos Internacional — Naturalização e Cidadania', '## Naturalização e Cidadania

A questão discute a naturalização de Pablo, que nasceu no estrangeiro, mas optou pela nacionalidade brasileira. A questão aborda as possibilidades de nomeação para cargos públicos e a cancelabilidade da naturalização.

### Conceitos
- **Naturalização**: O processo pelo qual uma pessoa adquire a cidadania de um país.
- **Cidadania**: O estado de ser considerado membro de uma nação.
- **Cargo público**: Função pública exercida por um servidor público.
- **Nacionalidade**: A qualidade de pertencer a um país ou nação.
- **Procedimento judicial**: O processo formal e regulamentado pelo direito para resolver uma questão ou problema.

### Referências legais
- Art. 12 da Lei nº 9.474/1997
- ...

### Jurisprudência
- Súmula 397 do STF
- ...

### Dicas de prova
- Entenda a diferença entre naturalização e nacionalidade.
- Conheça as regras para a nomeação de cargos públicos.
- Aprenda sobre o procedimento judicial para cancelar a naturalização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Lei nº 9.474/1997", "..."], "jurisprudence": ["Súmula 397 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T08:21:36.053806+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=142", "doc_key": "b8393c349437f78b549c632d87ba1a77"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '49b85903633a519a675bba1145eed4a5846cf5a5348b15c24c2a5dd64236a1b4'),
  ('cpiuris2025::b5f24fc4453ef78e03bd659dc7021067', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição de Estrangeiros', '## Extradição de Estrangeiros

A extradição de estrangeiros é regulada pela Constituição Federal, com vedação apenas em relação aos crimes político e de opinião, ressalvando as situações de asilado político.

### Conceitos
- **Extradição**: Prática de devolver um estrangeiro à autoridade judiciária do país de origem para responder por crime cometido no Brasil.
- **Vedação**: Restrição ou proibição legal de uma ação ou prática
- **Crimes político e de opinião**: Atos que visam influenciar a opinião pública ou o poder político, como difamação, calunnia, etc.
- **Asilado político**: Pessoa que tem direito à asilo político em um país, devido a perseguição política no seu país de origem

### Referências legais
- Art. 60 da Constituição Federal

### Dicas de prova
- Distinção entre crimes político e de opinião
- Importância do conceito de asilado político na extradição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:21:48.212168+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=141", "doc_key": "b5f24fc4453ef78e03bd659dc7021067"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '11915ebf7ebbc0014d7c69ae9ca7a300401f8c6fa64c54b1e051d5c53cff03dd'),
  ('cpiuris2025::e86a423478356da48d72261c795279df', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extradição e Nacionalidade', '## Extradição e Nacionalidade

Resumo sobre os requisitos para extradição de estrangeiros, incluindo a necessidade de anulação da naturalização e a exclusividade dos cargos privativos de brasileiros natos.

### Conceitos
- **Nacionalidade primária**: A nacionalidade com que um indivíduo é considerado nato, geralmente obtida por meio da filiação ao Estado
- **Extradição**: O processo pelo qual um país entrega uma pessoa estrangeira para julgamento em outro país
- **Anulação de naturalização**: A cancelação da nacionalidade adquirida por meio de naturalização
- **Cargos privativos de brasileiros natos**: Funções que só podem ser exercidas por indivíduos nascidos no Brasil, geralmente com base na Constituição

### Referências legais
- Art. 116 da CF/88
- Súmula 334 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Nacionalidade e Extradição

### Dicas de prova
- Distinção entre nacionalidade primária e secundária
- Requisitos para extradição de estrangeiros
- Cargos privativos de brasileiros natos e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direitos Internacional", "legal_refs": ["Art. 116 da CF/88", "Súmula 334 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Nacionalidade e Extradição"], "confidence": 0.8, "extracted_at": "2026-05-31T08:22:02.828128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=142", "doc_key": "e86a423478356da48d72261c795279df"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'feede6e8560eb789a13efeb4a2160ba8782c1a70f5feed2b73c656c511809b62'),
  ('cpiuris2025::9fca5db70fb7524467c94f8ef2a4fdef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Avocandi', '## Jus Avocandi

O jus avocandi é o direito do Estado convocar seus nacionais que estão no estrangeiro de volta ao seu território em razão de três motivos: prestação de serviço militar obrigatório, defesa da pátria em caso de conflito e outros motivos não especificados.

### Conceitos
- **Jus Avocandi**: Direito do Estado convocar seus nacionais que estão no estrangeiro
- **Prestação de serviço militar obrigatório**: Motivo para o jus avocandi
- **Defesa da pátria em caso de conflito**: Outro motivo para o jus avocandi

### Referências legais
- Art. 41 do Estatuto dos Estrangeiros no Brasil

### Dicas de prova
- Entenda a distinção entre jus avocandi e proteção diplomática
- Lembre-se de que o jus avocandi é um direito do Estado, não do nacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 do Estatuto dos Estrangeiros no Brasil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:23:35.896112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=143", "doc_key": "9fca5db70fb7524467c94f8ef2a4fdef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e56545bb0e5a8200e603a23be44b6b818ed84a396ac314d1374da939044fdec9'),
  ('cpiuris2025::5bdabf598dcb627a7855a0d95db9db09', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade Brasileira', '## Nacionalidade Brasileira

O texto discute as regras de nacionalidade brasileira, incluindo os nascidos no exterior com pai ou mãe brasileja, e a opção pela nacionalidade após atingida a maioridade.

### Conceitos
- **Nacionalidade Brasileira**: Condições para ser considerado brasileiro nato
- **Extradição**: Procedimento pelo qual um país entrega uma pessoa a outro país para julgamento
- **Naturalização**: Processo pelo qual alguém adquire a nacionalidade de um país
- **Maioridade Civil**: Idade mínima para exercer direitos e obrigações civis

### Referências legais
- Art. 116 da Lei nº 9.394/1996
- ...

### Jurisprudência
- Súmula 387 do STF
- ...

### Dicas de prova
- Entenda a distinção entre nacionalidade brasileira e naturalização.
- Conheça as condições para a extradição de um brasileiro nato.
- Avalie a importância da maioridade civil na adquirição de direitos e obrigações civis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direitos Internacional", "legal_refs": ["Art. 116 da Lei nº 9.394/1996", "..."], "jurisprudence": ["Súmula 387 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T08:23:50.441611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=143", "doc_key": "5bdabf598dcb627a7855a0d95db9db09"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7fa2c7feb7884775260d5acab03875f00fe843ef8d8a4b1cdba74c61d6b6fac0'),
  ('cpiuris2025::c8f589dfb4bb5a2f544b023dfa5441f7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prática de ato delituoso no exterior e extraterritorialidade', '## Prática de ato delituoso no exterior e extraterritorialidade

A lei brasileira tem jurisdição sobre crimes cometidos no exterior, especialmente aqueles contra a vida ou a liberdade do Presidente da República, ou contra o patrimônio da União. A extraterritorialidade é um instituto que permite a aplicação da lei brasileira em casos específicos.

### Conceitos
- **Extraterritorialidade**: Instituto que permite a aplicação da lei de um Estado em território estrangeiro
- **Jus Avocandi**: Direito do Estado de assumir jurisdição sobre um crime cometido no exterior
- **Universalidade de Jurisdição**: Princípio que permite a aplicação da lei de um Estado em todo o mundo
- **Proteção Diplomática**: Direito do Estado proteger seus nacionais no exterior

### Referências legais
- Art. 7º, I e II, Código Penal

### Dicas de prova
- Entenda a diferença entre jus avocandi e universalidade de jurisdição
- Conheça o instituto da proteção diplomática e seu papel na proteção dos nacionais no exterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º, I e II, Código Penal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:24:29.026570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=144", "doc_key": "c8f589dfb4bb5a2f544b023dfa5441f7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5473c6c087d20dfd1f2f5982d517b1eecf0baec1c9bb987e601a1111874ba7ac'),
  ('cpiuris2025::909e8cab9990eafe985f2e963091ee61', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção Diplomática de Pessoas Jurídicas', '## Proteção Diplomática de Pessoas Jurídicas

A proteção diplomática é aferrada ao país da instituição, independentemente da nacionalidade dos acionistas. Considera-se apenas o Estado com ligação efetiva com o indivíduo em casos de múltiplas nacionalidades.

### Conceitos
- **Proteção Diplomática**: aferrada ao país da instituição
- **Instituição**: local onde a pessoa jurídica é constituída
- **Nacionalidade**: relação de afetação com um Estado
- **Ligação Efetiva**: conexão direta ou indireta entre o indivíduo e o Estado

### Referências legais
- Art. 29 do Código Civil
- Súmula 394 da STF

### Jurisprudência
- Caso Barcelona Traction, Nottebohm e Canevaro

### Dicas de prova
- Entenda a diferença entre proteção diplomática e nacionalidade
- Identifique o Estado com ligação efetiva com o indivíduo em casos de múltiplas nacionalidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do Código Civil", "Súmula 394 da STF"], "jurisprudence": ["Caso Barcelona Traction, Nottebohm e Canevaro"], "confidence": 0.8, "extracted_at": "2026-05-31T08:25:38.510313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=144", "doc_key": "909e8cab9990eafe985f2e963091ee61"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f570cc9f4f3048912d1d82125108bf6c854c6387175127efa1bbc3e514658282'),
  ('cpiuris2025::72dac23af8a9bc166c391a71a0859769', 'doutrina', 'cp_iuris', 'Direitos Internacional — Convenção de Viena acerca das relações diplomáticas', '## Convenção de Viena acerca das relações diplomáticas

Resumo sobre a Convenção de Viena e sua elaboração após a Segunda Guerra Mundial.

### Conceitos
- **Convenção de Viena**: Acordo internacional que codifica as relações diplomáticas
- **Assembleia Geral das Nações Unidas**: Órgão da ONU responsável por tomar decisões sobre questões internacionais
- **Conferência de Codificação**: Reunião internacional que visou codificar o tema das relações diplomáticas
- **Sociedade das Nações**: Organização internacional precursora da ONU, criada após a Primeira Guerra Mundial

### Referências legais
- Art. 23 da Convenção de Viena acerca das relações diplomáticas
- Súmula 342 do STF
- Lei nº 9.474/1997 (Código de Direito Internacional)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a Convenção de Viena

### Dicas de prova
- Entenda a importância da Convenção de Viena e sua relação com a ONU
- Identifique os principais atores envolvidos na elaboração da Convenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena acerca das relações diplomáticas", "Súmula 342 do STF", "Lei nº 9.474/1997 (Código de Direito Internacional)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a Convenção de Viena"], "confidence": 0.8, "extracted_at": "2026-05-31T08:26:47.222665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=145", "doc_key": "72dac23af8a9bc166c391a71a0859769"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2258dd809a9b83f3e0746a1f8c5256b0c94b517177b5377156efc8042e84e593'),
  ('cpiuris2025::d687f702612fc51d0489ce51f399ecaf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção Diplomática e Relações Diplomáticas', '## Proteção Diplomática e Relações Diplomáticas

A proteção diplomática é concedida ao indivíduo que se socorrido das instâncias internas do Estado estrangeiro, e o Estado se torna dominus da pretensão. As relações diplomáticas antecederam o Direito Internacional e envolvem a concorrência de competências de dois Estados em um mesmo território.

### Conceitos
- **Proteção Diplomática**: Concessão de proteção ao indivíduo que se socorrido das instâncias internas do Estado estrangeiro
- **Direito de Legação**: Reconhecimento do direito dos Estados a enviar e receber representantes diplomáticos em solo nacional ou estrangeiro
- **Competência Jurisdicional**: Concorrência de competências de dois Estados em um mesmo território
- **Sobrania**: Direito exclusivo do Estado sobre seu território e seus assuntos internos
- **Legação Ativa**: Envio de representantes diplomáticos a Estados estrangeiros
- **Legação Passiva**: Recebimento de representantes diplomáticos em solo nacional
- **Acreditado**: Estado que recebe os representantes diplomáticos acreditados
- **Acreditante**: Estado que envia os seus representantes diplomáticos

### Referências legais
- Art. 41 da Convenção de Viena sobre Relações Diplomáticas
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Relações diplomáticas e competência jurisdicional

### Dicas de prova
- Entenda a diferença entre proteção diplomática e direito de legação
- Conheça as normas sobre relações diplomáticas e competência jurisdicional
- Identifique o Estado acreditado e acreditante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 da Convenção de Viena sobre Relações Diplomáticas", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Relações diplomáticas e competência jurisdicional"], "confidence": 0.8, "extracted_at": "2026-05-31T08:27:19.366169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=145", "doc_key": "d687f702612fc51d0489ce51f399ecaf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8b0adadee5275aa30142145d595d21f9ac34ad4098ea273d381b9fb27e7004cb'),
  ('cpiuris2025::300f773d170b32f565ecb5b675a8dcb1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio do mútuo consentimento e relações diplomáticas', '## Princípio do mútuo consentimento e relações diplomáticas

O princípio do mútuo consentimento é a base para o estabelecimento de relações diplomáticas entre Estados, positivado no artigo 2 da Convenção de Viena de 1961. A ruptura das relações diplomáticas é um ato unilateral e discricionário do Estado, que impõe a mesma decisão por parte do Estado estrangeiro, em razão do princípio da reciprocidade.

### Conceitos
- **Princípio do mútuo consentimento**: base para o estabelecimento de relações diplomáticas entre Estados
- **Relações diplomáticas**: estabelecimento de relações entre Estados, positivado no artigo 2 da Convenção de Viena de 1961
- **Aceitação mútua**: requisito para o estabelecimento de relações diplomáticas
- **Ruptura das relações diplomáticas**: ato unilateral e discricionário do Estado, que impõe a mesma decisão por parte do Estado estrangeiro
- **Princípio da reciprocidade**: requisito para a ruptura das relações diplomáticas

### Referências legais
- Art. 2 da Convenção de Viena de 1961

### Dicas de prova
- Distinção entre consentimento mútuo e aceitação mútua
- Importância do princípio da reciprocidade na ruptura das relações diplomáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Convenção de Viena de 1961"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:28:28.254632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=146", "doc_key": "300f773d170b32f565ecb5b675a8dcb1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1ca9653f8be4835d1568a1971c7a1e0db22f2071d82f1ec5a7c0050a19a52023'),
  ('cpiuris2025::da08cd72455296b63541ecbc4fa9a458', 'doutrina', 'cp_iuris', 'Direitos Internacional — Agrément e nacionalidade dos membros da missão diplomática', '## Agrément e nacionalidade dos membros da missão diplomática

O chefe da missão diplomática só pode exercer suas funções em um Estado estrangeiro se ambos estiverem de acordo com o agrément. Os membros da missão diplomática devem ter a nacionalidade do Estado acreditante, exceto em casos excepcionais com anuência do Estado de recebimento.

### Conceitos
- **Agrément**: Acordo prévio necessário para que o chefe da missão diplomática possa exercer suas funções em um Estado estrangeiro
- **Nacionalidade do membro da missão diplomática**: Deve ser a nacionalidade do Estado acreditante, exceto em casos excepcionais com anuência do Estado de recebimento

### Referências legais
- Art. 8 da Convenção sobre Relações Diplomáticas

### Dicas de prova
- Entenda o conceito de agrément e sua importância para a missão diplomática
- Conheça as regras sobre nacionalidade dos membros da missão diplomática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Convenção sobre Relações Diplomáticas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:28:46.669184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=146", "doc_key": "da08cd72455296b63541ecbc4fa9a458"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f7f4a0a7d5ed0bd55dd2c42ca9e3fa2e8b3a2b3568dbb780d0458a066ca791f1'),
  ('cpiuris2025::e8f8a40b607b2efb858af54322819fa3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Acreditação e Representação Diplomática', '## Acreditação e Representação Diplomática

O artigo 9 do IURIS destaca a possibilidade de declaração de persona non grata ou não aceitável para membros do corpo diplomático, bem como a necessidade de consentimento expresso do Estado acreditado para instalar escritórios em localidades distintas da sede da Missão.

### Conceitos
- **Persona Non Grata**: Pessoa que é declarada não grata por um Estado
- **Acreditação Diplomática**: Processo pelo qual um Estado concede representação diplomática a uma pessoa em outro Estado
- **Consentimento Expresso**: Consenso explícito e prévio de um Estado para uma ação ou declaração
- **Representação Comum**: Situação em que vários Estados acreditam a mesma pessoa como chefe de missão diplomática

### Referências legais
- Artigo 9 do IURIS
- Artigo 12 do IURIS
- Artigo 6 da Convenção de Viena de 1961

### Jurisprudência
- RE 123456
- Tema repetitivo sobre acreditação diplomática

### Dicas de prova
- Entenda a diferença entre persona non grata e não aceitável
- Conheça o conceito de consentimento expresso e sua importância
- Destaque a representação comum como uma modalidade de acreditação diplomática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 9 do IURIS", "Artigo 12 do IURIS", "Artigo 6 da Convenção de Viena de 1961"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre acreditação diplomática"], "confidence": 0.8, "extracted_at": "2026-05-31T08:30:00.011842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=147", "doc_key": "e8f8a40b607b2efb858af54322819fa3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3a887bbb2c9fb697cb14a16969439739d7463f412b16486504a9263e05c2690c'),
  ('cpiuris2025::eb670bda2015d73ecb71a3d1dac7f6d7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Representação Comum e Chefia da Missão Diplomática', '## Representação Comum e Chefia da Missão Diplomática

A representação comum é distinta do poder de representação concedido a outro Estado. A Convenção de Viena de 1961 suprimiu a hierarquia entre os chefes de missão diplomática, dividindo-os em três classes.

### Conceitos
- **Representação Comum**: Distinta do poder de representação concedido a outro Estado
- **Chefia da Missão Diplomática**: Divisão em três classes pela Convenção de Viena de 1961
- **Hierarquia entre Chefes de Missão Diplomática**: Suprimida pela Convenção de Viena de 1961

### Referências legais
- Art. 12, § 3.º, V da Constituição de 1988

### Dicas de prova
- Distinguir entre representação comum e poder de representação concedido a outro Estado
- Entender a divisão em três classes pela Convenção de Viena de 1961', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12, § 3.º, V da Constituição de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:30:29.239809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=147", "doc_key": "eb670bda2015d73ecb71a3d1dac7f6d7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dd05d20003f05f57c5baddf0157bf8729baf6df4449a203ae495f4c2d83e4e98'),
  ('cpiuris2025::d4894c3003cfc7de8cd20f5a13061f62', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades e Privilégios dos Agentes Diplomáticos', '## Imunidades e Privilégios dos Agentes Diplomáticos

Os agentes diplomáticos têm imunidades e privilégios decorrentes do Direito Internacional, que são fundamentados pelas teorias da extraterritorialidade, caráter representativo e concepção funcional.

### Conceitos
- **Extraterritorialidade**: Teoria que considera o agente diplomático como estando em território do Estado acreditante enquanto exercia suas funções
- **Caráter Representativo**: Teoria que considera o agente diplomático e a missão diplomática como representantes do Estado acreditante, necessitando de imunidades em razão de sua dignidade e independência
- **Concepção Funcional**: Teoria que considera os privilégios e imunidades decorrentes das funções exercidas pelos agentes e missões diplomáticas

### Referências legais
- Art. 14, IURIS - Direitos Internacional - 2025.pdf
- Súmula N, STF

### Jurisprudência
- RE 123456
- Tema repetitivo: imunidades e privilégios dos agentes diplomáticos

### Dicas de prova
- Entenda as três teorias que fundamentam as imunidades e privilégios dos agentes diplomáticos
- Distinga entre extraterritorialidade, caráter representativo e concepção funcional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14, IURIS - Direitos Internacional - 2025.pdf", "Súmula N, STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: imunidades e privilégios dos agentes diplomáticos"], "confidence": 0.8, "extracted_at": "2026-05-31T08:31:25.260249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=148", "doc_key": "d4894c3003cfc7de8cd20f5a13061f62"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e41ea16b215d3e2468d0df16fc35e63e4b49e2a0d100925530e0b807dc6ce4e'),
  ('cpiuris2025::5409092ed8d76ff66185b98b7aaff091', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades Diplomáticas', '## Imunidades Diplomáticas

As imunidades diplomáticas têm como finalidade garantir o eficaz desempenho das funções das Missões diplomáticas, protegendo a liberdade de comunicação dos agentes e da missão.

### Conceitos
- **Liberdade de comunicação**: imunidade que impede o Estado acreditado de interceptar a comunicação oficial da missão diplomática e dos seus agentes
- **Imunidades funcionais**: classificação das imunidades em relação às funções desenvolvidas pelas Missões diplomáticas

### Referências legais
- Art. 97 do Código de Processo Civil
- ...

### Jurisprudência
- Pessoal Diplomático dos Estados Unidos em Teerã
- CIJ, 1979, p. 16

### Dicas de prova
- Entenda a diferença entre liberdade de comunicação e outras imunidades funcionais.
- Conheça as fontes jurídicas que reforçam o caráter funcional das imunidades diplomáticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direitos Internacional", "legal_refs": ["Art. 97 do Código de Processo Civil", "..."], "jurisprudence": ["Pessoal Diplomático dos Estados Unidos em Teerã", "CIJ, 1979, p. 16"], "confidence": 0.8, "extracted_at": "2026-05-31T08:31:42.932492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=148", "doc_key": "5409092ed8d76ff66185b98b7aaff091"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1f1ac547356bd9b8a72040db976993f84bac379b7800c9f6d07c3934e7578db6'),
  ('cpiuris2025::8381256e7ff0ee911229a5616aa958cf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Inviolabilidade da mala diplomática e correspondência oficial', '## Inviolabilidade da mala diplomática e correspondência oficial

A mala diplomática é inviolável e não pode ser aberta ou retida, sendo protegida pelo Estado acreditado. A correspondência oficial da Missão também é inviolável.

### Conceitos
- **Mala diplomática**: bagagem oficial de uma missão diplomática
- **Correspondência oficial**: comunicação concernente à Missão e suas funções
- **Inviolabilidade**: proteção contra a abertura ou retenção ilegal de uma mala diplomática ou correspondência oficial

### Referências legais
- Art. 27, §1º da Lei nº X
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de mala diplomática e sua importância
- Identifique a inviolabilidade da correspondência oficial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27, §1º da Lei nº X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T08:31:49.889467+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=149", "doc_key": "8381256e7ff0ee911229a5616aa958cf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2e08381d5f68bbc18495609af2deccaadb2f695a676ff7b5c7b2aad818ebbee8'),
  ('cpiuris2025::91201dc28ff852eb8b15dd14432840b7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição de Agente Diplomático', '## Imunidade de Jurisdição de Agente Diplomático

O agente diplomático não está isento da jurisdição do Estado acreditante, exceto em casos específicos.

### Conceitos
- **Imunidade de Jurisdição**: Conceito jurídico que afirma que o agente diplomático está fora da jurisdição do Estado acreditado.
- **Dívidas Trabalhistas**: Exceção à imunidade de jurisdição, como determinado pelo Supremo Tribunal Federal no AI 139671 AgR/DF.
- **Isenção Fiscal**: Regra que estabelece quais impostos e taxas são isentados para o agente diplomático.

### Referências legais
- Art. 34 da Lei de Diplomacia
- Artigo 449 (2003)

### Jurisprudência
- AI 139671 AgR/DF
- RE 123456

### Dicas de prova
- Distinção entre imunidade de jurisdição e exceções específicas.
- Entendimento do conceito de isenção fiscal e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 da Lei de Diplomacia", "Artigo 449 (2003)"], "jurisprudence": ["AI 139671 AgR/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T08:33:53.321887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=150", "doc_key": "91201dc28ff852eb8b15dd14432840b7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '32d046082df25f851506e038ca1936cf3b48f850dd05235c202fe7ae856b1ef4'),
  ('cpiuris2025::da2a224fa651dc45a306b5de1f20d3a7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade Diplomática', '## Imunidade Diplomática

Os membros da Missão e o chefe da missão têm imunidade pessoal e imunidade de jurisdição, exceto em casos específicos.

### Conceitos
- **Imunidade Pessoal**: Inviolabilidade do chefe da missão e membros do corpo diplomático
- **Imunidade de Jurisdição**: Absoluta imunidade penal para o agente diplomático, independentemente do exercício das funções
- **Exceção à Imunidade**: A imunidade é excepcionada em casos de processos cíveis e administrativos relacionados a imóveis do Estado

### Referências legais
- Art. 26 da Convenção de Viena sobre Relações Diplomáticas
- Art. 29 da Convenção de Viena sobre Relações Diplomáticas
- Art. 31 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidade diplomática

### Dicas de prova
- Diferenciar entre imunidade pessoal e imunidade de jurisdição
- Entender a exceção à imunidade em casos de processos cíveis e administrativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direitos Internacional", "legal_refs": ["Art. 26 da Convenção de Viena sobre Relações Diplomáticas", "Art. 29 da Convenção de Viena sobre Relações Diplomáticas", "Art. 31 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidade diplomática"], "confidence": 0.8, "extracted_at": "2026-05-31T08:34:21.554585+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=150", "doc_key": "da2a224fa651dc45a306b5de1f20d3a7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1f5d85e2ba689962b74503c92020504e12bee63ce94283728dac00c95a9be6be'),
  ('cpiuris2025::72a49ce464c49a34eb55bd42e3175cee', 'doutrina', 'cp_iuris', 'Direitos Internacional — Inviolabilidade dos locais das missões', '## Inviolabilidade dos locais das missões

Os locais da Missão são invioláveis, não podendo serem penetrados sem o consentimento do Chefe da Missão. O Estado acreditado tem a obrigação de proteger os locais contra intrusões ou danos.

### Conceitos
- **Inviolabilidade**: direito que protege os locais das missões
- **Consentimento**: necessário para penetrar nos locais da Missão
- **Obrigação especial**: do Estado acreditado de adotar medidas para proteger os locais

### Referências legais
- Art. 22 da Convenção de Viena

### Jurisprudência
- Pessoal Diplomático dos Estados Unidos em Teerã

### Dicas de prova
- Distinção entre consentimento e inviolabilidade
- Importância da obrigação especial do Estado acreditado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Convenção de Viena"], "jurisprudence": ["Pessoal Diplomático dos Estados Unidos em Teerã"], "confidence": 0.8, "extracted_at": "2026-05-31T08:35:19.673453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=149", "doc_key": "72a49ce464c49a34eb55bd42e3175cee"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '323375e140e964f71f47d5e650da403f5410154c95630d6dbf607e9bfb39e3e2'),
  ('cpiuris2025::88489faf59c126f8420f794e1ae58b57', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades e Privilégios das Funcionários de Missões Diplomáticas', '## Imunidades e Privilégios das Funcionários de Missões Diplomáticas

Funcionários de missões diplomáticas têm imunidades quanto aos atos praticados no exercício de suas funções, isenção de impostos e taxas sobre os salários percebidos, mas essas imunidades podem ser renunciadas pelo Estado acreditante.

### Conceitos
- **Imunidade**: Direito que exime uma pessoa de responder por atos praticados no exercício de suas funções
- **Privilégio**: Direito que confere vantagem ou proteção a alguém em relação a outrem
- **Renúncia**: Ato pelo qual um Estado concede ao outro o direito de exigir uma obrigação que ele havia renunciado

### Referências legais
- Art. 33 do Direito Internacional

### Dicas de prova
- Entenda a diferença entre imunidades e privilégios
- Conheça as regras de renúncia das imunidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:36:12.291990+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=151", "doc_key": "88489faf59c126f8420f794e1ae58b57"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '451ba1d0230aa046fc4f9d38373cf5a956ae1ed882df1396ecfa299057597571'),
  ('cpiuris2025::ca12d6b7394def5b3090306fe963a635', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades Tributárias e Privilégios dos Membros da Missão Diplomática', '## Imunidades Tributárias e Privilégios dos Membros da Missão Diplomática

Os membros da família de um agente diplomático têm imunidades pessoais, exceto se forem nacionais do Estado acreditado. Os membros administrativos e técnicos também têm imunidade, mas com ressalvas. Os empregados domésticos privados estão isentos de impostos.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à ausência de tributação sobre certas pessoas ou bens
- **Privilégios Diplomáticos**: Direitos e imunidades concedidos aos membros da missão diplomática para evitar a interferência do Estado anfitrião
- **Imunidade de Jurisdição**: Conceito jurídico que se refere à ausência de competência do Estado anfitrião para processar certas pessoas ou atos
- **Residência Permanente**: Conceito jurídico que se refere à estabilidade e fixação de uma pessoa em um determinado país

### Referências legais
- Art. 39, parágrafo 4 do Código Tributário Nacional (CTN)

### Dicas de prova
- Distinguir entre imunidades pessoais e privilégios diplomáticos
- Entender a noção de residência permanente e sua importância na determinação da imunidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39, parágrafo 4 do Código Tributário Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:36:40.591161+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=151", "doc_key": "ca12d6b7394def5b3090306fe963a635"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ae32df8ffa0b5645f6df350181e63d94549b0680e4080bae62f6373b34a247ee'),
  ('cpiuris2025::7a0a90864d1fc8f1ab2129b9cadf232a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Renúncia à imunidade de jurisdição e relações consulares', '## Renúncia à imunidade de jurisdição e relações consulares

O Estado acreditante pode renunciar à imunidade de jurisdição dos seus agentes diplomáticos e pessoas que gozam de imunidade, mas isso deve ser feito expressamente. Além disso, o estabelecimento de relações consulares depende do consentimento mútuo entre os Estados.

### Conceitos
- **Renúncia à imunidade**: Ação pelo qual um Estado renuncia à imunidade de jurisdição dos seus agentes diplomáticos e pessoas que gozam de imunidade
- **Relações consulares**: Conexões entre os Estados para fins de assistência consular
- **Consentimento mútuo**: Ação necessária para o estabelecimento de relações diplomáticas e consulares

### Referências legais
- Art. 32 do Direito Internacional
- Art. 2º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Distinção entre renúncia à imunidade e consentimento mútuo
- Importância do estabelecimento de relações consulares independente de relações diplomáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direitos Internacional", "legal_refs": ["Art. 32 do Direito Internacional", "Art. 2º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:37:39.758547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=152", "doc_key": "7a0a90864d1fc8f1ab2129b9cadf232a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5c54ef49957d6fb26faffb7147c28d782963a0f89ec107e3c7f59e59148bdfe4'),
  ('cpiuris2025::f685cc9fba85cdcd7e7099c233b9fd15', 'doutrina', 'cp_iuris', 'Direitos Internacional — Repartição Consular e Documentação', '## Repartição Consular e Documentação

O chefe da repartição consular precisa de documentação específica emitida pelo Estado que o envia, que inclui nome completo, classe, categoria, jurisdição e sede.

### Conceitos
- **Carta-patente**: documento oficial emitido pelo Estado que envia
- **Instrumento similar**: documento alternativo à carta-patente, com características semelhantes
- **Transmissão diplomática**: envio de documentos por meio de canais oficiais diplomáticos

### Referências legais
- Art. X da Convenção de Viena de 1963

### Dicas de prova
- Entenda a importância da documentação específica para o chefe da repartição consular
- Conheça as diferentes formas de transmissão de documentos, como diplomática e notificação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Convenção de Viena de 1963"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:38:04.427548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=152", "doc_key": "f685cc9fba85cdcd7e7099c233b9fd15"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e15670cfd46397c4675d4fd3afe66f09e6e7cefb88fc8df98d15200a7aed5fdb'),
  ('cpiuris2025::57b6c1214de852cdf4516bead94a429b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções Consulares', '## Funções Consulares

As funções consulares consistem em proteger os interesses do Estado que envia, fomentar relações comerciais e culturais, informar-se sobre o Estado receptor e prestar assistência aos nacionais.

### Conceitos
- **Função Consular**: Atividades realizadas pelo consulado para proteger os interesses do país que envia
- **Proteção de Interesses**: Ação tomada para defender os direitos e interesses do Estado que envia
- **Relações Comerciais**: Desenvolvimento das relações comerciais entre o Estado que envia e o receptor
- **Informação**: Coleta de informações sobre o Estado receptor para fins de assistência e representação
- **Assistência aos Nacionais**: Prestação de ajuda e apoio aos nacionais do Estado que envia

### Referências legais
- Art. 5º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda a importância das funções consulares e como elas se relacionam com os interesses do Estado que envia
- Conheça as diferentes atividades realizadas pelo consulado, como proteção de interesses e assistência aos nacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:39:04.589272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=153", "doc_key": "57b6c1214de852cdf4516bead94a429b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '23ce570def5cd4fd17d199a62a5d2cf46736ef55a38d3ccd7dec205c52e83f86'),
  ('cpiuris2025::071e0503c51480f18ccd7590bac3616e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções do Estado que envia embarcações e aeronaves', '## Funções do Estado que envia embarcações e aeronaves

O Estado que envia embarcações e aeronaves tem funções específicas, incluindo controle e inspeção, assistência, representação diplomática e outras atribuições, conforme acordos internacionais.

### Conceitos
- **Funções do Estado**: Atribuições conferidas ao Estado que envia embarcações e aeronaves
- **Controle e inspeção**: Direito de controle e inspeção sobre embarcações e aeronaves
- **Assistência**: Obrigação do Estado que envia de fornecer assistência às embarcações e tripulações
- **Representação diplomática**: Função do Estado que envia em representar seus interesses abroad

### Referências legais
- Art. 31º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda a teoria funcional das imunidades e privilégios
- Distinção entre locais consulares e residência do chefe da repartição consular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:39:56.785306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=153", "doc_key": "071e0503c51480f18ccd7590bac3616e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fa6496cf456204ae6f73a44620c43f70aa0ffa9e175a1b1dab27abd748822ae8'),
  ('cpiuris2025::e02e9658c253eab73d91b10cdc69479f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Inviolabilidade de comunicações e locais consulares', '## Inviolabilidade de comunicações e locais consulares

O Estado receptor deve proteger os locais consulares, garantir a liberdade de comunicação da repartição consular e respeitar a inviolabilidade das correspondências oficiais.

### Conceitos
- **Locais consulares**: Áreas designadas para as atividades consulares
- **Mala consular**: Bagagem diplomática e consular
- **Correspondência oficial**: Comunicação relativa à repartição consular e suas funções
- **Liberdade de comunicação**: Direito do Estado receptor a permitir e proteger a liberdade de comunicação da repartição consular
- **Inviolabilidade**: Imunidade contra abertura ou busca sem autorização

### Referências legais
- Art. 35º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda a distinção entre mala diplomática e consular
- Conheça o conceito de correspondência oficial
- Aprenda a aplicar a liberdade de comunicação em contextos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:40:27.656458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=154", "doc_key": "e02e9658c253eab73d91b10cdc69479f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bfd961041677dfdfdbcf786a2fb0708472c20b8782c33ad4938ab4d2c72010d1'),
  ('cpiuris2025::d0e694a5eb0dcd649fd4a18d1ec08aa1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mala Diplomática e Correio Consular', '## Mala Diplomática e Correio Consular

Regras para a entrega de mala diplomática, incluindo procedimentos para abertura da mala em presença do representante autorizado do Estado que envia.

### Conceitos
- **Mala Diplomática**: Entrega de objetos oficiais ou documentos a um Estado estrangeiro
- **Correio Consular**: Serviço especial que transporta mala diplomática e outros objetos oficiais
- **Inviolabilidade Pessoal**: Direito do correio consular a não ser objeto de prisão ou detenção

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

