  ('cpiuris2025::7f9051647588acc3cab2f237954ac48b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação de comunicação à repartição consular sobre a prisão e a morte de um nacional', '## Obrigação de comunicação à repartição consular sobre a prisão e a morte de um nacional

A Convenção de Viena sobre Relações Consulares estabelece a obrigação da comunicação à repartição consular sobre a prisão e a morte de um nacional, com o objetivo de facilitar o exercício das funções consulares.

### Conceitos
- **Comunicação**: A notificação da repartição consular sobre eventos relevantes relacionados ao nacional do Estado que envia
- **Convenção de Viena sobre Relações Consulares**: Tratado internacional que estabelece regras para as relações entre os países e seus cidadãos

### Referências legais
- Art. 36º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda a importância da comunicação na relação consular
- Conheça a Convenção de Viena sobre Relações Consulares e seu significado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:42:14.187192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=155", "doc_key": "7f9051647588acc3cab2f237954ac48b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f9faf60c6276f72155bd43fd61b29eb5a5cd816d659086cab4f3dd60898312bc'),
  ('cpiuris2025::f963950994288fda61ffc1bb4797019c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade fiscal e imunidades pessoais', '## Imunidade fiscal e imunidades pessoais

A Convenção de Viena sobre Relações Consulares estabelece imunidade fiscal para locais consulares e residência do chefe da repartição consular, bem como imunidades pessoais para funcionários consulares, incluindo imunidade de jurisdição e violabilidade pessoal.

### Conceitos
- **Imunidade fiscal**: Exigência de isenção de impostos e taxas nacionais, regionais e municipais para locais consulares e residência do chefe da repartição consular.
- **Imunidade de jurisdição**: Restrição dos atos praticados por funcionários consulares à jurisdição do Estado receptor.
- **Inviolabilidade pessoal**: Proteção dos funcionários consulares contra detenção preventiva ou limitação de suas liberdades, exceto em casos de crimes graves.

### Referências legais
- Art. 32º da Convenção de Viena sobre Relações Consulares
- Art. 43º da Convenção de Viena sobre Relações Consulares
- Art. 41º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda a distinção entre imunidade fiscal e outras formas de isenção tributária.
- Conheça as limitações da imunidade de jurisdição e violabilidade pessoal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direitos Internacional", "legal_refs": ["Art. 32º da Convenção de Viena sobre Relações Consulares", "Art. 43º da Convenção de Viena sobre Relações Consulares", "Art. 41º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:42:38.764942+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=155", "doc_key": "f963950994288fda61ffc1bb4797019c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9cf27107fee63b2f78d3cee30f12518f83d006dd45f67657f7cbc97a6da3f697'),
  ('cpiuris2025::2009be6fe4b817b12229a70bf265ee38', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prerrogativas dos funcionários consulares', '## Prerrogativas dos funcionários consulares

Os funcionários consulares têm direito de visitar e comunicar-se com os nacionais do Estado que envia, bem como informar suas autoridades competentes sobre a detenção ou prisão do nacional.

### Conceitos
- **Prerrogativas dos funcionários consulares**: Direitos concedidos aos funcionários consulares para visitar e comunicar-se com os nacionais do Estado que envia
- **Visita de funcionário consular**: O direito de um funcionário consular visitar um nacional do Estado que envia em detenção ou prisão preventiva
- **Comunicação com o nacional**: A obrigação de uma autoridade competente informar a repartição consular competente sobre a detenção ou prisão de um nacional do Estado que envia
- **Informações em casos de morte**: O dever das autoridades competentes informar a repartição consular em cuja jurisdição a morte ocorreu
- **Tutela e curatela**: A nomeação de tutor ou curador para um menor ou incapaz nacional do Estado que envia, bem como a notificação à repartição consular competente
- **Naufrágio e acidente aéreo**: O dever das autoridades competentes informar a repartição consular em cuja jurisdição ocorreu o naufrágio ou acidente aéreo

### Referências legais
- Art. 37º da Convenção de Viena sobre Relações Consulares

### Dicas de prova
- Entenda as prerrogativas dos funcionários consulares e suas limitações
- Conheça as regras para a comunicação com os nacionais do Estado que envia em detenção ou prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direitos Internacional", "legal_refs": ["Art. 37º da Convenção de Viena sobre Relações Consulares"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:44:07.701527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=156", "doc_key": "2009be6fe4b817b12229a70bf265ee38"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e935a88819bea7acb143c3de895115cbbad27b3713db4494398ac55ffb541482'),
  ('cpiuris2025::90fc4f7d2e5af64617ae8575ee073bf1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação de notificação consular em casos de prisão preventiva', '## Obrigação de notificação consular em casos de prisão preventiva

A notificação consular é obrigatória em casos de prisão preventiva de cidadãos estrangeiros, mesmo que não haja comprovação de negativa do direito ao acesso aos autos da prisão.

### Conceitos
- **Prisão Preventiva**: Medida cautelar adotada pelo juiz para garantir a liberdade do réu até o final do processo.
- **Notificação Consular**: Obrigação de informar ao consulado do Estado de origem sobre a prisão ou detenção de um cidadão
- **Convenção de Viena sobre Relações Consulares**: Tratado internacional que estabelece diretrizes para as relações consulares entre os Estados

### Referências legais
- Art. 36 da Convenção de Viena sobre Relações Consulares

### Jurisprudência
- RHC 71.835/SP
- Súmula 416 do STF

### Dicas de prova
- Entenda a importância da notificação consular em casos de prisão preventiva.
- Conheça as diretrizes estabelecidas pela Convenção de Viena sobre Relações Consulares.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção de Viena sobre Relações Consulares"], "jurisprudence": ["RHC 71.835/SP", "Súmula 416 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T08:44:18.953525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=156", "doc_key": "90fc4f7d2e5af64617ae8575ee073bf1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd624c3de73f5e9bbcebebf85ac8410802df41b1e4aff0670060e264392ac1bc5'),
  ('cpiuris2025::c2b808f8a853d25c463aa36bffbf47e3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prerrogativas das Relações Consulares', '## Prerrogativas das Relações Consulares

A notificação consular é prerrogativa jurídica fundamental que compõe os direitos básicos da pessoa humana, especialmente para estrangeiros presos no exterior.

### Conceitos
- **Prerrogativas das Relações Consulares**: Direito do agente consular comunicar-se e visitar o nacional preso, bem como o direito do estrangeiro sob custódia do Estado receptor solicitar a cientificação de sua prisão.
- **État d''envoi**: O país que envia um cidadão para outro país
- **État d''accueil**: O país que recebe um cidadão de outro país
- **Notificação Consular**: Prerrogativa jurídica fundamental que informa o Estado receptor sobre a prisão de um estrangeiro em seu território

### Referências legais
- Art. 91 da Convenção de Viena sobre Relações Diplomáticas
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Opinião Consultiva nº 16/1999 da Corte Interamericana de Direitos Humanos

### Dicas de prova
- Entenda a importância da notificação consular para os direitos dos estrangeiros presos no exterior.
