  ('cpiuris2025::ea200b20901e3f15627534a0b2d1853f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição e Contratação de Funcionários em Missões Diplomáticas', '## Imunidade de Jurisdição e Contratação de Funcionários em Missões Diplomáticas

A prática brasileira de admitir reclamações trabalhistas contra funcionários de Missões Diplomáticas estrangeiras é considerada violação do direito internacional, que protege a imunidade de jurisdição desses funcionários.

### Conceitos
- **Imunidade de Jurisdição**: Direito que protege os funcionários diplomáticos de imunidade contra processos judiciais no país hospedeiro
- **Contratação de Funcionários em Missões Diplomáticas**: Ato pelo qual um Estado contrata funcionários para atuar em suas Missões Diplomáticas no exterior
- **Direito Internacional**: Sistema de leis que regula as relações entre Estados e outras entidades internacionais

### Referências legais
- Art. 21 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456 - STJ
- ...

### Dicas de prova
- Entenda a imunidade de jurisdição e sua aplicação prática
