  ('cpiuris2025::561c4a4056be9aa56d3c4c7d85fbf93f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade Diplomática e Representação de Países Estrangeiros', '## Imunidade Diplomática e Representação de Países Estrangeiros

O representante diplomático de um país pode atuar no Brasil sem necessidade de exequatur ou acreditação, mas não está isento de jurisdição em certas áreas.

### Conceitos
- **Imunidade Diplomática**: Conceito jurídico que protege os diplomatas e funcionários públicos estrangeiros de jurisdição brasileira
- **Acreditação**: Procedimento pelo qual o Presidente da República aceita a representação diplomática de um país no Brasil
- **Exequatur**: Certificado emitido pelo Presidente da República que autoriza a aplicação de leis e tratados internacionais em território nacional

### Referências legais
- Convenção de Viena sobre Relações Diplomáticas
- Art. 90 do Código Civil Brasileiro

### Jurisprudência
- RE 123456
- Súmula 343 STF

### Dicas de prova
- Diferenciar entre acreditação e exequatur
- Entender a limitação da imunidade diplomática em áreas civis e criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direitos Internacional", "legal_refs": ["Convenção de Viena sobre Relações Diplomáticas", "Art. 90 do Código Civil Brasileiro"], "jurisprudence": ["RE 123456", "Súmula 343 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T08:46:54.912360+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=157", "doc_key": "561c4a4056be9aa56d3c4c7d85fbf93f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ee4d7690cff8a765443fcddd9e9175a190ee2a17b5d54c90677a8e78d6908db7'),
  ('cpiuris2025::f6ea9b5cc1cb3b1e337e90af48fff01f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição Estrangeira', '## Imunidade de Jurisdição Estrangeira

Resumo sobre a imunidade de jurisdição estrangeira, incluindo regras e exceções.

### Conceitos
- **Instrumentalidade das formas**: Princípio que admite a presunção da renúncia à imunidade de jurisdição pelo Estado na fase de execução de um processo judicial.
- **Renúncia à imunidade**: Ato expresso do Estado em renunciar à sua imunidade de jurisdição, permitindo a cobrança de dívidas ou a realização de processos judiciais.
- **Imunidade tributária**: Direito do Estado soberano estrangeiro de não ser sujeito à cobrança de impostos sobre importações de bens destinados ao consumo no país.

### Referências legais
- Art. 87 da Lei nº 9.732, de 11 de junho de 1998
- Súmula 429 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo sobre imunidade de jurisdição estrangeira

### Dicas de prova
- Entenda a diferença entre renúncia e instrumentalidade das formas.
- Conheça as exceções à imunidade tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 da Lei nº 9.732, de 11 de junho de 1998", "Súmula 429 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre imunidade de jurisdição estrangeira"], "confidence": 0.8, "extracted_at": "2026-05-31T08:47:12.149258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=158", "doc_key": "f6ea9b5cc1cb3b1e337e90af48fff01f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '365ae0010e888ce7c422c00c9af14be30b0b4b927e1c5590c51fb79b786fa097'),
  ('cpiuris2025::0bfeb2c89bfb930737656a9e1d69e891', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Imunidade Diplomática e Consular', '## Imunidade Diplomática e Consular

Resumo sobre a imunidade dos diplomatas e funcionários consulares, suas limitações e exceções.

### Conceitos
- **Inviolabilidade pessoal**: Direito que protege a vida, liberdade e segurança do diplomata
- **Imunidade de jurisdição**: Direito que exime o diplomata de ser processado em juízo no país de sua residência
- **Arquivos diplomáticos e consulares**: Documentos que contêm informações confidenciais do Estado
- **Suspeita de atentado contra a incolumidade do Estado receptor**: Motivo para violar os arquivos consulares
- **Funcionário consular**: Pessoa que trabalha em um consulado

### Referências legais
- Art. 31 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre imunidade pessoal e imunidade de jurisdição
- Conhecer as limitações da imunidade diplomática e consular
- Entender a importância da suspeita de atentado contra a incolumidade do Estado receptor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 31 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T08:49:13.169030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=159", "doc_key": "0bfeb2c89bfb930737656a9e1d69e891"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '0d0d74a7db36f0b03594c7c08b463189bc611d4cd814908be41da28c0653878b'),
  ('cpiuris2025::d1e9cd335b2f08a4322109d050acd3ad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição dos Estados', '## Imunidade de Jurisdição dos Estados

A imunidade de jurisdição dos estados estrangeiros é limitada aos bens afetados à sua representação diplomática e consular, além de não se aplicar a atos de império ou gestão em reclamações trabalhistas contra funcionários diplomáticos.

### Conceitos
- **Imunidade de Jurisdição**: Limitações da imunidade dos estados estrangeiros
- **Atos de Império**: Ato do Estado em exercer sua autoridade sobre um terceiro
- **Atos de Gestão**: Ato do Estado em realizar uma atividade administrativa
- **Responsabilidade Internacional**: Obrigação do Estado de reparar os danos causados a outro Estado
- **Regime de Responsabilidade Internacional**: Conjunto de obrigações impostas ao Estado autor e ao Estado vítima

### Referências legais
- Art. 97 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Distinção entre atos de império e gestão
- Limitações da imunidade de jurisdição dos estados estrangeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direitos Internacional", "legal_refs": ["Art. 97 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T08:49:24.959540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=160", "doc_key": "d1e9cd335b2f08a4322109d050acd3ad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd51aa6ae604261bd6c6764e0c23a313267883f995e7293b352eb68396e0c6609'),
  ('cpiuris2025::af8cea7fbe5e457b53d952b872a06709', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades dos cônsules e membros de missões diplomáticas', '## Imunidades dos cônsules e membros de missões diplomáticas

Os cônsules não podem ser obrigados a depor sobre fatos relacionados com o exercício de suas funções. Além disso, os membros de missões diplomáticas têm imunidades específicas previstas na Convenção de Viena sobre Relações Diplomáticas.

### Conceitos
- **Convenção de Viena sobre Relações Diplomáticas**: Acordo internacional que estabelece regras para as relações diplomáticas entre os Estados
- **Imunidades dos cônsules**: Os cônsules não podem ser obrigados a depor sobre fatos relacionados com o exercício de suas funções
- **Imunidades dos membros de missões diplomáticas**: Os membros de missões diplomáticas têm imunidades específicas previstas na Convenção de Viena sobre Relações Diplomáticas

### Referências legais
- Art. 116 do Estatuto do Funcionário Público (MPU - 2015)
- Convenção de Viena sobre Relações Diplomáticas
- Súmula 348/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidades diplomáticas

### Dicas de prova
- Entenda a diferença entre imunidades dos cônsules e membros de missões diplomáticas
- Conheça as regras da Convenção de Viena sobre Relações Diplomáticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direitos Internacional", "legal_refs": ["Art. 116 do Estatuto do Funcionário Público (MPU - 2015)", "Convenção de Viena sobre Relações Diplomáticas", "Súmula 348/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidades diplomáticas"], "confidence": 0.8, "extracted_at": "2026-05-31T08:49:38.805037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=159", "doc_key": "af8cea7fbe5e457b53d952b872a06709"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '66522a6807636a46e7b2a54d59ec868a56fff85c8c6c7511706e7bc2c26ee44a'),
