Os Estados passam a ser responsabilizados perante organizações internacionais e indivíduos, além de perder a exclusividade da responsabilidade coletiva.

### Conceitos
- **Responsabilidade Coletiva**: aplicação da teoria do órgão
- **Responsabilidade Individual**: possibilidade de responsabilização por atos lícitos
- **Responsabilidade Internacional Objativa**: responsabilização por atos lícitos

### Referências legais
- Art. 196 da Convenção das Nações Unidas sobre o Direito do Mar
- ...

### Jurisprudência
- CASSESE, 2013, p. 344
- RE 123456

### Dicas de prova
- Distinção entre responsabilidade coletiva e individual
