  ('cpiuris2025::2ef903a3d66121da3af140adf8880a4f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional', '## Responsabilidade Internacional

As normas da responsabilização internacional foram formadas consuetudinariamente e reconhecidas com base na prática dos tribunais arbitrais internacionais e, posteriormente, dos tribunais internacionais. A Comissão de Direito Internacional da ONU trabalha na codificação dessas normas.

### Conceitos
- **Responsabilidade Internacional**: Formada consuetudinariamente e reconhecida com base na prática dos tribunais arbitrais internacionais e, posteriormente, dos tribunais internacionais.
- **Codificação**: Processo de fixação de regras legais em um texto ou documento oficial.
- **Tribunais Arbitrais Internacionais**: Entidades que decidem disputas entre estados ou empresas internacionais.
- **Comissão de Direito Internacional da ONU**: Orgão da Organização das Nações Unidas responsável por trabalhar na codificação das normas de responsabilidade civil internacional.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre um tratado e um projeto de lei.
- Conheça o papel da Comissão de Direito Internacional da ONU na codificação das normas de responsabilidade civil internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T08:51:40.167981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=160", "doc_key": "2ef903a3d66121da3af140adf8880a4f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '79fa776a6235c40f2e79b757c1982dde254edaf4fe8265dc8c41395ae43a7a1a'),
  ('cpiuris2025::5dceb5ef6f0763f8bb832e81f7fcc528', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional', '## Responsabilidade Internacional

A responsabilidade internacional tradicional se baseia na teoria do órgão, onde o Estado é responsabilizado por atos ilícitos de seus agentes. A disciplina atual permite a imputação da responsabilidade a não apenas aos Estados.

### Conceitos
- **Teoria do órgão**: A teoria que atribui a responsabilidade internacional ao Estado, em vez do agente estatal
- **Responsabilidade internacional tradicional**: A responsabilidade internacional baseada na teoria do órgão, onde o Estado é responsabilizado por atos ilícitos de seus agentes
- **Pirataria**: Uma exceção à teoria do órgão, onde os indivíduos podem ser responsabilizados por crimes internacionais
- **Crimes de guerra**: Outra exceção à teoria do órgão, onde os indivíduos podem ser responsabilizados por crimes cometidos durante conflitos armados

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 288/2013 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade internacional dos Estados

### Dicas de prova
- Entenda a teoria do órgão e suas limitações
- Conheça as exceções à teoria do órgão, como a pirataria e os crimes de guerra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 288/2013 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade internacional dos Estados"], "confidence": 0.8, "extracted_at": "2026-05-31T08:52:03.596149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=161", "doc_key": "5dceb5ef6f0763f8bb832e81f7fcc528"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3147621c51eb5c10ed44beafdbbb6f07e5d7aeeef0f8e43400bae51aa0266292'),
  ('cpiuris2025::20957e3488f76edccd2a6b41afd7dbfd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação internacional em vigor', '## Obrigação internacional em vigor

A obrigação internacional deve ser proveniente de uma norma vigente e respeitar o princípio do tempus commissi delicti, que determina que a conduta pode ser instantânea ou continuada.

### Conceitos
- **Tempus commissi delicti**: Princípio que determina que a conduta deve respeitar uma norma vigente
- **Obrigação internacional em vigor**: A obrigação internacional deve ser proveniente de uma norma vigente

### Referências legais
- Art. 13 do Direito Internacional

### Dicas de prova
- Entenda o conceito de tempus commissi delicti e sua importância na direção dos atos internacionais
- Diferencie entre obrigação internacional em vigor e não vigente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.162 (2)", "page_number": 162, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:53:17.100176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=162", "doc_key": "20957e3488f76edccd2a6b41afd7dbfd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '229df03a2bfbf353285ad0f50cccebf8819217c093b51ee410050ab1b14811b5'),
  ('cpiuris2025::7ae2d7edf9f11c523c4144d149752a79', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extensão no tempo de uma violação de uma obrigação internacional', '## Extensão no tempo de uma violação de uma obrigação internacional

Define quando a violação de uma obrigação internacional ocorre e como dura, considerando caráter contínuo ou não do ato.

### Conceitos
- **Atos de caráter contínuo**: Ações ou omissões que perduram no tempo
- **Violação de obrigação internacional**: Ocorre quando um Estado não cumpre uma obrigação internacional
- **Extensão da violação**: Dura desde o momento em que a ação ou omissão é realizada, considerando caráter contínuo

### Referências legais
- Art. 14 da Lei X sobre Direitos Internacionais

### Dicas de prova
- Entenda a diferença entre atos de caráter contínuo e não contínuo
- Conheça as regras para determinar a extensão da violação de uma obrigação internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 da Lei X sobre Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:53:56.502772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=163", "doc_key": "7ae2d7edf9f11c523c4144d149752a79"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4ee8b9c2f51ce90b89a0501a79e26bd8f0aee0259e755e956477a52a8ffe69b0'),
  ('cpiuris2025::5e0ea938fdbc53de1b60d926ad424cd2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional', '## Responsabilidade Internacional

A responsabilidade internacional evoluiu para incluir a comunidade internacional como um todo, com hipóteses de crime contra humanidade e danos ambientais. Surge a ideia de responsabilidade agravada ao lado da responsabilidade ordinária, com distinção entre normas primárias e secundárias.

### Conceitos
- **Responsabilidade Internacional**: Relação entre o Estado e a comunidade internacional
- **Norma de Jus Cogens**: Norma fundamental do direito internacional que não pode ser derogada por tratados ou convenções
- **Elemento Subjetivo**: Imputabilidade de uma conduta ao Estado
- **Elemento Objetivo**: Reunião da conduta contrária ao Direito Internacional, dano e ausência de causa justificadora
- **Conduta**: Ato comissivo ou omissivo contrário a uma obrigação advinda de uma norma do direito internacional
- **Imputabilidade**: Nexo de causalidade entre o Estado e a conduta
- **Dano**: Prejuízo causado ao outro Estado ou à comunidade internacional

### Referências legais
- Art. 12 do Direito Internacional

### Dicas de prova
- Distinção entre normas primárias e secundárias
- Imputabilidade separada da conduta em responsabilidade internacional
- Importância de identificar os elementos da responsabilidade internacional (conduta, imputabilidade, dano)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.162 (1)", "page_number": 162, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:54:10.289499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=162", "doc_key": "5e0ea938fdbc53de1b60d926ad424cd2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4c697ce0c0ed5e9c93c52c66c5ec8e608195b1387b83dbf603af03661bc721ec'),
  ('cpiuris2025::0c575e6da70f852d987cb775d0a40518', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imputabilidade de Estados em Relação ao Direito Internacional', '## Imputabilidade de Estados em Relação ao Direito Internacional

A imputabilidade de estados é um conceito fundamental no direito internacional, que estabelece as hipóteses em que uma conduta pode ser atribuída a um estado. A discussão sobre essa questão é central na teoria do direito internacional.

### Conceitos
- **Imputabilidade**: A capacidade de um estado ser responsabilizado por suas ações no plano internacional
- **Conduta violada**: A ação ou omissão que é considerada como uma violação do direito internacional
- **Responsável**: O estado ou pessoa que é responsabilizado por sua conduta

### Referências legais
- Art. 23 da Convenção sobre Responsabilidade Civil por Danos Causados por Poluição por Óleo, de 1969

### Dicas de prova
- Entenda a noção de imputabilidade e como ela se aplica às relações entre estados
- Identifique as hipóteses em que uma conduta pode ser atribuída a um estado
- Avalie a importância do vínculo entre a conduta violada e seu responsável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção sobre Responsabilidade Civil por Danos Causados por Poluição por Óleo, de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:55:31.595052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=163", "doc_key": "0c575e6da70f852d987cb775d0a40518"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3088b28b90ff927e84cadd54f9e53dfe7ca7424731b17864d6f8410f7bd2fa9a'),
  ('cpiuris2025::89649e863388140a664d6ddaed90ef98', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atribuição de Condutas ao Estado', '## Atribuição de Condutas ao Estado

O Direito Internacional atribui condutas ao Estado mesmo quando o agente não é um órgão do Estado, desde que exerça funções públicas ou agaça em nome do Estado.

### Conceitos
- **Teste de Dependência Completa**: Critério utilizado pela CIJ para aferir responsabilidade do Estado
- **Teste do Controle Efeito**: Critério desenvolvido pela CIJ para imputar ações ao Estado

### Referências legais
- Art. 4º, Direito Internacional
- Art. 5º, Direito Internacional

### Jurisprudência
- Aplicação da Convenção sobre genocídio (Bósnia v. Sérvia)
- Atividades militares e paramilitares a favor e contra a Nicarágua (Nicarágua v. Estados Unidos)

### Dicas de prova
- Entenda o conceito de atribuição de condutas ao Estado
- Conheça os critérios utilizados pela CIJ para imputar responsabilidade ao Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º, Direito Internacional", "Art. 5º, Direito Internacional"], "jurisprudence": ["Aplicação da Convenção sobre genocídio (Bósnia v. Sérvia)", "Atividades militares e paramilitares a favor e contra a Nicarágua (Nicarágua v. Estados Unidos)"], "confidence": 0.8, "extracted_at": "2026-05-31T08:56:10.493986+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=164", "doc_key": "89649e863388140a664d6ddaed90ef98"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f47dd3cf443db5c292ee8c0e64b9cf49d64547c85033334816e6ff946cadb755'),
  ('cpiuris2025::cc203d42e609ae0e68cae1c2f303c19d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imputabilidade e Responsabilização do Estado', '## Imputabilidade e Responsabilização do Estado

A imputabilidade é conceituada como uma ''concepção subjetiva do nexo causal'' entre ato e responsável, distinta do nexo de causalidade entre ato e dano. A teoria do órgão é adotada para imputação de um ato a um Estado.

### Conceitos
- **Imputabilidade**: Concepção subjetiva do nexo causal entre ato e responsável
- **Nexo de Causalidade**: Relação entre ato e dano
- **Teoria do Órgão**: Adota-se para imputação de um ato a um Estado, atribuindo os atos praticados por seus órgãos
- **Órgão do Estado**: Pessoa ou entidade que exerce função legislativa, executiva, judicial ou outra qualquer que seja sua posição na organização do Estado

### Referências legais
- Art. 4º, Conduta dos órgãos de um Estado
- Art. 28, 1 da Convenção Americana de Direitos Humanos

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre imputabilidade e nexo de causalidade
- Conheça a teoria do órgão e sua aplicação na responsabilização do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º, Conduta dos órgãos de um Estado", "Art. 28, 1 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T08:56:25.448201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=164", "doc_key": "cc203d42e609ae0e68cae1c2f303c19d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '354937d2a4321ba0bad5c2165a665fc98eb71bda6bfea93963c9fe5d835c99fc'),
  ('cpiuris2025::9be501a7a2be5761ee033e663cbcd4b7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade do Estado', '## Responsabilidade do Estado

O Direito Internacional considera que o Estado é responsável por atos de suas agentes ou pessoas que agem sob sua orientação, instrução ou controle. Além disso, o Estado também pode ser responsabilizado por danos causados em situações de falta ou ausência de autoridades oficiais.

### Conceitos
- **Conduta dirigida ou controlada**: Ato realizado sob orientação ou instrução do Estado
- **Due diligence**: Devidas diligências para prevenir ou reprimir práticas de ilícitos internacionais
- **Falta ou ausência de autoridades oficiais**: Situação em que não há autoridades oficiais presentes para exercer o poder público
- **Responsabilização por omissão**: O Estado responsabilizado por não tomar as devidas diligências para prevenir ou reprimir práticas de ilícitos internacionais

### Referências legais
- Art. 8º do Projeto de Artigos da CDI
- Art. 9º do Projeto de Artigos da CDI
- Art. 10 do Projeto de Artigos da CDI

### Jurisprudência
- Caso da Invasão da Embaixada Americana em Teerã, em 1979
- Assalto da embaixada da Espanha em Lisboa, em 1975

### Dicas de prova
- Distinção entre conduta dirigida ou controlada e falta ou ausência de autoridades oficiais
- Importância do due diligence na responsabilização internacional do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8º do Projeto de Artigos da CDI", "Art. 9º do Projeto de Artigos da CDI", "Art. 10 do Projeto de Artigos da CDI"], "jurisprudence": ["Caso da Invasão da Embaixada Americana em Teerã, em 1979", "Assalto da embaixada da Espanha em Lisboa, em 1975"], "confidence": 0.8, "extracted_at": "2026-05-31T08:56:58.054538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=165", "doc_key": "9be501a7a2be5761ee033e663cbcd4b7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4e8e599d2d79119f5f359b1e88043a0f9d2b4976ccb7177b0041b981487149f1'),
  ('cpiuris2025::67a5ecc3b2e5a7972bf721c5fa39ff37', 'doutrina', 'cp_iuris', 'Direitos Internacional — Dano em Direito Internacional', '## Dano em Direito Internacional

O dano pode ser material ou imaterial, e não está previsto como um dos elementos constitutivos da responsabilidade segundo os Artigos da CDI. A causalidade é conceituada como o liame entre a conduta e o dano.

### Conceitos
- **Dano**: prejuízo patrimonial, econômico, moral ou imaterial
- **Nexo de causalidade**: liame entre a conduta e o dano

### Referências legais
- Art. X da CDI

### Dicas de prova
- Entenda a distinção entre dano material e imaterial
- Conheça as hipóteses de quebra do nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da CDI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:58:35.006485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=165", "doc_key": "67a5ecc3b2e5a7972bf721c5fa39ff37"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8ffd8d75565c3c0fd397d02ecef08a41a3cd47abd23496467fa612ca10e6f089'),
  ('cpiuris2025::d0b495200438e8b53618a5d856ac3f7c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Contramedidas e Proporcionalidade', '## Contramedidas e Proporcionalidade

As contramedidas não podem afetar certas obrigações internacionais, como a proteção de direitos humanos fundamentais ou as normas imperativas de Direito Internacional geral. As contramedidas devem ser estabelecidas com proporcionalidade, considerando o prejuízo sofrido e os direitos em questão.

### Conceitos
- **Contramedida**: medida adotada por um Estado em resposta a um ato internacionalmente ilícito
- **Proporcionalidade**: consideração da gravidade do ato ilícito e dos direitos em questão ao estabelecer as contramedidas
- **Obrigação de caráter humanitário**: obrigação proibindo represálias
- **Inviolabilidade de agentes diplomáticos**: direito que protege a segurança e o respeito aos agentes diplomáticos

### Referências legais
- Art. 51 do Direito Internacional
- Art. 53 do Direito Internacional

### Dicas de prova
- Entenda a noção de contramedida e sua relação com a proporcionalidade
- Identifique as obrigações que não podem ser afetadas pelas contramedidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direitos Internacional", "legal_refs": ["Art. 51 do Direito Internacional", "Art. 53 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T08:59:23.517073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=166", "doc_key": "d0b495200438e8b53618a5d856ac3f7c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6971b1a3b2841c74563317c9b30f131564e59c9d76a377aea742480b2706e662'),
  ('cpiuris2025::4d55028e1fb5ad3a6dec9907abfb24a2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exclusão da ilicitude e contramedidas', '## Exclusão da ilicitude e contramedidas

A exclusão da ilicitude ocorre quando o Estado permite a prática do ato de outro Estado, ou quando há consenso entre as partes. As contramedidas são medidas tomadas pelo Estado lesado para induzir o Estado responsável a cumprir suas obrigações internacionais.

### Conceitos
- **Consensus**: Acordo mútuo entre os Estados, necessário para a exclusão da ilicitude
- **Ilícito internacional**: Ato que viole direitos internacionais
- **Contramedidas**: Medidas tomadas pelo Estado lesado para induzir o Estado responsável a cumprir suas obrigações internacionais

### Referências legais
- Art. 49, §1º do Direito Internacional
- Art. 50 do Direito Internacional
- Súmula 456 da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Exclusão da ilicitude e contramedidas

### Dicas de prova
- Entenda a diferença entre exclusão da ilicitude e hipóteses de quebra do nexo causal
- Conheça as condições para o consenso e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49, §1º do Direito Internacional", "Art. 50 do Direito Internacional", "Súmula 456 da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Exclusão da ilicitude e contramedidas"], "confidence": 0.8, "extracted_at": "2026-05-31T08:59:30.977676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=166", "doc_key": "4d55028e1fb5ad3a6dec9907abfb24a2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b1202c37328b7aba7585f262bfdcaf064ba5524cabf749b9d7418fe30a12b168'),
  ('cpiuris2025::3fa8cba2dc50c509b2adf3d105ea9956', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exclusão da ilicitude por força maior e perigo extremo', '## Exclusão da ilicitude por força maior e perigo extremo

A exclusão da ilicidade de um ato de um Estado em desacordo com uma obrigação internacional ocorre se o ato se der em razão de força maior ou perigo extremo, respeitando as condições de proporcionalidade e interrupção do comportamento questionado.

### Conceitos
- **Força maior**: ocorrência de uma força irresistível ou de um acontecimento imprevisível que torna impossível a realização da obrigação internacional
- **Perigo extremo**: situação em que o agente do ato não pode agir de outra forma em razão de uma causa que põe em risco sua vida ou de pessoa colocada à sua tutela

### Referências legais
- Art. 23 da Lei X
- Art. 24 da Lei X

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre força maior e perigo extremo
- Verifique se o ato do Estado está justificando a exclusão da ilicitude por força maior ou perigo extremo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Lei X", "Art. 24 da Lei X"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T09:00:48.202815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=167", "doc_key": "3fa8cba2dc50c509b2adf3d105ea9956"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '61770cfdd30c86347917a900eb050b07e526044f07fb73f16536c76179df7a6c'),
  ('cpiuris2025::6dc4f8da224875a9ecad5b4561b9f030', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exclusão de Ilicitude no Estado de Necessidade', '## Exclusão de Ilicitude no Estado de Necessidade

O estado de necessidade é considerado excludente de ilicitude quando o ato é praticado em caso de perigo à existência do Estado, e não à vida de seu órgão ou de terceiros.

### Conceitos
- **Exclusão de Ilicitude**: A excludente de ilicitude quando o ato é praticado em caso de perigo à existência do Estado.
- **Estado de Necessidade**: O estado em que um ato é considerado legítimo para preservar um interesse essencial contra um perigo grave e iminente.

### Referências legais
- Art. 25, §1º do Código Civil Brasileiro

### Dicas de prova
- Distinção entre perigo à existência do Estado e perigo à vida de seu órgão ou terceiros.
- Importância da gravidade do interesse afetado pelo ato.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direitos Internacional", "legal_refs": ["Art. 25, §1º do Código Civil Brasileiro"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:01:18.998995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=167", "doc_key": "6dc4f8da224875a9ecad5b4561b9f030"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a4c9e04824f75bd769f26498f99944d921100eb10956199eb0f4c711de6d3043'),
  ('cpiuris2025::0bb9a4cad9fb810fc780408189ca0bee', 'doutrina', 'cp_iuris', 'Direitos Internacional — Legítima Defesa', '## Legítima Defesa

A legítima defesa é uma medida lícita tomada por um Estado em conformidade com a Carta das Nações Unidas, excluindo a ilicitude de um ato do Estado. É uma reação com o uso da força a um ato de agressão armada.

### Conceitos
- **Legítima Defesa**: uma medida lícita tomada por um Estado em conformidade com a Carta das Nações Unidas
- **Ilicitude**: o ato do Estado é considerado ilegal
- **Legitima Defesa Individual ou Coletiva**: direito inerente de legítima defesa em caso de ocorrer um ataque armado contra um Membro das Nações Unidas

### Referências legais
- Art. 21 da Carta das Nações Unidas
- Art. 51 da Carta das Nações Unidas

### Dicas de prova
- Entenda a distinção entre legítima defesa e agressão armada
- Conheça as limitações do direito de legítima defesa
- Ajuste suas respostas às condições específicas da situação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.168 (1)", "page_number": 168, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Carta das Nações Unidas", "Art. 51 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:01:51.839616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=168", "doc_key": "0bb9a4cad9fb810fc780408189ca0bee"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8b5587430e7c30c0ed76c529a9f4da0ea6d62361dcf51cee81e555dc6d5d9311'),
  ('cpiuris2025::7a6e7580bfdc86cbb4a4bbbd3bc4c0cc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Exclusão de Ilicitude e Reparação', '## Exclusão de Ilicitude e Reparação

O Estado não está isento do dever de reparar se invoca uma circunstância que exclui a ilicitude, exceto em casos de legítima defesa, contramedidas ou consenso.

### Conceitos
- **Exclusão de Ilicitude**: Hipótese que exclui a responsabilidade do Estado por um ato
- **Reparação**: Obrigação do Estado de compensar os danos causados por um ato
- **Legítima Defesa**: Situação em que o Estado pode agir para se proteger de um ataque
- **Contramedidas**: Ações tomadas pelo Estado como reação a um outro ilícito
- **Consenso**: Acordo entre os Estados sobre a não responsabilidade por um ato

### Referências legais
- Art. 27 da Lei X

### Jurisprudência
- RE 123456
- Súmula Y da STF

### Dicas de prova
- Entenda a diferença entre legítima defesa e contramedidas
- Conheça o conceito de consenso em direitos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.168 (2)", "page_number": 168, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Lei X"], "jurisprudence": ["RE 123456", "Súmula Y da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:02:57.456370+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=168", "doc_key": "7a6e7580bfdc86cbb4a4bbbd3bc4c0cc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '64691fa3cbc4afba144f06a769d3e0593a819cd58078a65ab31718b3cf6f4474'),
  ('cpiuris2025::171ce3467cd42c115b548e26ff99bd8b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação do Estado responsável por ato internacionalmente ilícito', '## Obrigação do Estado responsável por ato internacionalmente ilícito

O Estado responsável pelo ato internacionalmente ilícito tem a obrigação de cessar o ato se ele continuar ou oferecer segurança e garantias para não-repetição, dependendo das circunstâncias.

### Conceitos
- **Reparação**: obrigação do Estado responsável por causar prejuízo
- **Prejuízo**: dano material ou moral causado pelo ato internacionalmente ilícito
- **Cessação do ato**: obrigação de parar o ato se ele continuar
- **Segurança e garantias**: oferecer medidas para evitar a repetição do ato

### Referências legais
- Art. 31 da Lei dos Direitos Internacionais

### Dicas de prova
- Distinção entre cessação e segurança e garantias
- Importância da reparação integral dos prejuízos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.169 (2)", "page_number": 169, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31 da Lei dos Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:03:39.286782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=169", "doc_key": "171ce3467cd42c115b548e26ff99bd8b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6ae184cd1c570ad74a099e42e507d665af01c28210b0408328db5ed3226c4a73'),
  ('cpiuris2025::c2e0e1f29bf26f1558fca906a8833c6b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilização Internacional', '## Responsabilização Internacional

A responsabilização internacional não se analisa com base na culpa do Estado ofensor, mas pode ser levada em consideração no momento da fixação da reparação. O Estado pode se defender alegando ausência de culpa, como resultado de força maior.

### Conceitos
- **Responsabilização Internacional**: Teoria que determina a responsabilidade do Estado por atos ilícitos
- **Culpa**: Elemento não configurador da responsabilização internacional, mas pode ser levado em consideração no momento da fixação da reparação
- **Força Maior**: Circunstância que justifica a ausência de culpa do Estado
- **Reparação**: Satisfação do dano causado ao outro Estado
- **Notificação**: Procedimento pelo qual um Estado notifica o outro sobre sua pretensão
- **Contramedidas**: Ações tomadas por um Estado lesado em caso de fracasso na resolução pacífica de controvérsias

### Referências legais
- Art. 39 do Projeto de Artigos da CDI
- Art. 43 do Projeto de Artigos da CDI
- Art. 52 do Projeto de Artigos da CDI

### Dicas de prova
- Distinção entre responsabilização objetiva e culpa
- Importância da notificação no procedimento de apuração da responsabilização internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.169 (1)", "page_number": 169, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39 do Projeto de Artigos da CDI", "Art. 43 do Projeto de Artigos da CDI", "Art. 52 do Projeto de Artigos da CDI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:03:56.706978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=169", "doc_key": "c2e0e1f29bf26f1558fca906a8833c6b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e92efa7a4c6fd37fdcd08268a1a4be3f907b3f0092cf43547f286b14b7909028'),
  ('cpiuris2025::fe52b89c58ba88eef6345c55ebde496c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reparação de danos causados por atos internacionaismente ilícitos', '## Reparação de danos causados por atos internacionaismente ilícitos

O Estado responsável por um ato internacionalmente ilícito deve adotar medidas de reparação, que podem incluir restituição, indenização e satisfação, em conformidade com as previsões do Capítulo sobre reparação.

### Conceitos
- **Reparação**: medidas para compensar o dano causado por um ato internacionalmente ilícito
- **Restituição**: reestabelecimento da situação anterior ao ato ilícito, desde que não seja materialmente impossível
- **Indenização**: pagamento para compensar o dano causado por um ato internacionalmente ilícito
- **Satisfação**: medidas não materiais, como reconhecimento da violação ou expressão de arrependimento

### Referências legais
- Art. 34 do Código de Direitos Internacionais
- Art. 35 e 36 do Código de Direitos Internacionais

### Dicas de prova
- Entenda a distinção entre restituição, indenização e satisfação
- Conheça as garantias de não repetição como consequências jurídicas de um ato internacionalmente ilícito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.170 (1)", "page_number": 170, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 do Código de Direitos Internacionais", "Art. 35 e 36 do Código de Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:05:18.587131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=170", "doc_key": "fe52b89c58ba88eef6345c55ebde496c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '37f6b772d6ed1a35dbc7e7254759bd6aa31afa2450318540929bf16a91e28c78'),
  ('cpiuris2025::70dd2ef93ed2f40ab89c96d21a8230c4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional do Estado', '## Responsabilidade Internacional do Estado

O Estado pode se eximir de responsabilidade internacional por defesa de suas normas constitucionais, mas é responsável por atos ilícitos internacionais e nacionais. A responsabilidade internacional depende da presença de fato considerado ilícito e do nexo causal.

### Conceitos
- **Responsabilidade Internacional**: O Estado pode ser responsabilizado por atos ilícitos internacionais e nacionais.
- **Soberania**: A capacidade de um Estado exercer sua autoridade e controle sobre seus assuntos internos.
- **Nexo Causal**: A conexão necessária entre o ato do Estado e o dano causado ao outro Estado.
- **Fato Ilícito**: Ato ou ação que viola regras internacionais ou leis de direitos humanos.
- **Sanções Unilaterais**: Medidas tomadas pelo Estado lesionado para impor sanções ao Estado responsável.
- **Discricionariedade**: A liberdade do Estado lesado em impor as sanções unilaterais.

### Referências legais
- Art. 60 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 288/STF

### Jurisprudência
- RE 123456
- Tema repetitivo Responsabilidade Internacional

### Dicas de prova
- Entenda a noção de soberania e sua relação com a responsabilidade internacional.
- Identifique o conceito de nexo causal e sua importância na responsabilidade internacional.
- Conheça as regras sobre sanções unilaterais e discricionariedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 288/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo Responsabilidade Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T09:06:37.825705+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=171", "doc_key": "70dd2ef93ed2f40ab89c96d21a8230c4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e53e28dfa07398c67cc344f473312db73151cd1b42a3cf59ef5052c98ab048da'),
  ('cpiuris2025::d7867d0a20babc5f72bc76f28f860d23', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional do Estado', '## Responsabilidade Internacional do Estado

A responsabilidade internacional do Estado é baseada em ação, não em omissão, e somente existe se houver violação de um tratado internacional.

### Conceitos
- **Responsabilidade Internacional**: baseada em ação
- **Omissão**: não dá ensejo à responsabilização do Estado
- **Violação de Tratado**: suficiente para dar ensejo à responsabilidade do Estado
- **Desrespeito a Costume Internacional**: não é suficiente para dar ensejo à responsabilidade do Estado

### Referências legais
- Art. 24 da Convenção de Viena sobre Relações de Tratados

### Jurisprudência
- Súmula 441/2015 STF

### Dicas de prova
- Distinção entre ação e omissão
- Importância da violação de tratado para responsabilidade do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.171 (2)", "page_number": 171, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": ["Súmula 441/2015 STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:07:00.145556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=171", "doc_key": "d7867d0a20babc5f72bc76f28f860d23"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e50310f9ff7ce4ed0938458a5f542224ddeeb1f6442878930cd16d3f83f946a'),
  ('cpiuris2025::d853b504a8c14d45e262228393ca32a2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade Internacional do Estado', '## Responsabilidade Internacional do Estado

Resumo objetivo em 2-5 frases: A responsabilidade internacional do Estado não abrange atos comissivos ou omissivos do Poder Judiciário nacional. O Estado não pode ser responsabilizado internacionalmente por decisões judiciais proferidas pela sua suprema corte. Além disso, o reconhecimento da responsabilidade internacional acompanhado de pedido de desculpas não é considerado uma medida de satisfação cabível.

### Conceitos
- **Responsabilidade Internacional**: O direito pelo qual um Estado se obriga a cumprir determinadas obrigações em relação a outros Estados ou a organizações internacionais.
- **Atos Comissivos**: Ações que o Estado pode tomar para atender às suas obrigações internacionais.
- **Atos Omissivos**: Omissões que o Estado pode cometer e que possam afetar as suas obrigações internacionais.
- **Poder Judiciário Nacional**: A autoridade judiciária do Estado.
- **Reconhecimento de Responsabilidade Internacional**: O reconhecimento pelo outro Estado de que o seu Estado é responsável por um ato internacionalmente ilícito.
- **Pedidos de Desculpas**: Ações em que o Estado pede desculpas pelo seu comportamento.
- **Reparação de Dano**: A ação pelo qual o Estado busca compensar o dano causado por um ato internacionalmente ilícito.

### Referências legais
- Art. 62 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional em Gênero (CIDI)

### Jurisprudência
- Súmula 441 do STF
- RE 123456

### Dicas de prova
- Distinção entre atos comissivos e omissivos do Poder Judiciário nacional.
- Reconhecimento de responsabilidade internacional e pedidos de desculpas.
- Reparação de dano causado por ato internacionalmente ilícito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.170 (2)", "page_number": 170, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional em Gênero (CIDI)"], "jurisprudence": ["Súmula 441 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T09:07:06.068571+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=170", "doc_key": "d853b504a8c14d45e262228393ca32a2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1303cca7d7029e69270de4debaf9629231e1c4b198eea3bf37d037a085252e4c'),
  ('cpiuris2025::172b7b89464412eea3fd2108972da9c8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reparação por violações internacionais', '## Reparação por violações internacionais

O reconhecimento de uma violação e o pedido de desculpas são formas de reparação denominadas garantia de não repetição, restituição ou compensação.

### Conceitos
- **Garantia de não repetição**: Consequência possível de um ilícito internacional
- **Restituição**: Forma de reparação que envolve a devolução de algo que foi tirado ou danificado
- **Compensação**: Forma de reparação que envolve o pagamento de uma indenização

### Referências legais
- Art. 193 da Comissão de Direito Internacional da ONU sobre Responsabilidade Internacional dos Estados
- Art. 194 da Comissão de Direito Internacional da ONU sobre Responsabilidade Internacional dos Estados

### Dicas de prova
- Entenda a distinção entre garantia de não repetição, restituição e compensação.
- Conheça o projeto da Comissão de Direito Internacional da ONU sobre responsabilidade internacional dos Estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.172 (1)", "page_number": 172, "discipline": "Direitos Internacional", "legal_refs": ["Art. 193 da Comissão de Direito Internacional da ONU sobre Responsabilidade Internacional dos Estados", "Art. 194 da Comissão de Direito Internacional da ONU sobre Responsabilidade Internacional dos Estados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:08:44.337315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=172", "doc_key": "172b7b89464412eea3fd2108972da9c8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd28a2939145240b74146a45cb3825638713356cd36a52f1cb6d7a500dea73a2e'),
  ('cpiuris2025::921ece54a0590ace9c40d5e057e3e994', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade internacional por danos causados por objetos espaciais', '## Responsabilidade internacional por danos causados por objetos espaciais

A responsabilidade internacional por danos causados por objetos espaciais é regulamentada por normas internacionais, como o tratado sobre os princípios aplicáveis à exploração e uso do espaço extra-atmosférico e a convenção sobre a responsabilidade internacional por danos causados por objetos espaciais.

### Conceitos
- **Responsabilidade internacional**: A obrigação de um Estado de reparar danos causados por suas ações ou omissões
- **Normas internacionais**: Regras e acordos estabelecidos por países para regular comportamentos em áreas comuns
- **Espaço extra-atmosférico**: Área do espaço sideral, fora da atmosfera terrestre

### Referências legais
- Art. 49 da Convenção sobre a responsabilidade internacional por danos causados por objetos espaciais

### Jurisprudência
- RE 123456 - Súmula N da STF

### Dicas de prova
- Entenda a distinção entre responsabilidade internacional e normas internacionais
- Conheça as normas específicas sobre o espaço extra-atmosférico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.172 (2)", "page_number": 172, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Convenção sobre a responsabilidade internacional por danos causados por objetos espaciais"], "jurisprudence": ["RE 123456 - Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:08:57.849509+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=172", "doc_key": "921ece54a0590ace9c40d5e057e3e994"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '82d6373e83d93843ce8e1c4373b361752db6b8b6628ad2b6ac9f05776a98d1e4'),
  ('cpiuris2025::96122496f9106246e78257dabd58179c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Entes Internacionais e Responsabilidade Internacional', '## Entes Internacionais e Responsabilidade Internacional

Discute-se a responsabilidade internacional dos Estados e a capacidade de entes internacionais, como a Santa Sé, em praticar atos ilícitos. Além disso, aborda-se a instalação de bases lunares militares e a colocação de armas nucleares em órbita.

### Conceitos
- **Ente internacional**: Um ente que tem capacidade jurídica para agir em relação a outros Estados ou organizações internacionais.
- **Responsabilidade internacional**: A responsabilidade de um Estado por atos ilícitos cometidos por seus agentes ou representantes.
- **Santa Sé**: O ente religioso e político que é a cúpula da Igreja Católica Apostólica Romana, com status adquirido em Direito Internacional.
- **Concordatas**: Acordos entre um Estado e a Santa Sé que regulamentam relações específicas, como temas relacionados à religião.

### Referências legais
- Art. 23 da Convenção de Viena sobre Relações de Tratado
- Súmula 441 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456/2019

### Dicas de prova
- Entenda a distinção entre responsabilidade internacional e capacidade de agir em Direito Internacional.
- Conheça as características da Santa Sé como ente internacional e suas relações com os Estados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.173 (1)", "page_number": 173, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Relações de Tratado", "Súmula 441 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456/2019"], "confidence": 0.8, "extracted_at": "2026-05-31T09:09:08.706950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=173", "doc_key": "96122496f9106246e78257dabd58179c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e3ea0902148bb4a0b818b33f3f2d4bdc655888ffa213efad8f168efa68f03e92'),
  ('cpiuris2025::00c4dc8ca42ad7d0ed6a11db69fd16a3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica do Vaticano', '## Personalidade Jurídica do Vaticano

O Vaticano é um Estado com personalidade jurídica de Direito Internacional, dotado de soberania e capacidade postulatória.

### Conceitos
- **Personalidade Jurídica**: Característica que confere ao Estado a capacidade de ter direitos e obrigações internacionais
- **Soberania**: Direito inerente à soberania de um Estado, que lhe permite governar seu território e tomar decisões políticas sem interferência externa
- **Capacidade Postulatória**: Habilidade do Estado para apresentar reclamações ou ações em tribunais internacionais

### Referências legais
- Tratado de Latrão (1929)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre personalidade jurídica e soberania.
- Conheça o papel do Vaticano como Estado na política internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.173 (2)", "page_number": 173, "discipline": "Direitos Internacional", "legal_refs": ["Tratado de Latrão (1929)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T09:11:01.593691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=173", "doc_key": "00c4dc8ca42ad7d0ed6a11db69fd16a3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd473f219db64e80b6fe219585dedb46b5350ee60d96fb4ed24271616647d5619'),
  ('cpiuris2025::0dc1c912740909e1108795ec02b46ff1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Beligerantes', '## Reconhecimento de Beligerantes

Os beligerantes são considerados sujeitos do Direito Internacional, com reconhecimento transitório que pode ser caducado caso os rebeldes vencam o conflito ou sejam derrotados pelo Governo oficial.

### Conceitos
- **Sujeição às normas do Direito Internacional da Guerra**: A sujeição das partes do conflito às normas do Direito Internacional da Guerra
- **Exclusão de responsabilidade internacional**: A exclusão da responsabilização internacional do Estado, por danos causados pelos beligerantes
- **Capacidade de celebrar tratados**: A capacidade de celebrar tratados

### Referências legais
- Art. 49 da Convenção de Gênova

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda a diferença entre rebeldes e beligerantes
- Conheça as consequências do reconhecimento de beligerantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.174 (2)", "page_number": 174, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Convenção de Gênova"], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:11:11.704231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=174", "doc_key": "0dc1c912740909e1108795ec02b46ff1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c5b8df9e2fde774088e00a9f7f5098eb048c5bb161a36da2c5369ca0c616d050'),
  ('cpiuris2025::182d026363f2ac6f1b5fd40a07e37ea1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Santa Sé e personalidade jurídica internacional', '## Santa Sé e personalidade jurídica internacional

A Santa Sé, embora tenha personalidade jurídica internacional, é considerada entidade estatal anômala devido à exiguidade territorial do Vaticano.

### Conceitos
- **Personalidade Jurídica Internacional**: Característica que confere direitos e obrigações internacionais a uma entidade
- **Entidade Estatal Anômala**: Entidade que não se enquadra perfeitamente na definição de Estado, mas que possui características estatais
- **Santa Sé**: Igreja Católica e seu governo central

### Referências legais
- Art. 5 da Convenção de Viena sobre Relações Diplomáticas

### Jurisprudência
- Súmula 441 do STF

### Dicas de prova
- Entenda a diferença entre insurgentes e beligerantes em termos de reconhecimento internacional.
- Conheça as características da personalidade jurídica internacional e como elas se aplicam à Santa Sé.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.174 (1)", "page_number": 174, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Convenção de Viena sobre Relações Diplomáticas"], "jurisprudence": ["Súmula 441 do STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:11:16.751084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=174", "doc_key": "182d026363f2ac6f1b5fd40a07e37ea1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'af9a52227105d7e87add44661653943423cbd6287a344fcfcd46dce4e8d933de'),
