  ('cpiuris2025::1ccdea36241b3dd8801c3c258c89aefd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Movimentos de Libertação Nacional vs Beligerantes', '## Movimentos de Libertação Nacional vs Beligerantes

Resumo sobre a diferença entre movimentos de libertação nacional e beligerantes em termos de legitimidade e requisitos para reconhecimento.

### Conceitos
- **Autodeterminação dos povos**: Princípio que permite a liberdade dos povos, considerando sua vontade soberana.
- **Representatividade de seus membros como agentes do povo**: Requisito para reconhecimento dos movimentos de libertação nacional
- **Exercício do controle político**: Outo requisito para reconhecimento dos movimentos de libertação nacional

### Referências legais
- Art. 62 da Convenção das Nações Unidas sobre Direitos Humanos
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de movimentos de libertação nacional

### Dicas de prova
- Diferenciar entre movimentos de libertação nacional e beligerantes
