  ('cpiuris2025::25304e90c90aedeaca08f5fa0f921ce3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Organizações Internacionais', '## Organizações Internacionais

As organizações internacionais têm sede própria em um ou mais Estados-membros e regulam suas atividades por meio de acordos de instalação. A caracterização de uma organização internacional depende de critérios como ter pelo menos três Estados com direito a voto, estrutura formal e objetivos internacionais.

### Conceitos
- **Organização Internacional**: Entidade criada por instrumentos do Direito Internacional
- **Critérios de Caracterização**: Ter pelo menos três Estados com direito a voto, estrutura formal e objetivos internacionais
- **Sede Pública**: Local onde a organização internacional tem sede própria em um ou mais Estados-membros
- **Acordos de Instalação**: Instrumentos que regulam as atividades da organização internacional em seu território interno
- **Vocação Universalista**: Objetivo de criar organizações com competência mais ampla para resolver conflitos entre os Estados-membros
- **Evolução Histórica**: Três fases: desenvolvimento da diplomacia multilateral, criação da Liga das Nações e pretensões regionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a caracterização de uma organização internacional e seus critérios
- Conheça os diferentes tipos de organizações internacionais e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.176", "page_number": 176, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:14:06.506450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=176", "doc_key": "25304e90c90aedeaca08f5fa0f921ce3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cee4b0d3c35a3dafea85f5d10e3a103c398d9a38bc6286ca174ea0f2a4a7e89b'),
  ('cpiuris2025::4ea57d90937f4c3cba17e8810ec7d339', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação das organizações internacionais', '## Classificação das organizações internacionais

As organizações internacionais podem ser classificadas em políticas e técnicas, com exemplos como a ONU e a OEA para políticas, e a OIT para técnica.

### Conceitos
- **Organização Internacional**: Entidade criada por países para alcançar objetivos comuns
- **Classificação das Organizações Internacionais**: Divisão em políticas e técnicas
- **Política**: Objetivo de gerir conflitos e agir preventivamente para a manutenção da paz e segurança internacionais
- **Técnica**: Objetivo de cooperação técnica em uma área específica

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre políticas e técnicas das organizações internacionais
- Conheça os exemplos de organizações internacionais mencionadas no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.177 (2)", "page_number": 177, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:15:11.190031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=177", "doc_key": "4ea57d90937f4c3cba17e8810ec7d339"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b379f6d20bdb4ecbab4f17d6cada22b3a5540b874be07e69b550e274f1c8cc95'),
  ('cpiuris2025::93b9172a5a2a6e31398096022d80ad85', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

A personalidade jurídica internacional é um conceito que se desenvolveu após a Segunda Guerra Mundial, com a proliferação de organizações internacionais. A autonomia das organizações internacionais em relação aos seus Estados membros e sua atuação no plano internacional são fundamentais para sua personalidade jurídica.

### Conceitos
- **Personalidade Jurídica Internacional**: Conceito que se desenvolveu após a Segunda Guerra Mundial, com a proliferação de organizações internacionais.
- **Autonomia das Organizações Internacionais**: A autonomia das organizações internacionais em relação aos seus Estados membros é fundamental para sua personalidade jurídica.
- **Atuação no Plano Internacional**: A atuação das organizações internacionais no plano internacional é um aspecto importante de sua personalidade jurídica.
- **Distinção entre Organização e Estados-Membros**: A distinção entre a organização e os seus Estados-membros é fundamental para a aferição da personalidade jurídica internacional.
- **Poderes Jurídicos**: Os poderes jurídicos das organizações internacionais são fundamentais para sua personalidade jurídica.
- **Fins Lícitos**: Os fins lícitos das organizações internacionais são um aspecto importante de sua personalidade jurídica.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Reparação de danos sofridos à serviço das Nações Unidas

### Dicas de prova
- Entenda a autonomia das organizações internacionais e sua atuação no plano internacional.
- Distinça entre a organização e os seus Estados-membros é fundamental.
- Poderes jurídicos são fundamentais para a personalidade jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.177 (1)", "page_number": 177, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Reparação de danos sofridos à serviço das Nações Unidas"], "confidence": 0.8, "extracted_at": "2026-05-31T09:16:04.829604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=177", "doc_key": "93b9172a5a2a6e31398096022d80ad85"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9a7064cec15eefac5f0beffd3b1b09386e5448b163352c69bd44173d7fe25dfb'),
  ('cpiuris2025::5b949745fa19bd3f19edd656f304427b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Organizações Internacionais', '## Organizações Internacionais

Descreve as diferentes categorias de organizações internacionais, suas finalidades e âmbito de atuação.

### Conceitos
- **Organização com finalidade geral**: Detém uma multiplicidade de fins
- **Organização com finalidade especial**: Subdividida em categorias específicas (cooperação política, econômica, militar, social e humanitária, culturais, científicas e técnicas)
- **Universal ou global**: Busca abranger o maior número de Estados-membros possíveis
- **Regional**: Constituída em razão de um critério de identificação geográfica de seus membros
- **Abertas ilimitadamente**: Permite qualquer Estado ingressar sem restrição
- **Abertas limitadamente**: Permite o ingresso de novos membros, mas faz uma restrição geográfica que limita o número de possíveis candidatos
- **Fechadas**: Não permite a entrada de novos membros

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda as categorias de organizações internacionais e suas características
- Conheça o conceito de abertas ilimitadas, limitadas e fechadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.178 (1)", "page_number": 178, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:16:47.394606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=178", "doc_key": "5b949745fa19bd3f19edd656f304427b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '43cf392afd6120d4a82d8b6a86b5f5a3055881cdc90645d7d1510d4621e78f58'),
  ('cpiuris2025::c3a843de88a238b31f6a1e726d7c2314', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação de organizações internacionais', '## Classificação de organizações internacionais

As organizações internacionais são classificadas em cooperação e integração, com a cooperação buscando aproximação de políticas dos Estados sem perder o poder de conduzi-las, enquanto as organizações de integração desenvolvem políticas e objetivos comuns geridas por seus próprios membros.

### Conceitos
- **Cooperação**: Aproximação de políticas dos Estados sem perder o poder de conduzi-las
- **Integração**: Desenvolvimento de políticas e objetivos comuns geridos por seus próprios membros

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre cooperação e integração é fundamental
- Entenda a diferença entre os dois tipos de organizações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.178 (2)", "page_number": 178, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:16:56.575332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=178", "doc_key": "c3a843de88a238b31f6a1e726d7c2314"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2081736a51338984b17772d57dfabd4cd18e80e9ddaf6e74f32c5be93685df1e'),
  ('cpiuris2025::174d1661e85a86e3fc2a50ab3868260f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade da Organização das Nações Unidas', '## Imunidade da Organização das Nações Unidas

A Organização das Nações Unidas e seus bens gozam de imunidade de jurisdição, salvo em casos específicos em que a Organização renunciou a essa imunidade.

### Conceitos
- **Imunidade da Organização das Nações Unidas**: Direito que exime a Organização e seus bens de qualquer tipo de jurisdição
- **Renúncia à imunidade**: Ação pela qual a Organização renuncia a sua imunidade de jurisdição em determinados casos

### Referências legais
- Art. 27 da Convenção sobre Privilégios e Imunidades das Nações Unidas

### Jurisprudência
- RE 597368
- Súmula 456/STF

### Dicas de prova
- Entenda a diferença entre imunidade e renúncia à imunidade.
- Conheça o artigo 27 da Convenção sobre Privilégios e Imunidades das Nações Unidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.179 (2)", "page_number": 179, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Convenção sobre Privilégios e Imunidades das Nações Unidas"], "jurisprudence": ["RE 597368", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T09:18:43.371604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=179", "doc_key": "174d1661e85a86e3fc2a50ab3868260f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7c0d7b6ab85a821b2eecc1c11b6769361a2d9fa14b65a0412ff8a91bc6d56949'),
  ('cpiuris2025::6d6391435997723bdd52e3bd3f8976ea', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estatuto Jurídico das Organizações Internacionais', '## Estatuto Jurídico das Organizações Internacionais

As organizações internacionais têm direitos e deveres provenientes das normas do Direito Internacional, incluindo a capacidade de concluir tratados limitada ao objeto da organização.

### Conceitos
- **Organização internacional**: Entidade jurídica internacional com personalidade própria
- **Capacidade de concluir tratados**: Direito das organizações internacionais para assinar acordos e convênios com outros Estados e organizações
- **Estatuto jurídico internacional**: Regras que regem a existência e o funcionamento das organizações internacionais
- **Imunidade de jurisdição estatal**: Direito das organizações internacionais para não serem sujeitas à jurisdição dos Estados-membros

### Referências legais
- Art. 6º da Convenção de Viena sobre o Direito dos Tratados entre Estados e Organizações Internacionais
- Súmula 456 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Estatuto Jurídico das Organizações Internacionais

### Dicas de prova
- Entenda a capacidade de concluir tratados e o estatuto jurídico internacional
- Identifique a imunidade de jurisdição estatal como direito das organizações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.179 (1)", "page_number": 179, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6º da Convenção de Viena sobre o Direito dos Tratados entre Estados e Organizações Internacionais", "Súmula 456 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Estatuto Jurídico das Organizações Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T09:18:54.419724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=179", "doc_key": "6d6391435997723bdd52e3bd3f8976ea"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7b64f2735d7b812b150ab15d659377e387a8b75432016873e5b363a2ac882d89'),
  ('cpiuris2025::7bcc33f7aafd84c0ff9eeaae27aa0770', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidades e Direitos Correlatos das Organizações Internacionais', '## Imunidades e Direitos Correlatos das Organizações Internacionais

Resumo do acórdão Teori Zavascki sobre imunidades e direitos correlatos das organizações internacionais, incluindo isenção fiscal, inviolabilidade de comunicações e locais afetos, legação, proteção dos funcionários e direito de reparação.

### Conceitos
- **Imunidade**: Conceito jurídico que protege as organizações internacionais de jurisdição estrangeira
- **Direitos Correlatos**: Direitos que se relacionam com as imunidades das organizações internacionais, como isenção fiscal e inviolabilidade de comunicações
- **Legação**: Direito que permite às organizações internacionais enviar representantes aos Estados para o desempenho de suas atividades
- **Proteção dos Funcionários**: Dever dos Estados de proteger os funcionários das organizações internacionais no exercício de suas funções
- **Direito de Reparação**: Direito que permite aos estados reparar danos sofridos pela organização internacional em caso de descumprimento do dever de proteção

### Referências legais
- Art. 21 da Lei nº 9.307/1996
- Súmula 397 do STF

### Jurisprudência
- RE 1034840 RG
- REPERCUSSÃO GERAL - MÉRITO DJe-143 DIVULG 29-06-2017

### Dicas de prova
- Entenda a noção de imunidade e seus direitos correlatos
- Conheça os direitos específicos das organizações internacionais, como legação e proteção dos funcionários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.180 (1)", "page_number": 180, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Lei nº 9.307/1996", "Súmula 397 do STF"], "jurisprudence": ["RE 1034840 RG", "REPERCUSSÃO GERAL - MÉRITO DJe-143 DIVULG 29-06-2017"], "confidence": 0.8, "extracted_at": "2026-05-31T09:19:58.271459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=180", "doc_key": "7bcc33f7aafd84c0ff9eeaae27aa0770"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2e23ab466728d7d26dc7af8a979b1ab9c3d348dfc12c52600ed41a8fd7083dd5'),
  ('cpiuris2025::886cffa66fbac8743e2e827d4ad091c0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Responsabilidade internacional de organizações internacionais', '## Responsabilidade internacional de organizações internacionais

As organizações internacionais podem ser responsabilizadas internacionalmente por suas ações, incluindo indenizações pagas aos estrangeiros.

### Conceitos
- **Sucessão das organizações internacionais**: Problema a ser enfrentado
- **Responsabilidade internacional**: Atuação de órgãos ou agentes de organizações internacionais
- **Indenizações**: Pagamento de compensação por danos causados

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre atuação interna e internacional
- Importância das indenizações em casos de responsabilidade internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.180 (2)", "page_number": 180, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T09:20:21.969993+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=180", "doc_key": "886cffa66fbac8743e2e827d4ad091c0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a3808fd8cac9c0f5b45c9dbc3eaf3ea628a4678f61e3d001f17aa60396c07f93'),
  ('cpiuris2025::f2c836b1e0f5d5b15b6843339220fc8a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Imunidade de Jurisdição de Organismos Internacionais', '## Imunidade de Jurisdição de Organismos Internacionais

A questão discute a competência da Justiça Federal ou do Trabalho para processar e julgar demandas contra organismos internacionais, como a Unesco. A resposta correta está relacionada à imunidade de jurisdição desses organismos.

### Conceitos
- **Imunidade de Jurisdição**: Conceito jurídico que afirma que os organismos internacionais não estão sujeitos às leis do Estado em que atuam.
- **Competência da Justiça Federal**: A competência da Justiça Federal é determinada pela Constituição e pelos códigos de procedimento criminal e civil.
- **Imunidade Relativa de Jurisdição do Estado Estrangeiro**: Teoria jurídica que afirma que os Estados estrangeiros não estão sujeitos às leis do Brasil, exceto em casos específicos.

### Referências legais
- Art. 109 da Constituição Federal de 1988

### Dicas de prova
- Distinção entre imunidade absoluta e relativa de jurisdição
- Reconhecimento da competência da Justiça Federal em relação a organismos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.181 (1)", "page_number": 181, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:20:55.600390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=181", "doc_key": "f2c836b1e0f5d5b15b6843339220fc8a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '879eca8e6a72641f302484f73176864d11ee5a8c29867b3f818c0dab44f3a183'),
  ('cpiuris2025::f42090f05eebb4a3dd2c39ca67c13642', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito internacional e substituição de Estados em organizações internacionais', '## Direito internacional e substituição de Estados em organizações internacionais

A República Federativa Lilliputiana foi criada após a invasão armada da Lilliput, mas o direito internacional não consagra o princípio de que um novo Estado tenha direito a substituir outro Estado nas organizações internacionais.

### Conceitos
- **Substituição de Estados**: O processo pelo qual um novo Estado assume a representação de um Estado anterior em organizações internacionais.
- **Direito internacional**: A disciplina jurídica que regula as relações entre Estados e outras entidades internacionais.
- **Organização internacional**: Uma entidade internacional que reúne Estados ou outras entidades para fins específicos.

### Referências legais
- Art. 59 do Estatuto do Vencedor da Guerra

### Dicas de prova
- Entenda a noção de substituição de Estados e como ela se relaciona com o direito internacional.
- Análise cuidadosamente as alternativas para identificar a resposta correta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.181 (2)", "page_number": 181, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 do Estatuto do Vencedor da Guerra"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:21:09.638844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=181", "doc_key": "f42090f05eebb4a3dd2c39ca67c13642"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '36ebfd73bed91d89503e9befd535fa71efc141c2b259241d4a93edbee66fa0b2'),
  ('cpiuris2025::3878f907a1db742da5583f04ae294e2a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Organização das Nações Unidas', '## Organização das Nações Unidas

Resumo sobre a Organização das Nações Unidas, suas finalidades e propósitos.

### Conceitos
- **Assembleia Geral**: órgão máximo da ONU
- **Voto absoluto**: necessário para tomar decisões no Conselho de Administração da OIT
- **Convenção Americana sobre Direitos Humanos**: Pacto de São José da Costa Rica
- **Expulsão coletiva**: excepcionalmente permitida pela Convenção Americana sobre Direitos Humanos
- **Vocação universal**: organizações internacionais com finalidade de atuação em todo o mundo

### Referências legais
- Art. 1 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância da Assembleia Geral e do Conselho de Administração na OIT.
- Conheça as diferenças entre organizações internacionais e não governamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.182 (1)", "page_number": 182, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:23:13.358313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=182", "doc_key": "3878f907a1db742da5583f04ae294e2a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5c8d025632a981d3a853b8b2bf804eca16880460d9dae73966ad5a5e420ca6fd'),
  ('cpiuris2025::772de80f5833964fc56faf0a5005523c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Objetivos e Princípios da ONU', '## Objetivos e Princípios da ONU

A Organização das Nações Unidas (ONU) tem como objetivo promover a paz mundial, proteger os direitos humanos e garantir liberdades fundamentais para todos. Isso é alcançado através de objetivos comuns que devem ser harmonizados pelas nações.

### Conceitos
- **Direitos Humanos**: Benedictiones inalienáveis de todos os seres humanos
- **Liberdades Fundamentais**: Direitos essenciais que garantem a dignidade humana
- **Objetivos Comuns**: Metas globais que devem ser alcançadas pelas nações
- **Paz Mundial**: Estabilidade e segurança em todo o mundo

### Referências legais
- Art. 13 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância dos direitos humanos e liberdades fundamentais na ONU
- Conheça os objetivos comuns e como eles devem ser alcançados pelas nações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.182 (2)", "page_number": 182, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:23:18.386208+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=182", "doc_key": "772de80f5833964fc56faf0a5005523c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd20bda9c052dea030db9ce07a6d69da3ea77ddbf00828523c760e73b89ce0efc'),
  ('cpiuris2025::e01556bc01be766cbc67767461b5e7e1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Origem e membros da ONU', '## Origem e membros da ONU

A Organização das Nações Unidas (ONU) foi formada após a Segunda Guerra Mundial, com a assinatura de 24 países na Declaração das Nações Unidas em 1942. Os membros originários são os que participaram da Conferência de São Francisco e assinaram a Carta da ONU, enquanto os admitidos ou eleitos são os Estados que ingressaram após a apresentação de sua candidatura.

### Conceitos
- **Conferência de São Francisco**: Reunião em que os representantes de 50 países se reuniram para elaborar a Carta das Nações Unidas e as normas atinentes à Corte Internacional de Justiça
- **Membros originários**: Estados que participaram da Conferência de São Francisco e assinaram a Declaração das Nações Unidas
- **Membros admitidos ou eleitos**: Estados que ingressaram na ONU após a apresentação de sua candidatura, com recomendação favorável do Conselho de Segurança e decisão da Assembleia Geral

### Referências legais
- Artigo 3 da Carta da ONU
- Artigo 110 da Carta da ONU

### Dicas de prova
- Entenda a importância da Conferência de São Francisco na formação da ONU
- Conheça as diferenças entre Membros originários e admitidos ou eleitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.183 (1)", "page_number": 183, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 3 da Carta da ONU", "Artigo 110 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:24:01.392275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=183", "doc_key": "e01556bc01be766cbc67767461b5e7e1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '04796c7211c2ccaa9fe08bcc6daff89bbbd660ca191b456ac4e549217e6e8103'),
  ('cpiuris2025::2c7cb6f61e250bf44849cd28414ff554', 'doutrina', 'cp_iuris', 'Direitos Internacional — Admissão de Estados Membros nas Nações Unidas', '## Admissão de Estados Membros nas Nações Unidas

As condições para a admissão de novos membros na ONU são estabelecidas no Artigo 4 da Carta das Nações Unidas, exigindo que os Estados aceitem as obrigações contidas na Carta e estejam aptos a cumprir essas obrigações.

### Conceitos
- **Admissão de Estado Membro**: Processo pelo qual um novo Estado é admitido como membro das Nações Unidas
- **Carta das Nações Unidas**: Instrumento internacional que estabelece os princípios e objetivos da ONU
- **Obrigações contidas na Carta**: Requisitos e responsabilidades impostos aos Estados membros da ONU

### Referências legais
- Art. 4 da Carta das Nações Unidas

### Dicas de prova
- Entenda a diferença entre admissão e aceitação
- Conheça os requisitos para a admissão de um novo membro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.183 (2)", "page_number": 183, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:25:25.492035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=183", "doc_key": "2c7cb6f61e250bf44849cd28414ff554"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f340b3c9aa4250d53c3d8cd6c45f485223c23066159d6ee4d00092cb0fc2e7ad'),
  ('cpiuris2025::294f1013fd905434ba6468bcab8b4ca0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão e Expulsão de Estados-membros da ONU', '## Suspensão e Expulsão de Estados-membros da ONU

A Carta da ONU estabelece regras para a suspensão e expulsão de Estados-membros, que requerem recomendação do Conselho de Segurança e decisão da Assembleia Geral.

### Conceitos
- **Carta da ONU**: O documento fundamental da Organização das Nações Unidas
- **Conselho de Segurança**: Órgão principal da ONU responsável pela manutenção da paz e segurança internacionais
- **Assembleia Geral**: Órgão legislativo da ONU responsável por tomar decisões importantes
- **Suspensão de privilégios**: Medida tomada pela Assembleia Geral contra um Estado-membro que violou os princípios da Carta
- **Expulsão**: Medida tomada pela Assembleia Geral contra um Estado-membro que violou persistentemente os princípios da Carta

### Referências legais
- Art. 5 da Carta da ONU
- Art. 6 da Carta da ONU

### Dicas de prova
- Entenda a distinção entre suspensão e expulsão de Estados-membros
- Conheça os procedimentos legais estabelecidos pela Carta da ONU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.184", "page_number": 184, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Carta da ONU", "Art. 6 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:25:54.423956+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=184", "doc_key": "294f1013fd905434ba6468bcab8b4ca0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd6403f39a05cff86110b3b4463880bc9a77daee653ef23a325e2cd7499d8e6d7'),
  ('cpiuris2025::f1fb876e7bcc4821c021915131b83a4a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conselho de Segurança da ONU', '## Conselho de Segurança da ONU

O Conselho de Segurança é composto por 15 membros, com 5 permanentes e 10 rotativos. Os membros permanentes são China, Estados Unidos, França, Reino Unido e Rússia, enquanto os membros rotativos são eleitos por um período de dois anos e representam diferentes regiões do mundo.

### Conceitos
- **Conselho de Segurança**: órgão da ONU responsável pela manutenção da paz e segurança internacionais
- **Membros permanentes**: China, Estados Unidos, França, Reino Unido e Rússia
- **Membros não permanentes**: eleitos por um período de dois anos para representar diferentes regiões do mundo
- **Composição do Conselho**: 15 membros, com 5 permanentes e 10 rotativos
- **Eleição dos Membros não Permanentes**: realizada pela Assembleia Geral da ONU
- **Presidência do Conselho**: rotativa, por ordem alfabética, por um período de um mês

### Referências legais
- Art. 23 da Carta das Nações Unidas

### Dicas de prova
- Entenda a composição do Conselho de Segurança e os critérios para a eleição dos Membros não permanentes
- Conheça as regiões representadas pelos Membros não permanentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.185", "page_number": 185, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:26:41.040606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=185", "doc_key": "f1fb876e7bcc4821c021915131b83a4a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c8a4bec8aa5e5702c8daac9f1fbae43582de7894afc9fd128eb426b001065537'),
  ('cpiuris2025::0238235ebe9c6cdd4557ed9754b9bec9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Votação no Conselho de Segurança', '## Votação no Conselho de Segurança

O Conselho de Segurança tem um sistema de votação distinto, com questões processuais necessitando de 9 votos afirmativos e outras questões necessitando de 9 votos afirmativos sem nenhum voto negativo.

### Conceitos
- **Votação**: O processo pelo qual o Conselho de Segurança toma decisões
- **Questão processual**: Uma questão que envolve procedimentos ou formalidades
- **Questão substantiva**: Uma questão que envolve substância ou conteúdo
- **Voto afirmativo**: Um voto que apoia uma decisão
- **Veto**: O direito de um membro permanente do Conselho de Segurança de impedir uma decisão
- **Abstenção**: A ação de não votar em uma questão

### Referências legais
- Art. 27 da Carta da ONU

### Dicas de prova
- Entenda a distinção entre questões processuais e substantivas
- Conheça o conceito de veto e como ele funciona no Conselho de Segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.186 (1)", "page_number": 186, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:27:42.251368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=186", "doc_key": "0238235ebe9c6cdd4557ed9754b9bec9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd73b2a37d0e95cb1e131f1dd998715fc54fba7de6c2d479576454e2531cb7b2'),
  ('cpiuris2025::81f90f404d27f724f75d61673ac7d898', 'doutrina', 'cp_iuris', 'Direitos Internacional — Designações de comitês de sanções e publicação de resoluções da ONU', '## Designações de comitês de sanções e publicação de resoluções da ONU

As designações de comitês de sanções da ONU têm executoriedade imediata no Brasil, sendo suas resoluções publicadas no Diário Oficial da União pelo Ministério das Relações Exteriores.

### Conceitos
- **executoriedade imediata**: direito que permite a execução imediata de uma decisão ou medida
- **publicação no Diário Oficial da União**: procedimento pelo qual um documento oficial é divulgado para informar o público

### Referências legais
- Art. 7º da Lei X
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de executoriedade imediata e sua aplicação no contexto das designações de comitês de sanções.
- Conheça o procedimento de publicação de resoluções da ONU no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.186 (2)", "page_number": 186, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º da Lei X", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T09:27:42.456484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=186", "doc_key": "81f90f404d27f724f75d61673ac7d898"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '62dcc7813bd97d24acb609dd1c9079d67c9ac263cb45ecdef5bb344264f027c7'),
  ('cpiuris2025::56684128e30fceaefcd612ebcb17676a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência e Atribuições da Assembleia Geral', '## Competência e Atribuições da Assembleia Geral

A Assembleia Geral tem competência ampla para discutir assuntos correlatos às finalidades da Carta da ONU ou que se relacionem com as atribuições e funções de seus órgãos, podendo fazer recomendações aos Membros das Nações Unidas ou ao Conselho de Segurança.

### Conceitos
- **Competência**: habilitação para agir em um determinado assunto
- **Atribuições**: funções e responsabilidades de um órgão
- **Assembleia Geral**: órgão máximo da ONU
- **Maioria de dois terços**: quantidade de votos necessária para tomar decisões importantes
- **Questões importantes**: assuntos que requerem uma decisão especial

### Referências legais
- Artigo 10 da Carta da ONU
- Artigo 17 da Carta da ONU

### Dicas de prova
- Entenda a competência e as atribuições da Assembleia Geral para evitar erros em provas.
- Lembre-se de que a maioria de dois terços é necessária para tomar decisões importantes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.187 (1)", "page_number": 187, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 10 da Carta da ONU", "Artigo 17 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:28:59.997795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=187", "doc_key": "56684128e30fceaefcd612ebcb17676a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0f4f81719e28593dc53b78c3996ed5be41a49348bd1a2b73a7852c8508660599'),
  ('cpiuris2025::7679585d7fb6f439b3c8b08a20ed6a13', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atribuições facultativas das Nações Unidas', '## Atribuições facultativas das Nações Unidas

As atribuições facultativas permitem a concorrência com a competência de outros órgãos, como recomendações ao Conselho de Segurança.

### Conceitos
- **Atribuição facultativa**: permite a concorrência com a competência de outros órgãos
- **Competência exclusiva**: é a competência de um órgão específico
- **Carta das Nações Unidas**: instrumento fundador das Nações Unidas

### Referências legais
- Artigo 13.1 da Carta das Nações Unidas

### Dicas de prova
- Entenda a distinção entre competência exclusiva e facultativa
- Conheça as atribuições do Conselho de Segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.187 (2)", "page_number": 187, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 13.1 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:29:25.826617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=187", "doc_key": "7679585d7fb6f439b3c8b08a20ed6a13"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '41fc27e37c8f626d84e0bf9854d3f26452571415b5a7719d05b60bbcf898b30a'),
  ('cpiuris2025::150d037257a653abc1d3c0ca13ad4ca7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atribuições e funções das Nações Unidas', '## Atribuições e funções das Nações Unidas

As Nações Unidas têm atribuições e funções definidas, incluindo a manutenção da paz e segurança internacionais, e são auxiliadas por comissões e órgãos subsidiários.

### Conceitos
- **Atribuições das Nações Unidas**: As Nações Unidas têm atribuições definidas para manter a paz e segurança internacionais.
- **Comissões das Nações Unidas**: As Nações Unidas contam com o auxílio de seis comissões para exercer suas atribuições.
- **Órgãos subsidiários**: Os órgãos subsidiários, como painéis e grupos de trabalho, são criados para harmonizar as abordagens das Nações Unidas.

### Referências legais
- Artigo 10 da Carta das Nações Unidas
- Artigo 11.1 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância das atribuições e funções das Nações Unidas.
- Conheça as comissões e órgãos subsidiários que auxiliam as Nações Unidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.188", "page_number": 188, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 10 da Carta das Nações Unidas", "Artigo 11.1 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:30:11.354516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=188", "doc_key": "150d037257a653abc1d3c0ca13ad4ca7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e57f4b84808d280e4d0fb0eb5cc0ce1a44f0eff5e556518066e6d0bc41115b42'),
  ('cpiuris2025::a645db1f3586994cc7204a13ecea519c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conselho Econômico e Social da ONU', '## Conselho Econômico e Social da ONU

O Conselho Econômico e Social da ONU tem atribuições previstas no artigo 62 da Carta da ONU, incluindo estudos e relatórios sobre assuntos internacionais de caráter econômico, social, cultural, educacional, sanitário e conexos, além de fazer recomendações à Assembleia Geral e aos Membros das Nações Unidas.

### Conceitos
- **Atribuições do Conselho Econômico e Social**: previstas no artigo 62 da Carta da ONU
- **Votação no Conselho Econômico e Social**: tomadas por maioria dos membros presentes e votantes
- **Princípio da autodeterminação dos povos**: considerado pelo Conselho de Tutela das Nações Unidas

### Referências legais
- Artigo 62 da Carta da ONU
- Artigo 67 da Carta da ONU
- Artigos 86 a 91 da Carta da ONU

### Dicas de prova
- Entenda o papel do Conselho Econômico e Social na ONU e suas atribuições.
- Conheça o princípio da autodeterminação dos povos e sua importância no contexto das Nações Unidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.189", "page_number": 189, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 62 da Carta da ONU", "Artigo 67 da Carta da ONU", "Artigos 86 a 91 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:31:28.158573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=189", "doc_key": "a645db1f3586994cc7204a13ecea519c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2d48245265a3c72a4b3c1624ad43ed483e3ca21a51a3ccf60c47dee7abaf8470'),
  ('cpiuris2025::d8c00cab5551518d3819502b75048717', 'doutrina', 'cp_iuris', 'Direitos Internacional — Secretário-Geral da ONU', '## Secretário-Geral da ONU

O Secretário-Geral é indicado pela Assembleia Geral após recomendação do Conselho de Segurança, para um mandato de cinco anos, permitida uma recondução. É o principal funcionário administrativo da Organização.

### Conceitos
- **mandato**: período de tempo durante o qual alguém é indicado ou eleito para exercer uma função
- **recomendação**: sugestão feita por alguém em favor de outra pessoa
- **pessoal**: empregados ou funcionários de uma organização
- **Administração**: área da gestão e controle de uma organização
- **Assembleia Geral**: órgão máximo da ONU que eleita o Secretário-Geral
- **Conselho de Segurança**: órgão da ONU responsável por garantir a segurança internacional

### Referências legais
- Art. 97 da Carta da ONU
- Art. 98 da Carta da ONU
- Art. 99 da Carta da ONU

### Dicas de prova
- Entenda a importância do Secretário-Geral na Administração da ONU
- Conheça as funções e responsabilidades do Secretário-Geral
- Aprenda com o Art. 97 da Carta da ONU para identificar o mandato do Secretário-Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direitos Internacional", "legal_refs": ["Art. 97 da Carta da ONU", "Art. 98 da Carta da ONU", "Art. 99 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:32:01.413984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=190", "doc_key": "d8c00cab5551518d3819502b75048717"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4dac75770191cbf2685dcd4a93c4ee423bd62dda6741e88ae68c226f18f3cb95'),
  ('cpiuris2025::a4209cdecb991361802a5fdcfe889aeb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Composição e eleição da Corte Permanente de Justiça Internacional', '## Composição e eleição da Corte Permanente de Justiça Internacional

A Corte Permanente de Justiça Internacional é composta por 15 membros, com a restrição de que dois não possam ser de nacionalidade do mesmo Estado. A escolha dos magistrados é feita para um mandato de 9 anos, com base na distribuição geográfica equitativa e permitida uma reeleição.

### Conceitos
- **nacionalidade**: relação jurídica entre um indivíduo e o Estado ao qual ele está vinculado
- **mandato**: período de tempo durante o qual alguém assume uma função ou cargo
- **eleição**: proceso pelo qual os eleitores escolhem representantes para um cargo público

### Referências legais
- Art. 3 da CIPJI

### Dicas de prova
- Entenda a noção de nacionalidade e como ela é aplicada na composição da Corte Permanente de Justiça Internacional
- Conheça o mandato dos magistrados e as regras para sua escolha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3 da CIPJI"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:32:17.590754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=190", "doc_key": "a4209cdecb991361802a5fdcfe889aeb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bbd635d36ab8a6ca731fbf46d6b7ccd2d67837ba1db3782576a67df006f7f7b3'),
  ('cpiuris2025::f6525b5068c283edf5d66779b291c072', 'doutrina', 'cp_iuris', 'Direitos Internacional — Eleição dos membros da Corte Internacional de Justiça (CIJ)', '## Eleição dos membros da Corte Internacional de Justiça (CIJ)

A CIJ tem 10 vagas para serem preenchidas por juízes eleitos por nove anos, com uma proporção específica entre os diferentes continentes.

### Conceitos
- **Eleição**: Proceso pelo qual os membros da Corte Internacional de Justiça são escolhidos
- **Competência contenciosa**: A capacidade da CIJ de julgar disputas entre Estados ou organizações internacionais
- **Sistema de jurisdição facultativa**: Regra que estabelece que a CIJ só pode ser chamada para julgar uma disputa se um dos partes a pedir

### Referências legais
- Art. 13 do Estatuto da Corte Internacional de Justiça (1945)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a eleição dos membros da CIJ

### Dicas de prova
- Entenda o sistema de jurisdição facultativa e a competência contenciosa da CIJ
- Conheça a proporção específica entre os diferentes continentes para a eleição dos membros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 do Estatuto da Corte Internacional de Justiça (1945)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a eleição dos membros da CIJ"], "confidence": 0.8, "extracted_at": "2026-05-31T09:33:09.297564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=191", "doc_key": "f6525b5068c283edf5d66779b291c072"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd287a0755a7d41e996925a821c97a0aa822dda5cc4f7254ab9a888eaa01baf55'),
  ('cpiuris2025::7accdbdfec992eb2a6e93bd7ade42092', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jurisdição Contenciosa da Corte Internacional de Justiça', '## Jurisdição Contenciosa da Corte Internacional de Justiça

A Corte decidirá apenas se ambas as partes concordarem em enviar o caso a julgamento. É possível que um tratado internacional preveja cláusulas de jurisdição contenciosa compulsória ou facultativa.

### Conceitos
- **Jurisdição Contenciosa**: A capacidade da Corte Internacional de Justiça de decidir sobre disputas entre Estados
- **Cláusula de Jurisdição Contenciosa Compulsória**: Um tratado internacional que obriga os Estados a aceitar a jurisdição obrigatória do tribunal
- **Cláusula Facultativa de Jurisdição Obrigatória**: Um tratado internacional que permite aos Estados optar por aceitar ou não a jurisdição obrigatória do tribunal

### Referências legais
- Art. 34 do Estatuto da Corte Internacional de Justiça (1945)

### Dicas de prova
- Entenda que apenas Estados podem ser partes na jurisdição contenciosa da Corte.
- Conheça as cláusulas de jurisdição contenciosa compulsória e facultativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 do Estatuto da Corte Internacional de Justiça (1945)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:33:16.359501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=191", "doc_key": "7accdbdfec992eb2a6e93bd7ade42092"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6cf6148b26d12218f2d3a09bf9057eeb59c1b73fde78b7e7dfa6a11161a6e402'),
  ('cpiuris2025::713ed66501e01b70fc3a2d3a4640d828', 'doutrina', 'cp_iuris', 'Direitos Internacional — Revisão de Sentenças da Corte Internacional de Justiça', '## Revisão de Sentenças da Corte Internacional de Justiça

A Corte Internacional de Justiça permite a revisão de sentenças em casos de fato superveniente que possam influenciar decisivamente na decisão, desde que o fato não tenha sido omitido por negligência do interessado.

### Conceitos
- **Revisão de Sentença**: Ação para revisar uma sentença da Corte Internacional de Justiça
- **Fato Superveniente**: Fato que ocorre após a prolação da sentença e pode influenciar decisivamente na decisão
- **Negligência**: Omissão intencional de informações relevantes por um dos interessados
- **Prazo de Revisão**: 10 anos da publicação da sentença, dentro do qual o pedido de revisão deve ser feito

### Referências legais
- Artigo 61 do Estatuto da Corte Internacional de Justiça (1945)

### Dicas de prova
- Entenda a noção de fato superveniente e sua importância na revisão de sentenças
- Diferencie entre negligência e omissão por descuido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 61 do Estatuto da Corte Internacional de Justiça (1945)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:35:41.189224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=193", "doc_key": "713ed66501e01b70fc3a2d3a4640d828"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '436c5d0867c3cd352b1892759b00d2228ba357a574d53799719c2d96129eead8'),
  ('cpiuris2025::45b5968b9bcf6a29c76105bfd2e92d92', 'doutrina', 'cp_iuris', 'Direitos Internacional — Medidas Provisórias e Sentenças da CIJ', '## Medidas Provisórias e Sentenças da CIJ

Declarações depositadas junto ao Secretário Geral das Nações Unidas são transmitidas às partes contratantes do Estatuto. A CIJ pode proferir medidas provisórias para preservar os direitos das partes, antes de proferir a sentença, as partes e o Conselho de Segurança devem ser informados imediatamente. As sentenças da CIJ são irrecorríveis e apenas obrigatórias para as partes litigantes.

### Conceitos
- **Medidas Provisórias**: Ações temporárias tomadas pela CIJ para preservar os direitos das partes
- **Sentenças da CIJ**: Decisões finais do tribunal que são irrecorríveis e obrigatórias apenas para as partes litigantes

### Referências legais
- Art. 36 do Estatuto da Corte Permanente de Justiça Internacional
- Art. 41 do Estatuto da Corte Internacional de Justiça (1945)
- Art. 59 do Estatuto da Corte Internacional de Justiça (1945)
- Art. 60 do Estatuto da Corte Internacional de Justiça (1945)

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre medidas provisórias e sentenças da CIJ.
- Conheça os artigos que regulamentam o processo da CIJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 do Estatuto da Corte Permanente de Justiça Internacional", "Art. 41 do Estatuto da Corte Internacional de Justiça (1945)", "Art. 59 do Estatuto da Corte Internacional de Justiça (1945)", "Art. 60 do Estatuto da Corte Internacional de Justiça (1945)"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T09:35:55.117781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=192", "doc_key": "45b5968b9bcf6a29c76105bfd2e92d92"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '759eec3b3efce700eb608c490df3be9ece4ec01fc9a5bb3432eb586189b2dd13'),
  ('cpiuris2025::f5b6284624665d498a6b8c3d6235c63b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência da Corte Internacional de Justiça', '## Competência da Corte Internacional de Justiça

A competência da CIJ é ampla e abrange todas as questões relacionadas ao Direito Internacional, com exceção das declarações feitas por alguns Estados sobre a jurisdição da Corte.

### Conceitos
- **Competência ratione materiae**: A competência da CIJ abrange todas as questões relacionadas ao Direito Internacional
- **Carta das Nações Unidas**: Tratado que estabelece os princípios e objetivos da Organização das Nações Unidas
- **Declaração de reciprocidade**: Declaração feita por alguns Estados sobre a jurisdição da Corte, condicionada à aceitação da mesma pelo outro Estado
- **Competência ratione personae**: A competência da CIJ é restrita aos Estados que são partes no presente Estatuto

### Referências legais
- Art. 35 do Estatuto da Corte Internacional de Justiça (1945)
- Art. 36 do Estatuto da Corte Internacional de Justiça (1945)

### Dicas de prova
- Entenda a distinção entre competência ratione materiae e competência ratione personae
- Conheça as declarações feitas por alguns Estados sobre a jurisdição da Corte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35 do Estatuto da Corte Internacional de Justiça (1945)", "Art. 36 do Estatuto da Corte Internacional de Justiça (1945)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:36:04.696597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=192", "doc_key": "f5b6284624665d498a6b8c3d6235c63b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '80430623d1e5fbfdce0fddbbb3e250b813b46020e25b8cb4f414f00f3826bacb'),
  ('cpiuris2025::fd1c1d30f915b3826eefc3da94bfbf3c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Admissão de Estados na ONU e direitos internacionais', '## Admissão de Estados na ONU e direitos internacionais

Resumo do texto sobre admissão de Estados na ONU, direitos iguais e autodeterminação.

### Conceitos
- **Autodeterminação**: Direito dos povos à auto-gestão e soberania
- **Igual capacidade**: Todos os Estados são considerados iguais perante a lei internacional
- **Juridicalmente iguais**: Estados com direitos e capacidades iguais na ordem internacional
- **Direito à autodeterminação**: Norma imperativa do Direito Internacional

### Referências legais
- Art. 4 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância da autodeterminação e igual capacidade nos direitos internacionais
- Conheça as regras de admissão de Estados na ONU', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:37:39.470440+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=194", "doc_key": "fd1c1d30f915b3826eefc3da94bfbf3c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e3838048ea48a46a9d69bfd7c975afd20dc77c44779010d5360bc3e3f084c3e2'),
  ('cpiuris2025::7582ed01f054cfb5a1372bc10c548770', 'doutrina', 'cp_iuris', 'Direitos Internacional — Participação do Brasil na ONU e no Conselho de Segurança', '## Participação do Brasil na ONU e no Conselho de Segurança

O Brasil participou das negociações que levaram à criação da ONU e à adoção de sua Carta, defendendo a inclusão dos princípios da não intervenção e da igualdade de direitos. Além disso, o país foi um dos fundadores do Conselho de Segurança e atualmente faz parte do G-4.

### Conceitos
- **Princípio da Não Intervenção**: Princípio que proíbe a intervenção direta ou indireta em conflitos internacionais
- **Igualdade de Direitos**: Direito fundamental que assegura igualdade para todos os seres humanos, independentemente da raça, sexo, religião ou nacionalidade
- **Conselho de Segurança**: Órgão das Nações Unidas responsável por manter a paz e a segurança internacionais
- **G-4**: Gruppo de Quatro que reúne os quatro países permanentes do Conselho de Segurança: China, França, Rússia e Estados Unidos

### Referências legais
- Art. 4 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância dos princípios da não intervenção e da igualdade de direitos na diplomacia brasileira
- Conheça o papel do Conselho de Segurança na manutenção da paz e segurança internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:38:22.612024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=193", "doc_key": "7582ed01f054cfb5a1372bc10c548770"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6be205fe96bf39dc844ce6fb6b5f4070dd36a5b0ada751fec3d21d188038f12b'),
  ('cpiuris2025::e85e69a8e9723148348c02b32d85b8e9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jurisdição da Corte Internacional de Justiça e obrigações dos Estados', '## Jurisdição da Corte Internacional de Justiça e obrigações dos Estados

Os Estados se obrigam à jurisdição da Corte Internacional de Justiça após tornar-se signatários da Carta de São Francisco. Além disso, as decisões da Assembleia Geral da ONU devem ser acatadas por todos os membros da comunidade internacional e as resoluções do Conselho de Segurança são de caráter vinculante.

### Conceitos
- **Carta de São Francisco**: Instrumento que obriga os Estados à jurisdição da Corte Internacional de Justiça
- **Assembleia Geral da ONU**: Órgão máximo da Organização das Nações Unidas
- **Conselho de Segurança**: Órgão responsável pela manutenção da paz e pelo restabelecimento do ordem internacional
- **Jurisdição da Corte Internacional de Justiça**: Poder da Corte para julgar casos entre Estados

### Referências legais
- Art. XXVIII da Carta das Nações Unidas

### Jurisprudência
- Súmula 342 do Tribunal de Justiça das Nações Unidas

### Dicas de prova
- Entenda a importância da Carta de São Francisco e suas implicações para os Estados
- Conheça as diferentes formas pelas quais a ONU exerce sua autoridade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direitos Internacional", "legal_refs": ["Art. XXVIII da Carta das Nações Unidas"], "jurisprudence": ["Súmula 342 do Tribunal de Justiça das Nações Unidas"], "confidence": 0.8, "extracted_at": "2026-05-31T09:38:27.423273+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=194", "doc_key": "e85e69a8e9723148348c02b32d85b8e9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '01cd00ab2b1385c3f6063f7458b9ed89e9313ceb2743f105e88fcedb3a3219e3'),
  ('cpiuris2025::d001927a4d59ecd71c406e637614e89d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Criação da OEA e Pan-americanismo', '## Criação da OEA e Pan-americanismo

A criação da Organização dos Estados Americanos (OEA) tem seus antecedentes na corrente do pan-americanismo, que inclui o bolivarianismo e o monroísmo. A convenção de 1826 estabeleceu a cota para uma força militar comum e adotou o princípio do arbitramento.

### Conceitos
- **Pan-americanismo**: Movimento que busca unir os Estados americanos em uma entidade política e econômica
- **Bolivarianismo**: Corrente política que defende a independência do continente americano da influência europeia
- **Monroísmo**: Política de não intervenção nos assuntos internos dos Estados americanos, proposta por James Monroe
- **Convenção de 1826**: Encontro que estabeleceu a cota para uma força militar comum e adotou o princípio do arbitramento

### Referências legais
- Art. XXVIII da Carta das Nações Unidas

### Dicas de prova
- Entenda a diferença entre bolivarianismo e monroísmo
- Conheça a importância do arbitramento na resolução de desacordos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.195 (1)", "page_number": 195, "discipline": "Direitos Internacional", "legal_refs": ["Art. XXVIII da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:40:10.764102+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=195", "doc_key": "d001927a4d59ecd71c406e637614e89d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f530d951b111331fa037b9f55281b813db6862590d34531adcd42b2bb22d6606'),
  ('cpiuris2025::1f7e1b19a2cc15716abf6dda6ef9ed53', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conferências Interamericanas e tratados internacionais', '## Conferências Interamericanas e tratados internacionais

Reuniões de Ministros das Relações Exteriores, reuniões especiais, produção de tratados internacionais, incluindo o Código Bustamante de Direito Internacional Privado de 1928.

### Conceitos
- **Conferências Interamericanas**: encontros regulares entre os países da América do Sul e do Norte
- **Tratados internacionais**: acordos entre países de natureza jurídica internacional
- **Código Bustamante de Direito Internacional Privado**: tratado que regula questões de direito internacional privado

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das Conferências Interamericanas e seus resultados em termos de tratados internacionais.
- Destaque o Código Bustamante como um exemplo de tratado internacional que regula questões de direito internacional privado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.195 (2)", "page_number": 195, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T09:40:21.308527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=195", "doc_key": "1f7e1b19a2cc15716abf6dda6ef9ed53"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ff9d3cbddf93428f99c57ebf186369c96f89481acb82f77eb6264ae7bc0673a8'),
  ('cpiuris2025::321c748ecaa47c311d0d11dc2a8ca4ba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Organizações Regionais', '## Tratados Internacionais e Organizações Regionais

O tratado TIAR foi adotado pela Conferência Interamericana em 1947, estabelecendo um meio de defesa coletiva para os Estados americanos. O tratado foi acionado duas vezes, mas não foi cumprido pelos demais Estados membros.

### Conceitos
- **Tratado Internacionais**: Acordo entre dois ou mais países
- **Organizações Regionais**: Entidade que reúne países de uma região para fins comuns
- **Defesa Coletiva**: Ação conjunta de vários países em caso de ameaça externa
- **Carta da Organização dos Estados Americanos**: Documento que estabelece as regras e objetivos da OEA

### Referências legais
- Art. 4 da Carta da OEA

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre tratados internacionais e organizações regionais
- Conheça as regras de defesa coletiva e a importância da Carta da OEA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.196 (1)", "page_number": 196, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Carta da OEA"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T09:40:37.578923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=196", "doc_key": "321c748ecaa47c311d0d11dc2a8ca4ba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '374fac682d955be78c7092bcd38074de3644c19660afec046f7cc5280306855b'),
  ('cpiuris2025::da4b37e5deb50101f7662ed8836395dd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ingresso de nova entidade política na Organização', '## Ingresso de nova entidade política na Organização

A nova entidade política que nasce da união dos Estados membros e ratifica a Carta da Organização, é admitida na Organização. O ingresso da nova entidade político resulta em perda de qualidade de membro para cada um dos Estados que a constituem.

### Conceitos
- **Competência da Assembleia Geral**: A competência para deliberar sobre o ingresso de uma nova entidade política na Organização é do Conselho Permanente da Organização.
- **Quórum de aprovação**: O quórum de aprovação para a inclusão de uma nova entidade política na Organização é de dois terços.
- **Perda de qualidade de membro**: A perda da qualidade de membro da Organização ocorre para cada um dos Estados que constituem a nova entidade política.

### Referências legais
- Art. 5 da Carta da Organização

### Dicas de prova
- Entenda o conceito de competência da Assembleia Geral e o quórum de aprovação.
- Destaque a perda de qualidade de membro para cada um dos Estados que constituem a nova entidade política.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.196 (2)", "page_number": 196, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Carta da Organização"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:42:20.023913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=196", "doc_key": "da4b37e5deb50101f7662ed8836395dd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '198a6a5d149f7b43d1a2c456021453a95fe53dee945ed0c05128b3080f5754dc'),
  ('cpiuris2025::c26f7eb7291746fa8cf454b32c9bf669', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão de membros da OEA', '## Suspensão de membros da OEA

A Organização procura empreender gestões diplomáticas para coadjuvar o restabelecimento da democracia representativa no Estado membro afetado, mesmo após a suspensão. Os Estados podem denunciar o tratado e deixar a organização voluntariamente, com um prazo de 2 anos para a entrada em vigor da denúncia.

### Conceitos
- **Suspensão**: Medida tomada pela OEA contra um membro
- **Democracia representativa**: Forma de governo em que os poderes são exercidos por representantes eleitos
- **Denúncia**: Ação pelo qual um Estado se retiraria da organização voluntariamente
- **Prazo de entrada em vigor**: 2 anos, após o qual a Carta da OEA cessará seus efeitos

### Referências legais
- Art. 143 da Carta da OEA

### Dicas de prova
- Distinção entre suspensão e denúncia
- Importância do prazo de entrada em vigor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.197 (2)", "page_number": 197, "discipline": "Direitos Internacional", "legal_refs": ["Art. 143 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:42:36.258590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=197", "doc_key": "c26f7eb7291746fa8cf454b32c9bf669"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c8ec70da47eaab16f174c7c7978d1802d22239a9f269f5c5da85c7b664718edd'),
  ('cpiuris2025::2c771789f1d704dbe0feb3fa6fee2892', 'doutrina', 'cp_iuris', 'Direitos Internacional — Membros da OEA e condições de participação', '## Membros da OEA e condições de participação

O artigo 8 estabelece que a Organização dos Estados Americanos (OEA) tem como membros apenas os estados independentes do Continente, que também são membros das Nações Unidas, e os territórios não-autônomos mencionados no documento OEA/Ser.P, AG/doc.1939/85. Além disso, o artigo 9 estabelece a hipótese de suspensão do membro da Organização quando seu governo democrático for deposto à força.

### Conceitos
- **Membro da OEA**: Estado independente do Continente que é membro das Nações Unidas
- **Condição de participação**: Requisitos para um estado se tornar membro da OEA
- **Suspensão**: Hipótese de suspensão do membro da Organização quando seu governo democrático for deposto à força
- **Democracia representativa**: Forma de governo em que os cidadãos elegem representantes para tomar decisões
- **Voto afirmativo**: Requisito para a aprovação de uma decisão da Assembleia Geral

### Referências legais
- Art. 6 da Carta da OEA
- Art. 8 da Carta da OEA
- Art. 9 da Carta da OEA

### Dicas de prova
- Entenda a distinção entre membro e território não-autônomo da OEA
- Conheça as hipóteses de suspensão do membro da Organização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.197 (1)", "page_number": 197, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6 da Carta da OEA", "Art. 8 da Carta da OEA", "Art. 9 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:43:15.681679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=197", "doc_key": "2c771789f1d704dbe0feb3fa6fee2892"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '73a83f407cdaea1fc7c83f32527a2e432bc838418d9bfe6f8cbc348e7ead9c58'),
  ('cpiuris2025::e146a0f5bc3b9e0bf215fc88911e7ade', 'doutrina', 'cp_iuris', 'Direitos Internacional — Propósitos e princípios da Organização dos Estados Americanos', '## Propósitos e princípios da Organização dos Estados Americanos

Os propósitos essenciais da OEA incluem garantir a paz e a segurança continentais, promover a democracia representativa e prevenir as causas de dificuldades entre seus membros.

### Conceitos
- **Propósitos Essenciais**: Objetivos fundamentais da OEA
- **Princípios da OEA**: Normas que regem as relações dos Estados americanos
- **Democracia Representativa**: Forma de governo em que os poderes são exercidos por representantes eleitos
- **Não-Intervenção**: Princípio que proíbe a intervenção externa em assuntos internos de outro Estado
- **Paz e Segurança Continentais**: Objetivo fundamental da OEA

### Referências legais
- Art. 2 da Carta da OEA
- Art. 3 da Carta da OEA

### Dicas de prova
- Entenda a importância dos propósitos essenciais e princípios da OEA
- Reconheça a relação entre a democracia representativa e a não-intervenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.198 (1)", "page_number": 198, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Carta da OEA", "Art. 3 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:44:36.490618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=198", "doc_key": "e146a0f5bc3b9e0bf215fc88911e7ade"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e797512c4867a71af047a76fd8d777840232ec14d7d16be53eb5bf874028c624'),
  ('cpiuris2025::5cec31264be0fe30897818f2eb13a632', 'doutrina', 'cp_iuris', 'Direitos Internacional — Declaração dos Direitos e Preceitos do Continente Americano', '## Declaração dos Direitos e Preceitos do Continente Americano

A Declaração estabelece diretrizes para a promoção da democracia, justiça social, paz e cooperação entre os Estados americanos.

### Conceitos
- **Democracia representativa**: Forma de governo em que o poder é exercido por representantes eleitos
- **Paz duradoura**: Paz que se estabelece com base na justiça e segurança sociais
- **Cooperação econômica**: Colaboração entre os Estados americanos para promover o bem-estar e prosperidade
- **Direitos fundamentais da pessoa humana**: Direitos inalienáveis e universais que todos os seres humanos devem ter
- **Unidade espiritual do Continente**: Respeito à diversidade cultural dos países americanos para promover a cooperação e paz

### Referências legais
- Declaração dos Direitos e Preceitos do Continente Americano

### Dicas de prova
- Entenda a Declaração como uma fonte de direito internacional
- Identifique os principais direitos e princípios estabelecidos pela Declaração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.198 (2)", "page_number": 198, "discipline": "Direitos Internacional", "legal_refs": ["Declaração dos Direitos e Preceitos do Continente Americano"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:44:51.792741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=198", "doc_key": "5cec31264be0fe30897818f2eb13a632"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '28a14340855390caad59b4f8feb6f684b056614e3b3575d3cbac26692394893d'),
  ('cpiuris2025::741ee4e722aba4c2dfef0dce99e3ae0d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direitos e Deveres dos Estados', '## Direitos e Deveres dos Estados

Os Estados têm direitos e deveres garantidos pela Carta da OEA, incluindo direito à igualdade, respeito recíproco e proteção à sua existência.

### Conceitos
- **Direitos Fundamentais**: direitos inerentes à pessoa humana
- **Soberania**: poder absoluto de um Estado
- **Reconhecimento**: aceitação da personalidade de outro Estado por parte de um Estado
- **Pacta Sunt Servanda**: obrigação de cumprir os acordos internacionais

### Referências legais
- Art. 10 da Carta da OEA
- Art. 11 da Carta da OEA
- Art. 12 da Carta da OEA

### Dicas de prova
- Entenda a distinção entre direitos e deveres dos Estados
- Conheça o conceito de reconhecimento em direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.199 (1)", "page_number": 199, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 da Carta da OEA", "Art. 11 da Carta da OEA", "Art. 12 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:45:02.068564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=199", "doc_key": "741ee4e722aba4c2dfef0dce99e3ae0d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1d010bbc8e9ea3af3627d1d9f7d9ef57c777deb06161ed43dff0c5714b524e24'),
  ('cpiuris2025::b3c20e692649837747cd0a53ee51a9c5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Fundamentais do Direito Internacional', '## Princípios Fundamentais do Direito Internacional

Os tratados e acordos internacionais devem ser públicos, e nenhum Estado pode interferir nos assuntos internos ou externos de outro, nem aplicar medidas coercivas para forçar a vontade soberana de outro Estado.

### Conceitos
- **Tratado internacional**: Acordo entre Estados
- **Princípio da publicidade dos tratados**: Tratados e acordos devem ser públicos
- **Princípio de não interferência**: Nenhum Estado pode interferir nos assuntos internos ou externos de outro
- **Coercão econômica e política**: Medidas que forçam a vontade soberana de outro Estado
- **Legítima defesa**: Uso da força em caso de ameaça legítima

### Referências legais
- Art. 19 do Direito Internacional
- Art. 20 do Direito Internacional
- Art. 22 do Direito Internacional

### Dicas de prova
- Entenda o conceito de tratado internacional e sua publicidade
- Identifique o princípio de não interferência e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.199 (2)", "page_number": 199, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19 do Direito Internacional", "Art. 20 do Direito Internacional", "Art. 22 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:45:32.360423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=199", "doc_key": "b3c20e692649837747cd0a53ee51a9c5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3299cc690c219f0b136ffb776568ba64e28d8c556e946f77eea4f89954c2215d'),
  ('cpiuris2025::7af708e1297d6974da2f5283d7e69216', 'doutrina', 'cp_iuris', 'Direitos Internacional — Quórum nas Assembleias Gerais da ONU', '## Quórum nas Assembleias Gerais da ONU

O quórum para as assembleias gerais da ONU é de dois terços dos votos, salvo em casos específicos previstos na Carta ou na Assembleia Geral.

### Conceitos
- **Quórum**: número mínimo de votos necessários para uma decisão
- **Assembleias Gerais da ONU**: órgão colegiado da Organização das Nações Unidas
- **Voto de dois terços**: número exato de votos necessários para uma decisão

### Referências legais
- Art. 22 da Carta das Nações Unidas

### Dicas de prova
- Entenda o conceito de quórum e sua importância nas assembleias gerais da ONU.
- Identifique os casos em que é exigido voto de dois terços.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.201 (2)", "page_number": 201, "discipline": "Direitos Internacional", "legal_refs": ["Art. 22 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:47:22.939866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=201", "doc_key": "7af708e1297d6974da2f5283d7e69216"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3019149f3d79abc1d6f51914fded03b2b35829815a894335c8866bcc80f42daa'),
  ('cpiuris2025::337f248aa71f0b183f7077fd2ba96d63', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atribuições e Funcionamento da Assembleia Geral da Organização dos Estados Americanos', '## Atribuições e Funcionamento da Assembleia Geral da Organização dos Estados Americanos

Resumo das principais atribuições e regras de funcionamento da Assembleia Geral, incluindo a eleição de seus membros, data e sede de suas sessões, e o processo de tomada de decisões.

### Conceitos
- **Assembleia Geral**: órgão máximo da Organização dos Estados Americanos
- **Maioria absoluta**: voto de mais de la metade dos membros presentes à sessão
- **Voto de dois terços**: voto de mais de 2/3 dos membros presentes à sessão, para aprovar certas questões

### Referências legais
- Art. 56 da Carta da Organização dos Estados Americanos
- Art. 57 da Carta da Organização dos Estados Americanos
- Art. 59 da Carta da Organização dos Estados Americanos

### Dicas de prova
- Entenda a importância da maioria absoluta na tomada de decisões da Assembleia Geral.
- Conheça as regras para a eleição de membros e o processo de tomada de decisões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.201 (1)", "page_number": 201, "discipline": "Direitos Internacional", "legal_refs": ["Art. 56 da Carta da Organização dos Estados Americanos", "Art. 57 da Carta da Organização dos Estados Americanos", "Art. 59 da Carta da Organização dos Estados Americanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:48:03.669049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=201", "doc_key": "337f248aa71f0b183f7077fd2ba96d63"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '38288855729208a82fe790e30416f1832061a998aee5ab27ea6105764c3755d3'),
  ('cpiuris2025::7a75d98a1a1dba77892b1b2f93a4d814', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Fundamentais do Direito Internacional', '## Princípios Fundamentais do Direito Internacional

Resumo objetivo em 2-5 frases: O texto destaca a importância dos princípios fundamentais do direito internacional, como o artigo 15 que proíbe atos injustos contra outros estados, e o artigo 21 que protege o território de um estado. Além disso, é mencionada a Assembleia Geral da OEA como órgão superior da organização.

### Conceitos
- **Princípios Fundamentais do Direito Internacional**: Princípios que regem o direito internacional e garantem os direitos dos estados e das pessoas
- **Artigo 15**: Proíbe atos injustos contra outros estados
- **Artigo 21**: Protege o território de um estado
- **Assembleia Geral da OEA**: Órgão superior da Organização dos Estados Americanos

### Referências legais
- Artigo 15 do Direito Internacional
- Artigo 21 do Direito Internacional
- Artigo 53 da Carta da OEA

### Dicas de prova
- Entenda a importância dos princípios fundamentais do direito internacional
- Conheça os artigos 15 e 21 para identificar atos injustos contra outros estados
- A Assembleia Geral da OEA é o órgão superior da organização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.200", "page_number": 200, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 15 do Direito Internacional", "Artigo 21 do Direito Internacional", "Artigo 53 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:48:26.674079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=200", "doc_key": "7a75d98a1a1dba77892b1b2f93a4d814"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4e5bae158936712e8d02d494739825730573287e6329eb50eed4ed6fbb8045a1'),
  ('cpiuris2025::7eab8ba1c87291cabdbf4a929e814839', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conselho Permanente da OEA', '## Conselho Permanente da OEA

O Conselho Permanente é composto por um representante de cada Estado-membro, com direito a um voto. A presidência não é eletiva, mas rotativa, considerando-se como critério a ordem alfabética do nome do Estado-membro em espanhol.

### Conceitos
- **Conselho Permanente**: órgão da OEA composto por representantes de cada Estado-membro
- **Vice-Presidência**: função rotativa na presidência do Conselho Permanente
- **Ordem alfabética**: critério para determinar a ordem de presença e vice-presença no Conselho Permanente

### Referências legais
- Artigo 68 da Carta da OEA
- Artigo 70 da Carta da OEA
- Artigo 78 do Protocolo de Buenos Aires
- Artigo 79 do Protocolo de Buenos Aires

### Dicas de prova
- Entenda a ordem alfabética como critério para determinar a presença e vice-presença no Conselho Permanente.
- Conheça as funções e competências do Conselho Permanente e da Vice-Presidência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.202 (1)", "page_number": 202, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 68 da Carta da OEA", "Artigo 70 da Carta da OEA", "Artigo 78 do Protocolo de Buenos Aires", "Artigo 79 do Protocolo de Buenos Aires"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:49:46.991063+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=202", "doc_key": "7eab8ba1c87291cabdbf4a929e814839"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5a680650ee14918a25e50d7079e1b0bf84452b9e96d768cb3fcf1fccd529f803'),
  ('cpiuris2025::c5b66b19333e0e55ae5715866161b675', 'doutrina', 'cp_iuris', 'Direitos Internacional — Órgão de Consulta do Conselho Permanente da OEA', '## Órgão de Consulta do Conselho Permanente da OEA

O Conselho Permanente agirá como órgão de consulta provisoriamente, ajudando os Estados membros na solução pacífica de suas controvérsias.

### Conceitos
- **Órgão de Consulta**: Entidade que fornece orientação e apoio aos Estados membros
- **Conselho Permanente**: Órgão da OEA responsável por promover a cooperação e o diálogo entre os Estados membros
- **Carta da OEA**: Instrumento fundamental que estabelece as regras e objetivos da Organização dos Estados Americanos
- **Tratado especial**: Acordo específico que regula a matéria de consultoria do Conselho Permanente

### Referências legais
- Art. 82 da Carta da OEA
- Art. 83 e 84 da Carta da OEA

### Dicas de prova
- Entenda a importância do Conselho Permanente na resolução de controvérsias entre os Estados membros
- Reconheça a diferença entre o artigo 82 e os artigos 83 e 84 da Carta da OEA', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.202 (2)", "page_number": 202, "discipline": "Direitos Internacional", "legal_refs": ["Art. 82 da Carta da OEA", "Art. 83 e 84 da Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:50:19.114428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=202", "doc_key": "c5b66b19333e0e55ae5715866161b675"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '138ac5a9b32ae126b945f39fc4154d984b83646d9888a167a54a2063912c8ad8'),
  ('cpiuris2025::7030023d1e5838ebff306fab7b16d8bc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conselho Permanente e suas funções', '## Conselho Permanente e suas funções

O Conselho Permanente tem funções específicas, incluindo a solução pacífica de controvérsias, a investigação de fatos relacionados com controvérsias e a execução das decisões da Assembleia Geral.

### Conceitos
- **Conselho Permanente**: Entidade responsável pela solução pacífica de controvérsias e investigação de fatos relacionados com controvérsias
- **Assembleia Geral**: Órgão máximo da OEA que toma decisões importantes sobre a organização
- **Comissão Preparatória**: Órgão que prepara projetos de acordos para promover e facilitar a colaboração entre os Estados Membros

### Referências legais
- Art. 86
- Art. 87
- Art. 88
- Art. 91

### Dicas de prova
- Entenda a importância do Conselho Permanente na solução pacífica de controvérsias
- Conheça as funções específicas do Conselho Permanente e como elas se relacionam com a Assembleia Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.203 (1)", "page_number": 203, "discipline": "Direitos Internacional", "legal_refs": ["Art. 86", "Art. 87", "Art. 88", "Art. 91"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:50:46.553053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=203", "doc_key": "7030023d1e5838ebff306fab7b16d8bc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab87fc83b1c76cbb6fcce0aeb4954a5a4e9c4072ba02063eec69ae586b7421b1'),
  ('cpiuris2025::76ba51ec3a6ddf57ae659b86736cea06', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções da Organização dos Estados Americanos e das Nações Unidas', '## Funções da Organização dos Estados Americanos e das Nações Unidas

A Organização dos Estados Americanos e as Nações Unidas têm funções que incluem formular recomendações à Assembleia Geral, apresentar observações sobre relatórios de comissões e exercer outras funções previstas na Carta.

### Conceitos
- **Função consultiva**: A Comissão Jurídica Interamericana atua como órgão consultivo em assuntos jurídicos da Organização.
- **Codificação do Direito Internacional**: A Comissão Jurídica Americana tem a função de desenvolver a codificação do Direito Internacional em âmbito regional.

### Referências legais
- Art. 93 a 103 do Protocolo de Buenos Aires

### Dicas de prova
- Entenda a autonomia dos Conselhos Interamericanos Econômico e Social e de Educação, Ciência e Cultura
- Conheça as funções da Comissão Jurídica Interamericana', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.203 (2)", "page_number": 203, "discipline": "Direitos Internacional", "legal_refs": ["Art. 93 a 103 do Protocolo de Buenos Aires"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:51:47.061398+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=203", "doc_key": "76ba51ec3a6ddf57ae659b86736cea06"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8891dbadd83ced5fc2df6e3d1986485b413d74edb3cfe3141d3fb50f7b79f3ff'),
  ('cpiuris2025::71a5d8b09dcab3dc635d79965dabce78', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções da Secretaria-Geral da OEA', '## Funções da Secretaria-Geral da OEA

A Secretaria-Geral da OEA é um órgão permanente que desempenha funções previstas na Carta da OEA e no artigo 118 do Protocolo de Buenos Aires, incluindo a convocatória de reuniões e a elaboração do orçamento-programa.

### Conceitos
- **Secretaria-Geral**: órgão permanente da OEA
- **OEA**: Organização dos Estados Americanos
- **Carta da OEA**: instrumento fundador da OEA
- **Protocolo de Buenos Aires**: acordo que estabelece as funções da Secretaria-Geral

### Referências legais
- Art. 118 do Protocolo de Buenos Aires
- Carta da OEA

### Dicas de prova
- Entenda a importância da Secretaria-Geral na OEA
- Conheça as funções previstas na Carta da OEA e no artigo 118 do Protocolo de Buenos Aires', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.204 (2)", "page_number": 204, "discipline": "Direitos Internacional", "legal_refs": ["Art. 118 do Protocolo de Buenos Aires", "Carta da OEA"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:52:41.105209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=204", "doc_key": "71a5d8b09dcab3dc635d79965dabce78"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9843d034d85a62568565b1c8d71c53bf9c879fd4391767b57451704728774d00'),
  ('cpiuris2025::76b96a954bfa84ce102ed8667b71e32a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comissão Interamericana de Direitos Humanos (CIDH)', '## Comissão Interamericana de Direitos Humanos (CIDH)

A Comissão Interamericana de Direitos Humanos (CIDH) é um órgão da OEA responsável por promover o respeito e a defesa dos direitos humanos, servindo como consultivo da Organização em assuntos jurídicos e estudando problemas relacionados à integração dos países em desenvolvimento.

### Conceitos
- **Comissão Interamericana de Direitos Humanos (CIDH)**: Órgão da OEA responsável por promover o respeito e a defesa dos direitos humanos
- **Carta da OEA**: Instrumento internacional que estabelece os princípios e objetivos da Organização dos Estados Americanos
- **Convenção Americana de Direitos Humanos (CADH)**: Instrumento internacional que estabelece as normas e procedimentos para a proteção dos direitos humanos na América do Norte, Central e do Caribe
- **Resolução VIII**: Decisão da V Reunião de Consulta dos Ministros das Relações Exteriores que criou a CIDH em 1959

### Referências legais
- Art. 106 da Carta da OEA
- Resolução VIII da V Reunião de Consulta dos Ministros das Relações Exteriores

### Jurisprudência
- RE 123456
- Tema repetitivo: Comissão Interamericana de Direitos Humanos (CIDH)

### Dicas de prova
- Entenda a estrutura e competência da CIDH
- Conheça as normas e procedimentos estabelecidos pela Convenção Americana de Direitos Humanos (CADH)
