  ('cpiuris2025::c82431c800baab8011c54f5b8e2445f0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Funções do Secretário-Geral da OEA', '## Funções do Secretário-Geral da OEA

O Secretário-Geral é responsável por representar a OEA em âmbito internacional e tem direito de voz nas reuniões da organização. Ele é eleito pela Assembleia Geral para um período de cinco anos e não pode ser reeleito mais de uma vez.

### Conceitos
- **Secretário-Geral**: Responsável por representar a OEA em âmbito internacional
- **Assembleia Geral**: Órgão máximo da OEA que eleita o Secretário-Geral
- **Mandato**: Período de tempo durante o qual alguém ocupa um cargo ou função

### Referências legais
- Art. 114 do Protocolo de Buenos Aires

### Dicas de prova
- Entenda a importância do Secretário-Geral na representação da OEA em âmbito internacional
- Conheça as regras para a eleição e o mandato do Secretário-Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.205 (1)", "page_number": 205, "discipline": "Direitos Internacional", "legal_refs": ["Art. 114 do Protocolo de Buenos Aires"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:53:49.017842+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=205", "doc_key": "c82431c800baab8011c54f5b8e2445f0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f9d7a39198ebb3fb677584ce38d186141daa332d5aa2ba2e807166bd2e825f90'),
  ('cpiuris2025::915723d5de33bc9e10a67333e0b20aca', 'doutrina', 'cp_iuris', 'Direitos Internacional — Órgão da OEA responsável por direitos humanos', '## Órgão da OEA responsável por direitos humanos

O órgão responsável por direitos humanos na OEA é denominado Alto Comissariado da OEA para os Direitos Humanos.

### Conceitos
- **Alto Comissariado**: órgão responsável por direitos humanos
- **OEA**: Organização dos Estados Americanos

