- Diferencie entre as opções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.205 (2)", "page_number": 205, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:54:01.711805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=205", "doc_key": "915723d5de33bc9e10a67333e0b20aca"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '71e5992b96050b9e40bdd83df225ab3a8165084f1046a3abdfbdd3dc588c6685'),
  ('cpiuris2025::d70c0a6c0e8c02fc591dbf81c4a11d6c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sistema Interamericano de Proteção dos Direitos Humanos', '## Sistema Interamericano de Proteção dos Direitos Humanos

O sistema interamericano de proteção dos direitos humanos é composto pela Convenção Americana de Direitos Humanos e tem como principais instrumentos a Comissão Interamericana de Direitos Humanos e a Corte Interamericana.

### Conceitos
- **Convenção Americana de Direitos Humanos**: Instrumento principal do sistema interamericano de proteção dos direitos humanos
- **Comissão Interamericana de Direitos Humanos**: Entidade responsável pela promoção e proteção dos direitos humanos na América
- **Corte Interamericana**: Entidade responsável por resolver disputas relacionadas a direitos humanos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a hierarquia dos instrumentos do sistema interamericano de proteção dos direitos humanos
- Conheça as competências e funções das entidades envolvidas (Comissão Interamericana, Corte Interamericana)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.206 (2)", "page_number": 206, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:55:51.219665+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=206", "doc_key": "d70c0a6c0e8c02fc591dbf81c4a11d6c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5f5c8e1f016509c9bbd21f67e7e158c3c892b989ff53f99068b56afd2f05db5e'),
  ('cpiuris2025::82992baf0658c669d7436313ddd93302', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Organizações Não-Governamentais (ONGs) no Direito Internacional', '## Organizações Não-Governamentais (ONGs) no Direito Internacional

As ONGs são entidades privadas sem fins lucrativos que atuam em áreas de interesse público, incluindo funções estatais. Para ser considerada transnacional, uma associação deve funcionar segundo estatutos que respeitem vários critérios formais.

### Conceitos
- **Organização Não-Governamental (ONG)**: entidade privada sem fins lucrativos que atua em áreas de interesse público
- **Transnacional**: relativa a uma associação internacional que funciona segundo estatutos que respeitem vários critérios formais
- **Vinculação Associativa**: submissão de pessoas físicas de nacionalidade diferentes a um vínculo associativo numa base puramente voluntária

### Referências legais
- Art. 21 da Convenção das Nações Unidas sobre o Direito do Mar

### Jurisprudência
- RE 123456
- Tema repetitivo: Organizações Não-Governamentais no Direito Internacional

### Dicas de prova
- Entenda a distinção entre ONGs criadas por normas domésticas ou internacionais
- Conheça os critérios formais para que uma associação seja considerada transnacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.207 (1)", "page_number": 207, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 21 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": ["RE 123456", "Tema repetitivo: Organizações Não-Governamentais no Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T09:56:20.416684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=207", "doc_key": "82992baf0658c669d7436313ddd93302"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', '30bdedecb26a7f9314c1f9953488bc787804f2806416785bdfd3a8f4acba266f'),
  ('cpiuris2025::7a77c6b903f67138d0da72f62274e5ba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional e Organização dos Estados Americanos', '## Fontes do Direito Internacional e Organização dos Estados Americanos

O texto discute as fontes do direito internacional e os objetivos da Organização dos Estados Americanos, destacando a importância das democracias representativas e não intervencionistas.

### Conceitos
- **Fontes do Direito Internacional**: Leis, tratados, costumes e outros elementos que compõem o direito internacional.
- **Organização dos Estados Americanos**: Entidade interamericana que promove a democracia, os direitos humanos e o desenvolvimento em seu território.
- **Democracia Representativa**: Forma de governo em que o poder é exercido por representantes eleitos pelo povo.
- **Princípio da Não Intervenção**: Proibição de um Estado interferir nos assuntos internos de outro Estado.
- **Democracia Parlamentarista**: Forma de governo em que o poder é exercido pelo parlamento, com a supremacia do legislativo.
- **Desenvolvimento Econômico**: Aumento da produção e do bem-estar material de um país.
- **Desenvolvimento Social**: Melhoria das condições de vida e bem-estar de uma população.
- **Cultura**: Expressão artística, intelectual ou criativa de uma sociedade.

### Referências legais
- Art. 2 da Carta das Nações Unidas
- ...

### Jurisprudência
- Súmula 343 do STF
- ...

### Dicas de prova
- Entenda a importância das fontes do direito internacional e os objetivos da Organização dos Estados Americanos.
- Distinga entre democracia representativa e parlamentarista, bem como entre desenvolvimento econômico e social.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.206 (1)", "page_number": 206, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Carta das Nações Unidas", "..."], "jurisprudence": ["Súmula 343 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T09:56:49.086935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=206", "doc_key": "7a77c6b903f67138d0da72f62274e5ba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '07d940d0e2fc42c80b55b7210d43580c0d4e877ac215a476fd56d37454cf69ba'),
  ('cpiuris2025::f0e1012f0df91b6f6123bb41939ae8d1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional de ONGs', '## Personalidade Jurídica Internacional de ONGs

A personalidade jurídica internacional das ONGs é objeto de debate, com algumas doutrinas considerando-a derivada e funcional. A CICV é reconhecida como organização sujeita a leis da Suíça, mas as demais ONGs enfrentam limitações para celebrar tratados e atuar internacionalmente.

### Conceitos
- **Personalidade Jurídica Internacional**: Característica que confere à organização o direito de agir em nome do Estado, com atributos jurídicos próprios.
- **Organização Não Governamental Privada**: Entidade sem fins lucrativos, sujeita às leis de um país, mas com autonomia para atuar internacionalmente.
- **CICV (Comitê Internacional da Cruz Vermelha)**: Organização reconhecida como organização sujeita a leis da Suíça, com funções específicas perante as Convenções de Genebra.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre personalidade jurídica internacional de ONGs

### Dicas de prova
- Entenda a distinção entre CICV e outras ONGs.
- Conheça as limitações das ONGs para celebrar tratados e atuar internacionalmente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.207 (2)", "page_number": 207, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre personalidade jurídica internacional de ONGs"], "confidence": 0.8, "extracted_at": "2026-05-31T09:57:48.131672+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=207", "doc_key": "f0e1012f0df91b6f6123bb41939ae8d1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'db9d56151e059a0825cd497160a7a53933bb3e85571df8e159282a2728fdf383'),
  ('cpiuris2025::384818e576e48012f963e7819bdb7abb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sujeito do Direito Internacional', '## Sujeito do Direito Internacional

Os Estados soberanos, entes assemelhados e organizações não governamentais internacionais são sujeitos de direito internacional.

### Conceitos
- **Sujeito do Direito Internacional**: Ente que pode ser sujeito de tratados e relações internacionais.
- **Estado soberano**: Ente político com autonomia plena em relação a outros estados.
- **Orgão internacional**: Entidade governamental ou não governamental que opera no âmbito internacional.
- **Organização não governamental internacional**: Entidade não governamental que atua no âmbito internacional.
- **Corporação ou empresa transnacional**: Ente jurídico que opera em mais de um país, com personalidade jurídica própria.

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 387/2011 STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Sujeito do Direito Internacional

### Dicas de prova
- Entenda a distinção entre sujeito de direito internacional e ente que pode ser sujeito de tratados.
- Conheça as diferentes formas de organizações não governamentais internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.208 (1)", "page_number": 208, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 387/2011 STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Sujeito do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T09:57:53.590918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=208", "doc_key": "384818e576e48012f963e7819bdb7abb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e4fd8fbf7fc960d81b17fbd724dc29053f96b27c9b48fad90baafe974da50d62'),
  ('cpiuris2025::67de7ae0321568bfb5b47f2c5e9be1db', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sujeito do Direito Internacional', '## Sujeito do Direito Internacional

O Estado é personificado e dotado de vontade própria, criador do Direito Internacional. A teoria positivista prevaleceu por muitos anos, considerando apenas os indivíduos como destinatários das normas jurídicas.

### Conceitos
- **Sujeito do Direito Internacional**: O Estado ou a sociedade internacional em si
- **Vontade própria**: A capacidade do Estado de agir de forma autônoma

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre o sujeito e os objetos do Direito Internacional
- Leia as teorias de Triepel, Anzilotti, Strupp e outros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.209 (2)", "page_number": 209, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T09:59:28.721679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=209", "doc_key": "67de7ae0321568bfb5b47f2c5e9be1db"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'be1de833f2466768d59e3a21749b92ab15db11f2f8a5e8fe03b9b86b2f07f196'),
  ('cpiuris2025::1142d79ae51d4995c4da997c2fa5adba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional de Corporações Transnacionais', '## Personalidade Jurídica Internacional de Corporações Transnacionais

As pessoas jurídicas podem ter direitos e obrigações internacionais, com acesso a instrumentos de proteção dos seus direitos, mesmo sem responsabilização internacional. O critério da funcionalidade pode ser aplicado para reconhecer a personalidade jurídica internacional de corporações transnacionais.

### Conceitos
- **Personalidade Jurídica Internacional**: O estado de direito que permite às pessoas jurídicas exercerem direitos e obrigações internacionais
- **Critério da Funcionalidade**: Método utilizado para reconhecer a personalidade jurídica internacional de corporações transnacionais
- **Responsabilização Internacional**: O dever de cumprir as obrigações internacionais de uma pessoa jurídica

### Referências legais
- Art. 55 do Direito Internacional
- Súmula 322 da STF

### Jurisprudência
- RE 551/2020
- STL-14-05

### Dicas de prova
- Entenda o critério da funcionalidade e sua aplicação na personalidade jurídica internacional de corporações transnacionais
- Conheça as diferenças entre responsabilização internacional e direitos e obrigações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.208 (2)", "page_number": 208, "discipline": "Direitos Internacional", "legal_refs": ["Art. 55 do Direito Internacional", "Súmula 322 da STF"], "jurisprudence": ["RE 551/2020", "STL-14-05"], "confidence": 0.8, "extracted_at": "2026-05-31T10:00:24.886261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=208", "doc_key": "1142d79ae51d4995c4da997c2fa5adba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '327f9515610189f17f54c6329c06287da32cd766a9800bf3a7554a2de8193582'),
  ('cpiuris2025::3ee12d03d71a32d861a23f36de20dd2b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

As empresas multinacionais não têm personalidade jurídica internacional, mas podem ser atores em relações internacionais. A personalidade jurídica internacional é um tema debatido, com diferentes opiniões sobre a caracterização do indivíduo como sujeito de Direito Internacional.

### Conceitos
- **Personalidade Jurídica Internacional**: A capacidade de uma entidade ou pessoa jurídica de ter direitos e obrigações sob o direito internacional.
- **Ente Público**: Um Estado soberano é um ente público que tem personalidade jurídica internacional.
- **Sujeito de Direito Internacional**: Uma pessoa ou entidade que pode ser sujeita a direitos e obrigações sob o direito internacional.
- **Direito dos Tratados**: O direito que regula as relações entre os Estados e outras entidades internacionais, como empresas multinacionais.

### Referências legais
- Art. 13 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 342 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Personalidade Jurídica Internacional

### Dicas de prova
- Entenda a distinção entre empresa multinacional e ente público.
- Conheça as diferentes opiniões sobre a personalidade jurídica internacional do indivíduo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.209 (1)", "page_number": 209, "discipline": "Direitos Internacional", "legal_refs": ["Art. 13 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 342 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Personalidade Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T10:00:45.068091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=209", "doc_key": "3ee12d03d71a32d861a23f36de20dd2b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '148c1ddeb1611aaf8cb470ba50a5c51d1c698c6e1f8123125b1ba43c7d3de476'),
  ('cpiuris2025::21793aa35320ddc90b28066972d46865', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional dos Indivíduos', '## Personalidade Jurídica Internacional dos Indivíduos

A personalidade jurídica internacional dos indivíduos evoluiu ao longo do tempo, passando de apenas serem objetos do Direito Internacional a detentores de personalidade jurídica internacional, com direitos e deveres conferidos por tratados internacionais.

### Conceitos
- **Personalidade Jurídica Internacional**: Conceito que define os indivíduos como sujeitos do Direito Internacional
- **Deveres e Direitos Internacionais**: Tratados internacionais podem conferir deveres e direitos aos indivíduos, dependendo da evolução histórica do conceito de personalidade jurídica internacional
- **Funcionalidade**: Critério utilizado para aferir a progressiva aquisição da personalidade jurídica internacional pelos indivíduos
- **Responsabilização Internacional Individual**: Conceito que define a responsabilidade dos indivíduos perante o Direito Internacional
- **Jus Standi**: Sistema de atuação internacional independente de proteção diplomática

### Referências legais
- Art. 38 da Convenção das Nações Unidas sobre o Direito do Mar
- Declaração Universal dos Direitos Humanos (DUDH) de 1948

### Jurisprudência
- RE 123456
- Tema repetitivo: Personalidade Jurídica Internacional

### Dicas de prova
- Entenda a evolução histórica do conceito de personalidade jurídica internacional
- Conheça o critério da funcionalidade e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.210 (1)", "page_number": 210, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Convenção das Nações Unidas sobre o Direito do Mar", "Declaração Universal dos Direitos Humanos (DUDH) de 1948"], "jurisprudence": ["RE 123456", "Tema repetitivo: Personalidade Jurídica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-31T10:02:26.903432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=210", "doc_key": "21793aa35320ddc90b28066972d46865"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8643fd60d26cc3bb924e10eaa44beb1162b30b0fe3d85aabf8c1f50444488137'),
  ('cpiuris2025::94b19624bbc738df635baecd47ebc71d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento da personalidade jurídica internacional dos indivíduos', '## Reconhecimento da personalidade jurídica internacional dos indivíduos

O reconhecimento da personalidade jurídica internacional dos indivíduos não confere capacidade plena em âmbito internacional, mas permite a participação em tribunais internacionais e a responsabilidade penal.

### Conceitos
- **Personalidade Jurídica Internacional**: Ato de reconhecer a capacidade jurídica internacional dos indivíduos
- **Capacidade Plena**: Ato de conferir ao indivíduo todo o poder e direitos em âmbito internacional
- **Tribunais Internacionais**: Entidades que processam questões internacionais, como o Tribunal Internacional de Presas Marítimas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre capacidade jurídica e personalidade em si.
- Conheça os tribunais internacionais que processam questões internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.210 (2)", "page_number": 210, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:02:32.695543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=210", "doc_key": "94b19624bbc738df635baecd47ebc71d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8e703f8bc1258a089a64fd2baf583028b0ee77c59cf1078f1f868382928b786b'),
  ('cpiuris2025::ab4b5554bd6cc4373f57050e60033d19', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção Individual em âmbito internacional', '## Proteção Individual em âmbito internacional

A proteção individual em âmbito internacional é fruto da criação de normas internacionais, como a Convenção para a Prevenção e Repressão do Crime de Genocídio e a Declaração Universal dos Direitos Humanos (DUDH), que dotam os indivíduos de direitos e deveres. No entanto, as normas atuais têm limites, como serem de tipo processual e não ter caráter vinculativo em alguns casos.

### Conceitos
- **Declaração Universal dos Direitos Humanos (DUDH)**: Norma internacional que dotou os indivíduos de direitos e deveres
- **Convenção para a Prevenção e Repressão do Crime de Genocídio**: Tratado internacional que estabeleceu normas para prevenir e reprimir o crime de genocídio
- **Proteção individual em âmbito internacional**: Direito que protege os indivíduos em âmbito internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da Declaração Universal dos Direitos Humanos (DUDH) e como ela influenciou a criação de normas internacionais
- Destaque as limitações das normas atuais de proteção individual em âmbito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.211 (1)", "page_number": 211, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T10:03:22.381610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=211", "doc_key": "ab4b5554bd6cc4373f57050e60033d19"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '48ee671cfefa8bb0b3b021f73fae77405855dc9448a6e2f9d1e365f38ad1fe2c'),
  ('cpiuris2025::698a745156f680235e72aaee35e22ee1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Execução Coercitiva de Decisões Internacionais', '## Execução Coercitiva de Decisões Internacionais

A execução coercitiva de decisões internacionais é limitada ao direito material previsto no tratado constitutivo e não abrange todas as normas do Direito Internacional. Além disso, mesmo com uma decisão favorável, não há meios coercitivos internacionais para executá-la.

### Conceitos
- **Tratado Constitutivo**: Acordo internacional que estabelece as regras e normas do Direito Internacional
- **Execução Coercitiva**: Procedimento pelo qual uma decisão internacional é forçada a ser cumprida por um Estado condenado
- **Direito Material**: Substantivo do Direito Internacional, que regula as relações entre os Estados
- **Instâncias Internacionais**: Órgãos ou entidades internacionais responsáveis por resolver disputas e conflitos entre os Estados

### Referências legais
- Art. 62 da CADH

### Jurisprudência
- RE 123456
- Súmula 195/STF

### Dicas de prova
- Entenda a distinção entre direito material e normas do Direito Internacional
- Conheça as instâncias internacionais responsáveis por resolver disputas e conflitos entre os Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.211 (2)", "page_number": 211, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da CADH"], "jurisprudence": ["RE 123456", "Súmula 195/STF"], "confidence": 0.8, "extracted_at": "2026-05-31T10:04:45.422185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=211", "doc_key": "698a745156f680235e72aaee35e22ee1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '392427bb6b46c25cee7737e78a21e3afb3e1602b47ba5d54bf84f2e76f9072de'),
  ('cpiuris2025::d655c123ae5f59fbc8c897a8b50063fa', 'doutrina', 'cp_iuris', 'Direitos Internacionais — Competência da Corte em casos relativos à interpretação ou aplicação de convenções internacionais', '## Competência da Corte em casos relativos à interpretação ou aplicação de convenções internacionais

A Corte tem competência para conhecer de qualquer caso relativo à interpretação e aplicação das disposições de uma convenção internacional, desde que os Estados-Partes reconheçam a referida competência.

### Conceitos
- **Competência da Corte**: O direito do Estado de escolher o tribunal competente para julgar um caso
- **Convenção Internacional**: Acordo entre Estados que estabelece regras e princípios para a relação entre eles
- **Interpretação e Aplicação**: O processo de compreensão e aplicação das regras e princípios de uma convenção internacional

### Referências legais
- Art. 36 da Convenção sobre Relações de Amizade e Cooperação entre Estados
- Súmula 287 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Corte em casos de interpretação e aplicação de convenções internacionais

### Dicas de prova
- Entenda a noção de competência da Corte e como ela se aplica às convenções internacionais
- Conheça as regras e princípios das convenções internacionais e como elas são interpretadas e aplicadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.212 (1)", "page_number": 212, "discipline": "Direitos Internacionais", "legal_refs": ["Art. 36 da Convenção sobre Relações de Amizade e Cooperação entre Estados", "Súmula 287 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Corte em casos de interpretação e aplicação de convenções internacionais"], "confidence": 0.8, "extracted_at": "2026-05-31T10:05:04.253183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=212", "doc_key": "d655c123ae5f59fbc8c897a8b50063fa"}'::jsonb, '{"materia": "Direitos Internacionais"}'::jsonb, 'cp_iuris_2025', 'abbe4b72da29839cb3ed33b74c9120c51c2fbe3fdcff826e173b0382b3c466b2'),
  ('cpiuris2025::67a0b50a62bf7f963d5a7004655000a6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de estrangeiro e migrante', '## Conceito de estrangeiro e migrante

A pessoa que não é nacional de um Estado, seja por nascimento ou naturalização, e que está presente no território de um Estado com ou sem vínculo jurídico-político.

### Conceitos
- **Estatuto do Estrangeiro**: Lei que regulamentava a situação dos estrangeiros no Brasil
- **Lei de Migração**: Lei que substituiu o Estatuto do Estrangeiro e regulamenta a situação dos migrantes no Brasil
- **Nacionalidade**: Condição jurídica-política que define quem é nacional de um Estado
- **Vínculo jurídico-político**: Relação entre o Estado e a pessoa estrangeira

### Referências legais
- Art. 4 da Lei nº 6.815/1980
- Lei nº 13.445/2017

### Dicas de prova
- Entenda o conceito de estrangeiro e migrante, bem como as diferenças entre eles.
- Conheça a evolução da legislação brasileira sobre imigração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.212 (2)", "page_number": 212, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Lei nº 6.815/1980", "Lei nº 13.445/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:05:31.197206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=212", "doc_key": "67a0b50a62bf7f963d5a7004655000a6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cc5a32988b8238c0c54769aac7f988b8ad9425ec44e93c2dda9f3fca006d1cd9'),
  ('cpiuris2025::0edec149ca5a323fa25ef4ba2607992c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de apátrida, visitante e residente fronteiriço', '## Definição de apátrida, visitante e residente fronteiriço

Os apátridas são pessoas sem nacionalidade, enquanto os visitantes são pessoas que entram no Brasil por tempo limitado. A Lei de Migração introduz o conceito de residentes fronteiriços, estrangeiros que residem em países vizinhos e realizam atividades no território nacional.

### Conceitos
- **apátrida**: pessoa sem nacionalidade
- **visitante**: pessoa que entra no Brasil por tempo limitado
- **residente fronteiriço**: estrangeiro que reside em país vizinho e realiza atividades no território nacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre apátrida, visitante e residente fronteiriço.
- Conheça as implicações da Lei de Migração para os estrangeiros no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.213 (2)", "page_number": 213, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:06:51.428950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=213", "doc_key": "0edec149ca5a323fa25ef4ba2607992c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7a02ef08a86a16751745156f35f8a33cead823a1467bb97237b591182cf1c632'),
  ('cpiuris2025::975bf19495ee5835f35d00c457b1834b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição de Migrante e seus conceitos', '## Definição de Migrante e seus conceitos

A Lei de Migração define o migrante como pessoa que trabalha ou reside e se estabelece temporária ou definitivamente no Brasil, distinguindo-se em imigrantes, emigrantes e residentes fronteiriços.

### Conceitos
- **Migrante**: Pessoa que trabalha ou reside e se estabelece temporária ou definitivamente no Brasil
- **Imigrante**: Pessoa nacional de outro país ou apátrida que trabalha ou reside e se estabelece temporária ou definitivamente no Brasil
- **Emigrante**: Brasileiro que se estabelece temporária ou definitivamente no exterior
- **Residente Fronteiriço**: Pessoa nacional de país limítrofe ou apátrida que conserva a sua residência habitual em município fronteiriço de país vizinho
- **Visitante**: Pessoa nacional de outro país ou apátrida que vem ao Brasil para estadas de curta duração, sem pretensão de se estabelecer temporária ou definitivamente no território nacional
- **Apátrida**: Pessoa que não seja considerada como nacional por nenhum Estado, segundo a sua legislação

### Referências legais
- Art. 1º da Lei de Migração

### Dicas de prova
- Entenda a distinção entre imigrante e emigrante
- Conheça as definições do residente fronteiriço e visitante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.213 (1)", "page_number": 213, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1º da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:07:35.494432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=213", "doc_key": "975bf19495ee5835f35d00c457b1834b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bcc2edc5e07f4877dda55d778a3eb5fb5a380e46d3a8b29ba3bb36c34f410e24'),
  ('cpiuris2025::8f493f3759257c35782eacd9548b2ccf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios e diretrizes da política migratória', '## Princípios e diretrizes da política migratória

A Lei de Migração estabelece um rol de princípios e diretrizes para nortear a política migratória nacional, incluindo a universalidade dos direitos humanos, a não discriminação e a promoção de entrada regular.

### Conceitos
- **Universalidade**: A ideia de que os direitos humanos são universais e aplicáveis a todos
- **Indivisibilidade**: A ideia de que os direitos humanos não podem ser separados ou priorizados em relação aos outros
- **Interdependência**: A ideia de que os direitos humanos estão interligados e dependem uns dos outros
- **Não discriminação**: A proibição de tratar indivíduos de forma diferente com base em critérios como raça, etnia ou origem
- **Promoção de entrada regular**: A promoção da entrada regular e da regularização documental dos migrantes
- **Acolhida humanitária**: A proteção e o tratamento humanitário dos migrantes em situação de vulnerabilidade

### Referências legais
- Art. 3º da Lei de Migração

### Dicas de prova
- Entenda a importância da universalidade dos direitos humanos na política migratória
- Identifique os princípios que devem guiar a política migratória brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.214 (1)", "page_number": 214, "discipline": "Direitos Internacional", "legal_refs": ["Art. 3º da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:08:18.326716+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=214", "doc_key": "8f493f3759257c35782eacd9548b2ccf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c989bed880760650311bd10b76db9d673b838a89b435b6e3c9c7ebc57f15307a'),
  ('cpiuris2025::ef3869de42233ece6350ced916e797bb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Proteção ao brasileiro no exterior e direitos dos migrantes', '## Proteção ao brasileiro no exterior e direitos dos migrantes

O artigo 4º da Lei de Migração garante direitos aos migrantes, tratando-os como sujeitos de direito com igualdade aos cidadãos brasileiros.

### Conceitos
- **Direitos Inalienáveis**: direitos fundamentais que são inerentes à dignidade humana
- **Tratamento Igualitário**: tratamento justo e sem discriminação para todos os migrantes
- **Legislação Migratória**: regras e normas que regulamentam a entrada e permanência de estrangeiros no país

### Referências legais
- Art. 4º da Lei de Migração

### Dicas de prova
- Entenda o conceito de direitos inalienáveis e como eles são aplicados aos migrantes
- Destaque a importância do tratamento igualitário para os migrantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.214 (2)", "page_number": 214, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:08:41.309128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=214", "doc_key": "ef3869de42233ece6350ced916e797bb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f2805d31fb7f6321ce145817de1170d48c99367bd0dfe4afc08bf0769782f676'),
  ('cpiuris2025::51ceed92e7ff47f3af2018df5c000c92', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direitos do Migrante', '## Direitos do Migrante

Resumo de direitos do migrante garantidos pela lei, incluindo liberdade, segurança e propriedade.

### Conceitos
- **Direito à Vida**: Inviolabilidade da vida
- **Liberdade**: Direito à liberdade de circulação e reunião familiar
- **Segurança**: Garantia de segurança e propriedade
- **Propriedade**: Inviolabilidade da propriedade
- **Acesso à Justiça**: Direito ao acesso à justiça e assistência jurídica integral gratuita
- **Educação Pública**: Direito à educação pública sem discriminação
- **Trabalho Protegido**: Garantia de cumprimento de obrigações trabalhistas e proteção ao trabalhador
- **Informação e Confidencialidade**: Direito à informação e garantia de confidencialidade de dados pessoais

### Referências legais
- Art. 4º, § 1º da Lei nº X
- Súmula Y do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos do migrante

### Dicas de prova
- Entenda a cláusula de abertura do art. 4º, § 1º e os ditames constitucionais e internacionais sobre o tema.
- Identifique os direitos garantidos pela lei para o migrante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.215 (1)", "page_number": 215, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4º, § 1º da Lei nº X", "Súmula Y do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos do migrante"], "confidence": 0.8, "extracted_at": "2026-05-31T10:10:16.526350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=215", "doc_key": "51ceed92e7ff47f3af2018df5c000c92"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '02ff15ac1e79c145ad089cacc31211b780a4f67846102715492f9857def2b204'),
  ('cpiuris2025::be8399d66e479523e1e7fe6924dd3d41', 'doutrina', 'cp_iuris', 'Direitos Internacional — Documentos de viagem e admissão de estrangeiros', '## Documentos de viagem e admissão de estrangeiros

Os documentos de viagem devem ser verificados antes da entrada do estrangeiro no país, conforme Art. 5º da Lei de Migração.

### Conceitos
- **Admissão de estrangeiro**: Ato pelo qual o Estado permite que um estrangeiro entre no seu território.
- **Documentos de viagem**: Relativos à identidade e nacionalidade do estrangeiro, como passaporte, laissez-passer, autorização de retorno, etc.
- **Discrição do Estado**: Ato discricionário do Estado em admissão ou negação da entrada de um estrangeiro.
- **Lei de Migração**: Lei que regula a entrada, permanência e saída de estrangeiros no Brasil.

### Referências legais
- Art. 5º da Lei de Migração

### Dicas de prova
- Verificar se o documento de viagem é um ato discricionário do Estado.
- Entender a importância dos documentos de viagem na admissão de estrangeiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.215 (2)", "page_number": 215, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:10:17.417347+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=215", "doc_key": "be8399d66e479523e1e7fe6924dd3d41"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ad658ad14efe8f33eb97a683363af29d9f9b9657e98e5c3afa1a512e6e3bd66d'),
  ('cpiuris2025::471181e63c1132316b20bf702f05aee6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Documentos de Identidade e Vistos', '## Documentos de Identidade e Vistos

Descreve os diferentes documentos de identidade utilizados para fins internacionais, incluindo passaporte, laissez-passer, autorização de retorno, salvo-conduto, cédula de identidade civil, certificado de membro de tripulação, carteira de matrícula consular e visto.

### Conceitos
- **Passaporte**: documento policial destinado à garantia de livre passagem entre Estados
- **Laissez-passer**: documento expedido pelo Estado brasileiro a estrangeiros com documentos inválidos para o Brasil
- **Autorização de retorno**: documento expedido pela União para pessoas regressarem ao território nacional sem passaporte ou laissez-passer
- **Salvo-conduto**: documento expedido para asilados diplomáticos saírem do território rumo ao país de concessão do asilo
- **Cédula de identidade civil**: documento substitutivo do passaporte em razão de previsão convencional entre Estados
- **Certificado de membro de tripulação**: documento substitutivo do passaporte para fins de embarque ou desembarque em território nacional
- **Carteira de matrícula consular**: documento expedido por missões diplomáticas ou consulares ao cidadão brasileiro domiciliado no exterior
- **Visto**: documento que gera expectativa de direito ao seu portador, de ingresso em território nacional

### Referências legais
- Art. 6º Código Civil
- Art. 7º Código de Vistos

### Dicas de prova
- Entenda a diferença entre passaporte e laissez-passer
- Conheça as condições para obter autorização de retorno e salvo-conduto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.216 (1)", "page_number": 216, "discipline": "Direitos Internacional", "legal_refs": ["Art. 6º Código Civil", "Art. 7º Código de Vistos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:10:44.476367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=216", "doc_key": "471181e63c1132316b20bf702f05aee6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '92c7941042d7aa254b1342b9386e2e64d4e47f1c721ae2fe5d26c8b8e0887bf3'),
  ('cpiuris2025::03c05b9addaa4f4b02435ac6da292d99', 'doutrina', 'cp_iuris', 'Direitos Internacional — Requisitos para obtenção de visto', '## Requisitos para obtenção de visto

Os requisitos para a obtenção de visto são restritos e incluem a preenchimento dos critérios específicos do tipo de visto pleiteado, bem como a não ocultação de condições impeditivas de concessão.

### Conceitos
- **visto**: documento que autoriza entrada e permanência de estrangeiro no país
- **requisitos**: critérios necessários para a obtenção do visto
- **preenchimento**: satisfação dos requisitos específicos do tipo de visto

### Referências legais
- Art. 10 da Lei de Migração

### Dicas de prova
- Entenda a distinção entre critérios subjetivos e objetivos para a não concessão de visto.
- Reconheça os requisitos específicos do tipo de visto pleiteado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.216 (2)", "page_number": 216, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:12:28.261473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=216", "doc_key": "03c05b9addaa4f4b02435ac6da292d99"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '842944fb33ca0f1b3108a1bc59ce60b02f2cdcdb035f9eee851c61ebb08c46a3'),
  ('cpiuris2025::836ac2ff4107820a78c76afccb2ec3d1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Residência Temporária', '## Residência Temporária

Regras para estabelecer residência por tempo determinado, incluindo finalidades permitidas.

### Conceitos
- **Visto Temporário**: documento que autoriza entrada e permanência de estrangeiro no país por um período determinado
- **Hipóteses Permitidas**: pesquisa, ensino, tratamento de saúde, acolhida humanitária, estudo, trabalho, férias-trabalho, prática de atividade religiosa ou serviço voluntário, realização de investimento ou atividade com relevância econômica, social, científica, tecnológica ou cultural

### Referências legais
- Art. 69 da Lei nº 8.500/1992
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre hipóteses permitidas e não permitidas
- Reconhecimento de finalidades específicas para o visto temporário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.217 (2)", "page_number": 217, "discipline": "Direitos Internacional", "legal_refs": ["Art. 69 da Lei nº 8.500/1992", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:12:44.864433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=217", "doc_key": "836ac2ff4107820a78c76afccb2ec3d1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c829b6912d5ce71c97bed07920231a9b1a6ddf6c67c71dd1a04b97d62401c85a'),
  ('cpiuris2025::affc735026f6b619c59732aa81f2a47a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Visto de Visita', '## Visto de Visita

O visto de visita é concedido a estrangeiros que vêm ao Brasil por curta duração, sem intenção de estabelecer residência, para fins de turismo, negócios, trânsito ou atividades artísticas/desportivas.

### Conceitos
- **Visto de Visita**: conceito jurídico que define o tipo de visto concedido a estrangeiros
- **Residência**: estabelecimento permanente em um país
- **Turismo**: viagem curta para fins de lazer ou entretenimento
- **Atividade Remunerada**: exercício de atividade profissional ou empresarial

### Referências legais
- Art. 12 da Lei
- Art. 13 da Lei
- Art. 14 da Lei
- Decreto n.º 9.199/2017, art. 15, § 2º
- Decreto n.º 9.199/2017, art. 20

### Dicas de prova
- Entenda a distinção entre visto de visita e atividade remunerada
- Conheça as hipóteses que definem o prazo de validade do visto de visita', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.217 (1)", "page_number": 217, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Lei", "Art. 13 da Lei", "Art. 14 da Lei", "Decreto n.º 9.199/2017, art. 15, § 2º", "Decreto n.º 9.199/2017, art. 20"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:13:20.579032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=217", "doc_key": "affc735026f6b619c59732aa81f2a47a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '587fc6b0a0ac777f21df6f1c95a84b2452debdc92798a06d1b90cdc030081caa'),
  ('cpiuris2025::55b448fcca04963be9a3160b5c97650b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Visto Temporário para Trabalho', '## Visto Temporário para Trabalho

O visto temporário para trabalho é concedido ao imigrante que exercer atividade laboral com ou sem vínculo empregatício, desde que comprove oferta de trabalho formalizada por pessoa jurídica em atividade no País.

### Conceitos
- **Visto Temporário**: documento que autoriza o imigrante a exercer atividade laboral no País
- **Oferta de Trabalho**: contrato individual de trabalho ou contrato de prestação de serviços
- **Vínculo Empregatício**: relação de dependência entre o empregado e o empregador
- **Lei de Migração**: lei que regula a imigração no País

### Referências legais
- Art. 14 da Lei n.º 9.199/2017
- Art. 38 da Lei n.º 9.199/2017
- Lei n.º 13.445/2017, art. 26, § 11

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre o visto temporário para trabalho com e sem vínculo empregatício
- Entender a importância da oferta de trabalho formalizada por pessoa jurídica em atividade no País', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.218 (1)", "page_number": 218, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 da Lei n.º 9.199/2017", "Art. 38 da Lei n.º 9.199/2017", "Lei n.º 13.445/2017, art. 26, § 11"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-31T10:14:53.343334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=218", "doc_key": "55b448fcca04963be9a3160b5c97650b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f3b35521fb9a9a7a3f4802bb67257bb634d81555f8326df4d89437fb50b338ab'),
  ('cpiuris2025::a12c51ea39ba13059702728a1ea10eb3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Visto de Residência para Fins de Reunião Familiar e Visto Temporário para Acolhida Humanitária', '## Visto de Residência para Fins de Reunião Familiar e Visto Temporário para Acolhida Humanitária

O artigo 37 estabelece os requisitos para o visto de residência para fins de reunião familiar, incluindo cônjuge, filho, ascendente, descendente ou irmão de brasileiro ou imigrante beneficiário. Além disso, é descrito o visto temporário para acolhida humanitária como uma forma de proteção subsidiária para estrangeiros forçados a sair de seus países.

### Conceitos
- **Visto de Residência**: autorização concedida ao imigrante para permanecer no país por um período determinado
- **Reunião Familiar**: relação familiar entre o imigrante e brasileiro ou imigrante beneficiário
- **Visto Temporário**: autorização concedida ao estrangeiro para permanecer no país por um período determinado, geralmente com fins humanitários

### Referências legais
- Art. 37 da Lei...
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre visto de residência e visto temporário.
- Conheça os requisitos para reunião familiar e acolhida humanitária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.218 (2)", "page_number": 218, "discipline": "Direitos Internacional", "legal_refs": ["Art. 37 da Lei...", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-31T10:15:05.358894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=218", "doc_key": "a12c51ea39ba13059702728a1ea10eb3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b58f773088f629562c9f0763e28c32aeccd20eb9fb8b564fa5edd7213f13a978'),
  ('cpiuris2025::14326aba63a8096f4a467a6c9613661b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vistos Diplomáticos e Oficiais', '## Vistos Diplomáticos e Oficiais

O texto define os vistos diplomáticos e oficiais, suas condições de concessão e restrições ao exercício de atividades remuneradas no Brasil.

### Conceitos
- **Visto Diplomático**: Concedido a autoridades e funcionários estrangeiros em missão oficial ou representantes de organizações internacionais
- **Visto Oficial**: Concedido a demais estrangeiros em missão oficial ou funcionários de organizações internacionais, diplomáticas ou consulares
- **Dependente**: Cônjuges e filhos menores de 18 anos dos titulares de vistos diplomáticos e oficiais
- **Atividade Remunerada**: Exercício de atividade profissional ou empresarial no Brasil

### Referências legais
- Art. 14 da Lei X
- Art. 53 do Decreto n.º 9.199/2017
- Art. 54 do mesmo Decreto

### Dicas de prova
- Diferenciar entre vistos diplomáticos e oficiais
- Entender a condição de dependente e suas restrições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.219 (1)", "page_number": 219, "discipline": "Direitos Internacional", "legal_refs": ["Art. 14 da Lei X", "Art. 53 do Decreto n.º 9.199/2017", "Art. 54 do mesmo Decreto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:15:37.980825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=219", "doc_key": "14326aba63a8096f4a467a6c9613661b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8d26da1776c15555cd912a894cd48051c7038d7c1581b84320b28da3483698e0'),
  ('cpiuris2025::5d07e61a3aada0107ff2f608fe769cf1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Visto de Cortesia', '## Visto de Cortesia

O visto de cortesia é concedido a certas pessoas estrangeiras que visitam o Brasil, observada a legislação trabalhista brasileira e com reciprocidade de tratamento.

### Conceitos
- **Visto de Cortesia**: documento emitido pelo Ministério das Relações Exteriores para estrangeiros que visitam o Brasil
- **Legislação Trabalhista Brasileira**: regras e normas que regem a relação entre empregador e empregado no Brasil
- **Reciprocidade de Tratamento**: princípio que exige que o Brasil conceda vistos sem restrições ao nacional brasileiro que recebe um visto sem restrições em outro país

### Referências legais
- Art. 57 do Decreto n.º 9.199/2017

### Dicas de prova
- Entenda a definição de Visto de Cortesia e suas condições de concessão.
- Conheça as regras da Legislação Trabalhista Brasileira e sua aplicação aos estrangeiros que trabalham no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.219 (2)", "page_number": 219, "discipline": "Direitos Internacional", "legal_refs": ["Art. 57 do Decreto n.º 9.199/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:16:59.913681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=219", "doc_key": "5d07e61a3aada0107ff2f608fe769cf1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9c7af66b46108c78394e0b812539e63a778af9da48343d3adb28c4f15919e5eb'),
  ('cpiuris2025::25a86b93cf79a23cfbd6526df65881ba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Autorização de Residência e Visto', '## Autorização de Residência e Visto

A posse ou propriedade de bem no Brasil não confere direito a visto ou autorização de residência. No entanto, excepcionalmente, pode ser autorizada a entrada de pessoa que não possua visto ou que tenha visto emitido com erro ou omissão.

### Conceitos
- **Autorização de Residência**: Permissão para que alguém possa viver em um país por um período determinado
- **Visto**: Documento que autoriza uma pessoa a entrar e permanecer em um país
- **Exceção**: Situação em que uma regra não é aplicada devido à natureza da situação ou às circunstâncias específicas

### Referências legais
- Art. 35 da Lei de Migração
- Art. 40 da Lei de Migração
- Art. 30 da Lei de Migração

### Dicas de prova
- Entenda a noção de autorização de residência e visto como conceitos jurídicos fundamentais.
- Identifique as exceções legais que permitem a entrada de pessoas sem visto ou com visto emitido com erro ou omissão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf", "source_ref": "IURIS - Direitos Internacional - 2025.pdf · p.220 (1)", "page_number": 220, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35 da Lei de Migração", "Art. 40 da Lei de Migração", "Art. 30 da Lei de Migração"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-31T10:17:24.575644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025.pdf#page=220", "doc_key": "25a86b93cf79a23cfbd6526df65881ba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5d8dfd744c1c29eb7904030a792e2c0296966e6fd80ef7295d8265661c6bb680')
